// Content for The Talks, Age by Age (node g64, Parent Layer, Chapter 8): NEW v2 build to GDD 64
// (mechanic-embodying), the KEYSTONE of the Parent Layer and the hinge of the generational loop: a parent guided
// here becomes the trusted adult the kids' journey always assumed. The core reframe: it isn't one dreaded "talk",
// it's many small, age-right conversations, and you can do them. 84 researched, India-grounded scenarios across
// how-to-talk → early-years → middle-years → the-teen-talks → facts-and-values → tools-and-help, each encoded as
// one of the shared v2 play actions (role-play / strike-rewrite / branch / sort / reflect / match / spot): no
// binary "tap the right card". Lead: role-play (say it), strike-rewrite (bust the myth), branch (your move). Six
// modes: how to talk (start early, stay calm, answer "I don't know" honestly, be the askable open door), the early
// years (correct body-part names (which protect against abuse and aid disclosure) body safety & consent basics,
// no body secrets, where-babies-come-from simply, consent in greetings), the middle years (prepare for puberty
// BEFORE it starts, periods and wet dreams for ALL children, online basics & reporting scary content), the teen
// talks (consent, online & porn-literacy against the manosphere, respect in relationships, staying askable through
// the eye-rolls), facts and your values (give honest facts AND share your values rather than choosing between
// them: silence cedes the field to peers and the algorithm), tools & help (age-by-age guides, ready scripts, the
// open-door habit, and routing any child-safety concern to Be the Safe Adult g69). Protective and evidence-based:
// correct names and talking make children SAFER, not more at risk; age-appropriate, accurate, non-explicit
// guidance is expert-reviewed; respects family values while keeping facts honest and NEVER shames a parent for not
// knowing. Builds on (and mirrors) the kids' journey from My Body, My Rules (g02); around it sit the
// positive-parenting pillars (g65-g69). India: these conversations are too often never had, and silence and "log
// kya kahenge" leave the internet and the manosphere to teach instead: the node gently breaks the cycle with
// culturally-aware scripts, mindful of grandparents and joint families. gameId "the-talks".
import type { V2GameConfig, Scenario } from "./v2-schema";

const SCENARIOS: Scenario[] = [
  {"id":"tk-001","cat":"how-to-talk","type":"strike-rewrite","hook":"\"There's one big, dreaded 'talk' you have to get perfectly right.\"","myth":{"un":"There's one big, dreaded 'talk' you have to get perfectly right.","re":"It isn't one talk; it's many small, age-right conversations over years, and you can absolutely do those.","why":"Lots of small chats beat one terrifying lecture."},"relearn":"It's not one big talk; it's many small, age-right conversations over time, and you can do those.","persona":"Vikram","source":"many small talks"},
  {"id":"tk-002","cat":"how-to-talk","type":"strike-rewrite","hook":"\"If I talk to my child about bodies and relationships, I'll encourage them too early.\"","myth":{"un":"If I talk to my child about bodies and relationships, I'll encourage them too early.","re":"Research shows honest, age-appropriate talks lead to later, safer choices, not earlier ones; silence is the real risk.","why":"Talking protects; it doesn't push."},"relearn":"Honest, age-appropriate talks lead to later and safer choices, not earlier ones; talking protects kids.","persona":"Divya","source":"talking protects"},
  {"id":"tk-003","cat":"how-to-talk","type":"branch","hook":"Your child asks a question about bodies and you feel a jolt of panic.","options":[{"text":"Stay calm, answer simply and honestly at their level","consequence":"You stay their go-to source.","outcome":"calm","best":true},{"text":"Get flustered, shut it down or say 'ask later'","consequence":"Staying calm and answering simply keeps you their source; shutting it down sends them to find out elsewhere."}],"debrief":"Meet a child's question calmly and answer simply at their level, rather than shutting it down.","relearn":"Answer kids' body questions calmly and simply; shutting them down just sends them elsewhere.","persona":"Vikram","source":"stay calm"},
  {"id":"tk-004","cat":"how-to-talk","type":"strike-rewrite","hook":"\"If I don't know the answer, I shouldn't say anything at all.\"","myth":{"un":"If I don't know the answer, I shouldn't say anything at all.","re":"'I don't know, let's find out together' is a great answer; it models honesty and keeps the door open.","why":"Not-knowing handled well builds trust."},"relearn":"'I don't know, let's find out together' is a great answer; you don't need every answer ready.","persona":"Divya","source":"I don't know"},
  {"id":"tk-005","type":"match","persona":"any","source":"talk skills","hook":"Match each conversation skill to what it does.","pairs":[{"left":"Staying calm and unshocked","right":"Keeps your child willing to ask"},{"left":"Answering at their level","right":"Makes the answer land"},{"left":"Saying 'great question'","right":"Rewards them for coming to you"},{"left":"'Let's find out together'","right":"Models honesty when you don't know"},{"left":"Many small chats over years","right":"Beats one dreaded big talk"}],"relearn":"Staying calm, answering at their level and welcoming questions keep your child coming to you.","cat":"how-to-talk"},
  {"id":"tk-006","cat":"how-to-talk","type":"reflect","hook":"Lensy: the aim isn't a perfect speech; it's being the askable parent your child keeps coming back to. Sit right?","prompt":"What do you think?","options":["Sits right","Be askable","Keep the door open"],"affirm":"The goal isn't a flawless talk but being the askable, open-door parent a child keeps returning to.","relearn":"The aim is to be the askable parent your child keeps coming back to, not to give a perfect speech.","persona":"any","source":"be askable"},
  {"id":"tk-007","type":"spot","persona":"any","source":"keep them asking","hook":"Spot the two reactions that send a child away instead of keeping them asking.","scene":[{"id":"a","text":"Calm, warm, honest answers","trick":false},{"id":"b","text":"Shock, anger or 'you're too young'","trick":true},{"id":"c","text":"Welcoming even awkward questions","trick":false},{"id":"d","text":"A shaming 'why would you ask that?'","trick":true},{"id":"e","text":"'I'm glad you came to me'","trick":false}],"why":"Shock or 'too young' and a shaming 'why ask that' send a child away; calm, welcoming answers keep them asking.","relearn":"Keep a child asking by answering calmly and welcoming even awkward questions, not by shaming them.","cat":"how-to-talk"},
  {"id":"tk-008","cat":"how-to-talk","type":"branch","hook":"You missed a chance to talk and now feel you've left it too late.","options":[{"text":"Start now; it's never too late to open the conversation","consequence":"You reopen the door at any age.","outcome":"start-now","best":true},{"text":"Decide the window has closed and stay silent","consequence":"Starting now reopens the door at any age; deciding it's too late guarantees the silence you fear."}],"debrief":"It's never too late to start the conversations; begin now rather than deciding the window has closed.","relearn":"Start the talks now whatever your child's age; it's never too late to open the door.","persona":"Divya","source":"never too late"},
  {"id":"tk-009","cat":"how-to-talk","type":"role-play","hook":"Your child asks something about bodies in the middle of a busy moment. You want to honour it.","setup":"Honour the question:","yourLine":[{"text":"\"That's a really good question, let's talk about it properly after dinner, I'll remember.\"","best":true},{"text":"\"Shh, we don't talk about that, especially not here.\""}],"relearn":"Honouring the question, even if you park it briefly, keeps it safe to ask, rather than teaching shame.","persona":"Priya","source":"honour the question"},
  {"id":"tk-010","cat":"how-to-talk","type":"reflect","hook":"Lensy: every calm answer makes the next, harder question easier for your child to ask. Worth it?","prompt":"What's your take?","options":["Worth it","Builds the habit","Yes"],"affirm":"Each calm answer builds the trust that makes the next, harder question easier for your child to bring you.","relearn":"Every calm answer makes the next, harder question easier for your child to ask.","persona":"any","source":"each answer builds"},
  {"id":"tk-011","type":"sort","persona":"any","source":"open vs close","hook":"Sort: an approach that opens the conversation, or one that closes it?","items":[{"id":"a","text":"Honest, calm, age-right answers"},{"id":"b","text":"Shame, panic or avoidance"},{"id":"c","text":"Little chats as they come up"},{"id":"d","text":"Waiting for one perfect big talk"},{"id":"e","text":"Welcoming awkward questions"},{"id":"f","text":"Reacting with shock or anger"}],"bins":[{"id":"opens","label":"Opens it up","valence":"pos"},{"id":"closes","label":"Shuts it down","valence":"neg"}],"key":{"a":"opens","b":"closes","c":"opens","d":"closes","e":"opens","f":"closes"},"relearn":"Honest calm answers and little ongoing chats open the conversation; shame and waiting for one big talk shut it down.","cat":"how-to-talk"},
  {"id":"tk-012","cat":"how-to-talk","type":"role-play","hook":"You feel awkward but want to start a first small conversation with your child. You begin gently.","setup":"Begin gently:","yourLine":[{"text":"\"I want you to know you can always ask me anything about your body or growing up, no question is silly.\"","best":true},{"text":"\"We'll talk about all that when you're much older.\""}],"relearn":"An open invitation that no question is silly starts the lifelong door, even if you feel awkward doing it.","persona":"Vikram","source":"open invitation"},
  {"id":"tk-013","cat":"early-years","type":"strike-rewrite","hook":"\"Teaching little kids the correct names for private body parts is inappropriate.\"","myth":{"un":"Teaching little kids the correct names for private body parts is inappropriate.","re":"Correct names are a protection: children who know them are likelier to be left alone by abusers and to tell clearly if something happens.","why":"Right words are a safety tool, not a loss of innocence."},"relearn":"Teaching correct body-part names protects children; it helps prevent abuse and helps them disclose clearly.","persona":"Divya","source":"correct names protect"},
  {"id":"tk-014","type":"sort","hook":"Sort: a body-safety basic for a young child, or not age-appropriate yet?","items":[{"id":"a","text":"Correct names for body parts"},{"id":"b","text":"Explicit details of sex"},{"id":"c","text":"Private parts are private; safe vs unsafe touch"},{"id":"d","text":"Adult relationship complexities"},{"id":"e","text":"“You're the boss of your own body”"},{"id":"f","text":"Graphic content from the internet"}],"bins":[{"id":"now","label":"Right for young kids","valence":"pos"},{"id":"later","label":"For when older","valence":"uhoh"}],"key":{"a":"now","b":"later","c":"now","d":"later","e":"now","f":"later"},"relearn":"Correct names, safe-vs-unsafe touch and body ownership suit young children; explicit details and adult complexities come much later.","persona":"any","source":"now vs later","cat":"early-years"},
  {"id":"tk-015","type":"match","hook":"Match each early body-safety idea to a simple way to teach it.","pairs":[{"left":"Your body belongs to you","right":"“You're the boss of your own body.”"},{"left":"Private parts are private","right":"“These are just for you, not for others.”"},{"left":"Tell a safe grown-up","right":"“If it feels wrong, tell me, no trouble.”"},{"left":"No body secrets","right":"“No one should ask you to keep a body secret.”"},{"left":"You can say no","right":"“You can say no to a hug, even to family.”"}],"relearn":"Ownership, privacy, telling, no body secrets and 'you can say no' are each taught simply, in a child's words.","persona":"Divya","source":"teach it simply","cat":"early-years"},
  {"id":"tk-016","cat":"early-years","type":"strike-rewrite","hook":"\"Kids should keep 'body secrets' to be polite to adults.\"","myth":{"un":"Kids should keep 'body secrets' to be polite to adults.","re":"Teach that no one should ask them to keep a secret about their body, and they can always say no and tell you.","why":"Body secrets are a grooming red flag."},"relearn":"No one should ask a child to keep a body secret; teach them they can always say no and tell you.","persona":"Divya","source":"no body secrets"},
  {"id":"tk-017","cat":"early-years","type":"branch","hook":"Your little one asks 'where do babies come from?' and you freeze.","options":[{"text":"Give a simple, true answer at their level","consequence":"You satisfy their curiosity honestly.","outcome":"simple-true","best":true},{"text":"Tell a stork-style story or shut it down","consequence":"A made-up story or shutdown teaches the child the topic is off-limits."}],"debrief":"Answer 'where do babies come from?' simply and truthfully at the child's level, not with a myth or a shutdown.","relearn":"Give little kids a simple true answer about where babies come from, not a stork story or silence.","persona":"Vikram","source":"simple true answer"},
  {"id":"tk-018","cat":"early-years","type":"strike-rewrite","hook":"\"Forcing a child to hug relatives teaches good manners.\"","myth":{"un":"Forcing a child to hug relatives teaches good manners.","re":"Letting a child choose how to greet people teaches consent, that their yes and no about their body count.","why":"Bodily choice now builds consent for life."},"relearn":"Letting a child choose whether to hug teaches consent; forcing affection overrides their bodily 'no'.","persona":"Priya","source":"consent in greetings"},
  {"id":"tk-019","cat":"early-years","type":"reflect","hook":"Lensy: 'you're the boss of your body' is consent, taught at age four. Powerful, isn't it?","prompt":"What do you think?","options":["Powerful","Consent early","Love that"],"affirm":"Teaching a small child that they're the boss of their own body plants the roots of consent for life.","relearn":"'You're the boss of your body' is consent taught at age four, the foundation for everything later.","persona":"any","source":"consent at four"},
  {"id":"tk-020","type":"spot","hook":"Spot the two lessons that DON'T keep a young child safer.","scene":[{"id":"a","text":"Knowing correct body-part names","trick":false},{"id":"b","text":"Being told their body isn't theirs to control","trick":true},{"id":"c","text":"Knowing they can always tell you","trick":false},{"id":"d","text":"Being told to keep a body secret to be polite","trick":true},{"id":"e","text":"Knowing private parts are just for them","trick":false}],"why":"Teaching a child their body isn't theirs, or to keep a body secret, removes safety; names, an open door and privacy protect.","relearn":"Safety comes from correct names, an open door and privacy, not from 'your body isn't yours' or 'keep a body secret'.","persona":"Divya","source":"safer early","cat":"early-years"},
  {"id":"tk-021","cat":"early-years","type":"role-play","hook":"Your child proudly uses a correct body-part name and a relative gasps. You want to back your child.","setup":"Back your child calmly:","yourLine":[{"text":"\"Those are just the proper names, we teach them so she stays safe and can tell us things.\"","best":true},{"text":"\"Sorry, sorry, we'll teach her not to say that.\""}],"relearn":"Calmly backing the correct names protects your child's safety tool instead of shaming them into silence.","persona":"Divya","source":"back the names"},
  {"id":"tk-022","cat":"early-years","type":"branch","hook":"A young child says they don't want a certain adult to bathe or touch them.","options":[{"text":"Listen, take it seriously, and respect their 'no'","consequence":"You honour their instincts and safety.","outcome":"respected","best":true},{"text":"Override them because the adult is family","consequence":"Overriding their 'no' teaches them it doesn't count."}],"debrief":"Take a young child's 'no' about their body seriously, even with family; it protects them and teaches consent.","relearn":"Respect a child's 'no' about their body, even toward family; overriding it erodes their safety instinct.","persona":"Priya","source":"respect their no"},
  {"id":"tk-023","cat":"middle-years","type":"strike-rewrite","hook":"\"You should wait until puberty starts to explain puberty.\"","myth":{"un":"You should wait until puberty starts to explain puberty.","re":"Prepare children before the changes begin, ideally by around nine, so periods, wet dreams and body changes never come as a frightening shock.","why":"Forewarned is far less frightening."},"relearn":"Explain puberty before it starts (by around nine) so the changes never come as a frightening shock.","persona":"Divya","source":"prep before puberty"},
  {"id":"tk-024","cat":"middle-years","type":"sort","hook":"Sort: worth covering before puberty hits, or leave for the teen years?","items":[{"id":"a","text":"Periods and wet dreams are normal"},{"id":"b","text":"Body changes that are coming"},{"id":"c","text":"Detailed adult relationship advice"},{"id":"d","text":"Basic online safety and privacy"},{"id":"e","text":"Sweat, hair and mood changes"},{"id":"f","text":"In-depth adult contraception choices"}],"bins":[{"id":"before","label":"Cover before puberty","valence":"pos"},{"id":"later","label":"Later","valence":"uhoh"}],"key":{"a":"before","b":"before","c":"later","d":"before","e":"before","f":"later"},"relearn":"Periods, wet dreams, coming changes and online basics suit pre-puberty; detailed adult advice waits.","persona":"any","source":"before or later"},
  {"id":"tk-025","cat":"middle-years","type":"strike-rewrite","hook":"\"Only girls need to know about periods, and only boys about wet dreams.\"","myth":{"un":"Only girls need to know about periods, and only boys about wet dreams.","re":"All children benefit from understanding everyone's puberty; it builds empathy and ends shame and teasing.","why":"Shared knowledge ends shame."},"relearn":"All children should learn about everyone's puberty, periods and wet dreams alike; it builds empathy and ends shame.","persona":"Priya","source":"everyone learns"},
  {"id":"tk-026","cat":"middle-years","type":"branch","hook":"Your nine-year-old is getting a phone and the online world is opening up.","options":[{"text":"Start simple talks about privacy, kindness and telling you about anything scary","consequence":"You build their online safety net early.","outcome":"online-safe","best":true},{"text":"Hand over the device with no conversation","consequence":"Handing over a device silently leaves them to the internet alone."}],"debrief":"Start simple online-safety talks (privacy, kindness, telling you anything scary) as a child goes online.","relearn":"Pair a first device with simple online-safety talks, not a silent handover.","persona":"Vikram","source":"online basics"},
  {"id":"tk-027","cat":"middle-years","type":"match","hook":"Match each pre-teen topic to a calm way in.","pairs":[{"left":"Periods","right":"\"It's a normal, healthy sign of growing up.\""},{"left":"Wet dreams","right":"\"This happens to bodies, nothing's wrong.\""},{"left":"Online strangers","right":"\"Tell me about anyone who makes you uneasy.\""},{"left":"Body odour","right":"\"Time for a daily wash routine, that's all.\""},{"left":"Growing taller","right":"\"Everyone grows at their own pace.\""}],"relearn":"Periods, wet dreams, online strangers, odour and growth each have a calm, normalising way to open the conversation.","persona":"any","source":"calm ways in"},
  {"id":"tk-028","cat":"middle-years","type":"reflect","hook":"Lensy: a child told about periods before their first one feels prepared, not terrified. Worth it?","prompt":"What do you think?","options":["Worth it","Prepared not scared","Yes"],"affirm":"Preparing a child for puberty before it starts replaces fear and shame with readiness and confidence.","relearn":"A child prepared for puberty before it starts feels ready, not terrified.","persona":"Divya","source":"prepared"},
  {"id":"tk-029","cat":"middle-years","type":"spot","hook":"Spot the two pre-teen messages that would undermine safety and confidence.","scene":[{"id":"a","text":"\"These changes are normal and healthy\"","trick":false},{"id":"b","text":"\"We don't talk about such dirty things\"","trick":true},{"id":"c","text":"\"Tell me about anything online that scares you\"","trick":false},{"id":"d","text":"\"Sort it out yourself, don't bother me\"","trick":true},{"id":"e","text":"\"You can come to me with any worry\"","trick":false}],"why":"\"Dirty things\" and \"sort it out yourself\" shut a child out; normalising changes and inviting them to tell you build safety.","relearn":"Pre-teen safety comes from normalising changes and inviting them to tell you, not from shame.","persona":"any","source":"build safety"},
  {"id":"tk-030","cat":"middle-years","type":"branch","hook":"Your pre-teen mentions something they saw online that clearly unsettled them.","options":[{"text":"Stay calm, thank them for telling you, and talk it through","consequence":"They learn telling you is safe and worth it.","outcome":"safe-telling","best":true},{"text":"React with anger or take the device away as punishment","consequence":"Anger or punishment teaches them to hide it next time."}],"debrief":"When a child reports something unsettling online, stay calm and thank them so they keep telling you.","relearn":"Thank a child for reporting scary content and talk it through; anger teaches them to hide it.","persona":"Vikram","source":"thank them for telling"},
  {"id":"tk-031","cat":"middle-years","type":"role-play","hook":"You want to prepare your daughter for periods, calmly and positively. You bring it up.","setup":"Bring it up warmly:","yourLine":[{"text":"\"Soon your body will start changing and one day you'll get your period, it's normal and I'll help you through it.\"","best":true},{"text":"\"You'll find out about all that when it happens.\""}],"relearn":"A warm, matter-of-fact heads-up makes a first period feel expected and supported, not frightening or shameful.","persona":"Divya","source":"prep for periods"},
  {"id":"tk-032","cat":"middle-years","type":"reflect","hook":"Lensy: the years just before puberty are the golden window, prepared kids handle it so much better. Agree?","prompt":"What's your take?","options":["Agree","Golden window","Prepare them"],"affirm":"The years just before puberty are the ideal window to prepare a child so the changes feel manageable.","relearn":"The years just before puberty are the golden window; prepared kids handle the changes far better.","persona":"any","source":"golden window"},
  {"id":"tk-033","cat":"the-teen-talks","type":"strike-rewrite","hook":"\"Once they're teens and online, it's too late and pointless to talk.\"","myth":{"un":"Once they're teens and online, it's too late and pointless to talk.","re":"Teens still want a trusted adult; staying askable about relationships, consent and online life matters most now.","why":"The door matters more, not less, in the teen years."},"relearn":"Teens still need a trusted adult; staying askable about relationships, consent and online life matters most now.","persona":"Vikram","source":"not too late"},
  {"id":"tk-034","cat":"the-teen-talks","type":"sort","persona":"any","source":"have the talk","hook":"Sort: a teen-years talk worth having, or one to skip?","items":[{"id":"a","text":"What consent really means"},{"id":"b","text":"How online porn distorts real sex and bodies"},{"id":"c","text":"Respect in dating and breakups"},{"id":"d","text":"Nothing, they'll figure it out alone"},{"id":"e","text":"Staying safe with online strangers"},{"id":"f","text":"Leave it to their friends to explain"}],"bins":[{"id":"have","label":"Worth having","valence":"pos"},{"id":"skip","label":"Don't skip the talks","valence":"neg"}],"key":{"a":"have","b":"have","c":"have","d":"skip","e":"have","f":"skip"},"relearn":"Consent, porn-literacy, respect and online safety are worth talking about; leaving teens to 'figure it out alone' or to friends isn't."},
  {"id":"tk-035","cat":"the-teen-talks","type":"strike-rewrite","hook":"\"What teens see online about sex and relationships is a fine substitute for talking to me.\"","myth":{"un":"What teens see online about sex and relationships is a fine substitute for talking to me.","re":"Online content and the manosphere often teach distortion and disrespect; your honest voice is the antidote.","why":"If you stay silent, the algorithm fills the gap."},"relearn":"Online content often distorts sex and respect; if you stay silent the algorithm teaches instead, so your voice matters.","persona":"Vikram","source":"your voice is the antidote"},
  {"id":"tk-036","cat":"the-teen-talks","type":"branch","hook":"Your teen rolls their eyes and says they 'already know everything' about relationships.","options":[{"text":"Stay warm and open, sharing your view without lecturing","consequence":"You stay a resource they'll quietly use.","outcome":"open","best":true},{"text":"Lecture or give up because they resist","consequence":"Lecturing or quitting closes the door."}],"debrief":"With an eye-rolling teen, stay warm and open and share without lecturing; you remain a quiet resource.","relearn":"Stay open and non-lecturing with a resistant teen; that keeps you a resource even through the eye-rolls.","persona":"Vikram","source":"through the eye-rolls"},
  {"id":"tk-037","cat":"the-teen-talks","type":"match","persona":"any","source":"respectful openers","hook":"Match each teen topic to an opener that respects them.","pairs":[{"left":"Consent","right":"\"Both people freely wanting it, every time, matters.\""},{"left":"Online porn","right":"\"A lot of it isn't real; let's talk about what is.\""},{"left":"A first relationship","right":"\"I'm here, no judgement, whenever you want to talk.\""},{"left":"A breakup","right":"\"This hurts, and I'm right here with you.\""},{"left":"Online strangers","right":"\"People aren't always who they claim. Show me.\""}],"relearn":"Consent, porn-literacy, first relationships, breakups and online strangers each have a respectful opener that keeps a teen listening."},
  {"id":"tk-038","cat":"the-teen-talks","type":"reflect","hook":"Lensy: a teen who can come to you about sex and relationships is a safer teen. Feel the stakes?","prompt":"What do you think?","options":["Feel it","Safer teen","Worth staying open"],"affirm":"A teen who can bring you questions about sex and relationships is safer than one left to the internet.","relearn":"A teen who can come to you about sex and relationships is a safer teen.","persona":"any","source":"safer teen"},
  {"id":"tk-039","cat":"the-teen-talks","type":"strike-rewrite","hook":"\"Talking to my teen about consent will give them ideas.\"","myth":{"un":"Talking to my teen about consent will give them ideas.","re":"Teaching consent gives them respect and safety, not ideas; it's among the most protective talks you can have.","why":"Consent knowledge protects, never encourages."},"relearn":"Teaching a teen consent gives them respect and safety, not 'ideas'; it's a deeply protective talk.","persona":"Vikram","source":"consent protects"},
  {"id":"tk-040","cat":"the-teen-talks","type":"spot","persona":"any","source":"safe and connected","hook":"Spot the two things that push a teen away and online.","scene":[{"id":"a","text":"Honest, non-judgemental conversations","trick":false},{"id":"b","text":"Shaming them about bodies or crushes","trick":true},{"id":"c","text":"Being a calm, askable resource","trick":false},{"id":"d","text":"Punishing them for asking questions","trick":true},{"id":"e","text":"Welcoming hard questions without judgement","trick":false}],"why":"Shaming them and punishing questions push a teen away and online; honest talks and being askable keep them connected.","relearn":"Shaming a teen and punishing their questions push them away and online; honest, askable parenting keeps them connected."},
  {"id":"tk-041","cat":"the-teen-talks","type":"role-play","hook":"Your teen asks something about sex that catches you off guard. You want to stay open.","setup":"Stay open and honest:","yourLine":[{"text":"\"Good question, I'm glad you asked me, here's what I know, and let's find out the rest together.\"","best":true},{"text":"\"Where did you hear that? You shouldn't be thinking about this.\""}],"relearn":"Welcoming a tough teen question, and finding answers together, keeps you their trusted source over the internet.","persona":"Vikram","source":"stay open teen"},
  {"id":"tk-042","cat":"the-teen-talks","type":"reflect","hook":"Lensy: every awkward, honest teen talk is a small vote for them trusting you over the algorithm. Worth it?","prompt":"What's your take?","options":["Worth it","Over the algorithm","Keep talking"],"affirm":"Each honest teen conversation builds the trust that keeps your child coming to you rather than the algorithm.","relearn":"Every honest teen talk is a vote for them trusting you over the algorithm.","persona":"any","source":"over the algorithm"},
  {"id":"tk-043","cat":"facts-and-values","type":"strike-rewrite","hook":"\"I have to choose between honest facts and my family's values.\"","myth":{"un":"I have to choose between honest facts and my family's values.","re":"You can give accurate facts and share your values; kids can hold both, the facts to stay safe and your values to guide them.","why":"Facts and values are partners, not rivals."},"relearn":"You don't choose between honest facts and your values; give both, the facts for safety and your values to guide.","persona":"Vikram","source":"facts and values"},
  {"id":"tk-044","cat":"facts-and-values","type":"sort","hook":"Sort: an honest fact every child needs, or a value you choose to share?","items":[{"id":"a","text":"How bodies work and how to stay safe"},{"id":"b","text":"What your family believes about timing"},{"id":"c","text":"Accurate names and basic health facts"},{"id":"d","text":"Your hopes and guidance for them"},{"id":"e","text":"What consent is and how to ask for it"},{"id":"f","text":"The faith and traditions you cherish"}],"bins":[{"id":"facts","label":"Honest facts","valence":"pos"},{"id":"values","label":"Your values","valence":"tell"}],"key":{"a":"facts","b":"values","c":"facts","d":"values","e":"facts","f":"values"},"relearn":"Body facts, consent and safety are honest facts every child needs; timing, hopes and traditions are values you share.","persona":"any","source":"facts vs values"},
  {"id":"tk-045","cat":"facts-and-values","type":"strike-rewrite","hook":"\"Withholding facts will keep my child innocent and safe.\"","myth":{"un":"Withholding facts will keep my child innocent and safe.","re":"Missing facts make children more vulnerable, not safer; honest information plus your values is what truly protects them.","why":"Knowledge is a shield, not a threat."},"relearn":"Withholding facts makes children more vulnerable; honest information plus your values protects them.","persona":"Divya","source":"facts protect"},
  {"id":"tk-046","cat":"facts-and-values","type":"branch","hook":"Your values differ from some facts your child needs, and you're unsure how to handle it.","options":[{"text":"Share the facts honestly and add your values as your view","consequence":"Your child gets safety and your guidance both.","outcome":"both","best":true},{"text":"Hide the facts to enforce the values","consequence":"Hiding facts leaves your child unsafe, and they'll likely find out anyway."}],"debrief":"Give the honest facts and share your values as your perspective; don't hide facts to enforce values.","relearn":"Offer honest facts and your values together; hiding facts just leaves a child unsafe.","persona":"Vikram","source":"both together"},
  {"id":"tk-047","cat":"facts-and-values","type":"match","hook":"Match each tricky moment to a facts-plus-values response.","pairs":[{"left":"'What does that word mean?'","right":"Define it simply, then share your view"},{"left":"'When is it okay to date?'","right":"Give the facts, then your family's values"},{"left":"'My friend has a boyfriend'","right":"Discuss respect and safety, and your hopes"},{"left":"'Why do people do that?'","right":"Honest answer first, then what we believe"},{"left":"'Is that normal?'","right":"Reassure with facts, add your guidance"}],"relearn":"Each tricky question gets honest facts first, then your family's values, so a child has both safety and guidance.","persona":"any","source":"facts plus values"},
  {"id":"tk-048","cat":"facts-and-values","type":"reflect","hook":"Lensy: your child can know the facts to stay safe and still carry the values you raise them with. Resonate?","prompt":"What do you think?","options":["Resonates","Both at once","That works"],"affirm":"Children can hold accurate facts for safety alongside the values their family raises them with; it isn't either/or.","relearn":"Your child can know the facts to stay safe and carry your values too; it's not either/or.","persona":"any","source":"hold both"},
  {"id":"tk-049","cat":"facts-and-values","type":"strike-rewrite","hook":"\"If I stay silent on values, my child won't be influenced by anyone.\"","myth":{"un":"If I stay silent on values, my child won't be influenced by anyone.","re":"If you don't share your values, peers, media and the algorithm will fill the gap; your voice belongs in the mix.","why":"Silence cedes the field to everyone else."},"relearn":"Silence on values doesn't keep a child neutral; peers and the algorithm fill the gap, so share your voice.","persona":"Vikram","source":"share your voice"},
  {"id":"tk-050","cat":"facts-and-values","type":"spot","hook":"Spot the two approaches that leave a child exposed, not protected.","scene":[{"id":"a","text":"Honest facts plus your shared values","trick":false},{"id":"b","text":"Silence and hoping for the best","trick":true},{"id":"c","text":"Open conversation, no shame","trick":false},{"id":"d","text":"Letting the feed teach instead of you","trick":true},{"id":"e","text":"Answering questions calmly and truthfully","trick":false}],"why":"Silence and ceding to the feed leave a child exposed; honest facts, shared values and open, calm talk protect them.","relearn":"Children are protected best by honest facts plus shared values and open talk, not by silence or the feed.","persona":"any","source":"protects best"},
  {"id":"tk-051","cat":"facts-and-values","type":"reflect","hook":"Lensy: breaking the family silence doesn't betray your culture; it lets you pass on the best of it. Sit right?","prompt":"What's your take?","options":["Sits right","Pass on the best","Not a betrayal"],"affirm":"Breaking the silence around these topics lets parents pass on their values intentionally, rather than ceding them.","relearn":"Breaking the silence doesn't betray your culture; it lets you pass on the best of it, on purpose.","persona":"any","source":"pass it on"},
  {"id":"tk-052","cat":"tools-and-help","type":"branch","hook":"You want to actually feel ready for the questions instead of caught off guard.","options":[{"text":"Keep a few simple, age-right scripts ready for the common questions","consequence":"You answer with calm confidence.","outcome":"scripted","best":true},{"text":"Wing every question and hope you don't freeze","consequence":"Winging every question risks the freeze that shuts kids down."}],"debrief":"Keep a few simple, age-right scripts ready so common questions don't catch you off guard.","relearn":"Ready a few age-right scripts; winging every hard question invites the freeze that closes the door.","persona":"Divya","source":"ready scripts"},
  {"id":"tk-053","cat":"tools-and-help","type":"match","hook":"Match each tool to what it gives a parent.","pairs":[{"left":"Age-by-age guides","right":"What to cover, and when"},{"left":"Ready scripts","right":"Words when you're caught off guard"},{"left":"The open-door habit","right":"A child who keeps coming to you"},{"left":"Learning alongside them","right":"Answers you didn't have before"},{"left":"The safeguarding route","right":"Help when a worry is about safety"}],"relearn":"Age-by-age guides, ready scripts, the open-door habit, learning alongside and the safeguarding route are the core tools of guiding a child's RSE.","persona":"any","source":"the toolkit"},
  {"id":"tk-054","cat":"tools-and-help","type":"strike-rewrite","hook":"\"My own gaps and embarrassment mean I can't guide my child at all.\"","myth":{"un":"My own gaps and embarrassment mean I can't guide my child at all.","re":"You can learn alongside your child; nobody starts an expert, and your willingness matters more than perfect knowledge.","why":"Willingness beats expertise."},"relearn":"Your own gaps don't disqualify you; you can learn alongside your child, and willingness matters more than expertise.","persona":"Vikram","source":"learn alongside"},
  {"id":"tk-055","cat":"tools-and-help","type":"sort","hook":"Sort: a green-flag move for guiding your child, or one to rethink?","items":[{"id":"a","text":"Many small, calm, honest talks"},{"id":"b","text":"One panicked lecture, then silence"},{"id":"c","text":"Learning the facts you're unsure of"},{"id":"d","text":"Shaming questions away"},{"id":"e","text":"Repairing it when you get one wrong"},{"id":"f","text":"Pretending you never heard the question"}],"bins":[{"id":"green","label":"Green-flag move","valence":"pos"},{"id":"rethink","label":"Rethink it","valence":"neg"}],"key":{"a":"green","b":"rethink","c":"green","d":"rethink","e":"green","f":"rethink"},"relearn":"Small calm talks, learning the facts and repairing fumbles are green flags; a panicked lecture, shaming and ignoring questions need a rethink.","persona":"any","source":"green or rethink"},
  {"id":"tk-056","cat":"tools-and-help","type":"branch","hook":"A question or comment from your child makes you worried about their safety.","options":[{"text":"Take it seriously and seek safeguarding guidance and support","consequence":"You act on a possible warning sign.","outcome":"safeguard","best":true},{"text":"Brush it off so you don't have to deal with it","consequence":"Brushing it off can miss real harm."}],"debrief":"If something your child says worries you for their safety, take it seriously and seek safeguarding guidance (see Be the Safe Adult).","relearn":"Act on a child-safety worry by taking it seriously and seeking guidance; don't brush it off.","persona":"Meena","source":"safeguard route"},
  {"id":"tk-057","cat":"tools-and-help","type":"reflect","hook":"Lensy: the scripts you give your child are the ones you may never have got yourself, and that's the cycle breaking. Feel it?","prompt":"What do you think?","options":["Feel it","Cycle breaking","Giving what I missed"],"affirm":"Giving your child the words and openness you may never have received is exactly how the silence cycle breaks.","relearn":"The scripts you give your child are the ones you never got; that's the cycle breaking.","persona":"any","source":"cycle breaking"},
  {"id":"tk-058","cat":"tools-and-help","type":"spot","hook":"Spot the two moves that aren't sustainable, among the ways that guide a child's RSE for years.","scene":[{"id":"a","text":"Ongoing small talks as they grow","trick":false},{"id":"b","text":"One big talk and never again","trick":true},{"id":"c","text":"Staying askable for years","trick":false},{"id":"d","text":"Waiting till you feel fully expert","trick":true},{"id":"e","text":"Answering questions as they come up","trick":false}],"why":"'One big talk and done' and 'wait till you're an expert' are the red flags.","relearn":"Guiding a child's RSE is ongoing small talks and an open door over years, not one big talk or waiting to feel expert.","persona":"any","source":"sustainable guidance"},
  {"id":"tk-059","cat":"tools-and-help","type":"match","hook":"Match a parent's worry to the reassuring tool.","pairs":[{"left":"'I'll freeze on a hard question'","right":"A ready, simple script"},{"left":"'I don't know enough'","right":"Learn it together, age by age"},{"left":"'Something my child said worries me'","right":"Safeguarding guidance (Be the Safe Adult)"},{"left":"'I already fumbled one answer'","right":"Go back and repair it"},{"left":"'I'm doing this all alone'","right":"Invite your co-parent to be askable too"}],"relearn":"Each parent worry has a tool: a script, learning together, safeguarding guidance, repairing a fumble, or inviting a co-parent in.","persona":"any","source":"worry to tool"},
  {"id":"tk-060","cat":"tools-and-help","type":"reflect","hook":"Lensy: the goal isn't one perfect talk. It's staying the askable parent across hundreds of small moments. Land for you?","prompt":"What's your take?","options":["Lands","Stay askable","Many small moments"],"affirm":"There is no single perfect talk; what protects a child is a parent who stays approachable across many small everyday moments.","relearn":"It was never one big talk. It's staying the parent your child can come back to, over and over.","persona":"any","source":"the long game"},
  {"id":"tk-061","cat":"tools-and-help","type":"role-play","hook":"Your co-parent feels too awkward to take part in the talks. You want to bring them in.","setup":"Bring them in gently:","yourLine":[{"text":"\"Let's do this together, even just being calm and askable matters, our kids need both of us.\"","best":true},{"text":"\"Fine, I'll handle all the awkward stuff myself then.\""}],"relearn":"Inviting a co-parent to simply be calm and askable shares the job and doubles a child's trusted doors.","persona":"Vikram","source":"bring co-parent in"},
  {"id":"tk-062","cat":"how-to-talk","type":"role-play","hook":"Your child asks a blunt question in front of guests and everyone goes quiet. You want to handle it gracefully.","setup":"Handle it gracefully:","yourLine":[{"text":"\"Great question, let's chat about it together a bit later, I'll give you a proper answer.\"","best":true},{"text":"\"Don't be rude, we'll never discuss that.\""}],"relearn":"A graceful park-it-for-later keeps the question safe to ask without shaming the child in front of others.","persona":"Priya","source":"graceful in public"},
  {"id":"tk-063","cat":"how-to-talk","type":"branch","hook":"You realise you tend to over-explain and overwhelm your child with too much at once.","options":[{"text":"Answer just what they asked, simply, and let them come back for more","consequence":"Your child takes it in and keeps asking.","outcome":"right-sized","best":true},{"text":"Deliver a long, anxious lecture","consequence":"An anxious lecture overwhelms and deters."}],"debrief":"Answer just the question asked, simply, and let your child come back for more, rather than over-explaining.","relearn":"Answer the actual question simply; over-explaining overwhelms a child and closes the door.","persona":"Vikram","source":"right-sized answers"},
  {"id":"tk-064","cat":"early-years","type":"role-play","hook":"Your four-year-old points and asks what a body part is called. You want to answer plainly.","setup":"Answer plainly:","yourLine":[{"text":"\"That's called a penis (or vulva), it's just the proper name, like elbow or knee.\"","best":true},{"text":"\"We don't say that word, it's rude.\""}],"relearn":"Naming body parts as plainly as elbows removes shame and gives a child the words that keep them safe.","persona":"Divya","source":"name it plainly"},
  {"id":"tk-065","cat":"early-years","type":"role-play","hook":"You want to teach your young child the 'safe grown-up' rule simply. You explain it.","setup":"Explain it simply:","yourLine":[{"text":"\"If anyone touches your private parts or asks you to keep a body secret, tell me, you'll never be in trouble.\"","best":true},{"text":"\"Just be good and do what grown-ups say.\""}],"relearn":"A clear 'tell me, you'll never be in trouble' rule gives a child permission to disclose, unlike 'obey grown-ups'.","persona":"Divya","source":"safe grown-up rule"},
  {"id":"tk-066","type":"sort","hook":"Sort: teaches a young child body safety, or accidentally undermines it?","items":[{"id":"a","text":"‘You can say no to unwanted touch’"},{"id":"b","text":"‘Always let elders hug and kiss you’"},{"id":"c","text":"‘Tell me anything, no secrets about bodies’"},{"id":"d","text":"‘Good kids never refuse adults’"},{"id":"e","text":"‘Your body belongs to you’"},{"id":"f","text":"‘Keep this just between us, don't tell’"}],"bins":[{"id":"safety","label":"Builds safety","valence":"pos"},{"id":"undermine","label":"Undermines it","valence":"neg"}],"key":{"a":"safety","b":"undermine","c":"safety","d":"undermine","e":"safety","f":"undermine"},"relearn":"'Say no', 'no body secrets' and 'your body is yours' build safety; 'always let elders', 'never refuse adults' and 'keep this secret' undermine it.","persona":"any","source":"safety or not","cat":"early-years"},
  {"id":"tk-067","type":"match","hook":"Match each young-child question to a simple, honest answer.","pairs":[{"left":"'Why is my body different from my sibling's?'","right":"Bodies come in different kinds, both are normal"},{"left":"'What's that for?'","right":"A calm, correct, one-line answer"},{"left":"'Can I say no to a hug?'","right":"Yes, your body is yours"},{"left":"'Where do babies come from?'","right":"A simple, true answer at your level"},{"left":"'Is it okay to feel curious?'","right":"Yes, and you can always ask me"}],"relearn":"Young children's body questions each have a simple, honest, shame-free answer that keeps them curious and safe.","persona":"Priya","source":"honest little answers","cat":"early-years"},
  {"id":"tk-068","cat":"middle-years","type":"role-play","hook":"Your pre-teen seems embarrassed about body changes. You want to normalise it warmly.","setup":"Normalise it warmly:","yourLine":[{"text":"\"Everything that's happening to your body is normal and healthy, and you can ask me anything, anytime.\"","best":true},{"text":"\"You're too sensitive about all this.\""}],"relearn":"Warmly normalising the changes and inviting questions replaces embarrassment with reassurance.","persona":"Divya","source":"normalise changes"},
  {"id":"tk-069","cat":"middle-years","type":"sort","hook":"Sort: a healthy pre-teen online habit to encourage, or a risk to address?","items":[{"id":"a","text":"Telling you about anything that feels off"},{"id":"b","text":"Sharing private info with strangers"},{"id":"c","text":"Keeping passwords and privacy"},{"id":"d","text":"Meeting online 'friends' alone"},{"id":"e","text":"Asking before downloading new apps"},{"id":"f","text":"Posting their location for all to see"}],"bins":[{"id":"encourage","label":"Encourage it","valence":"pos"},{"id":"address","label":"Address the risk","valence":"neg"}],"key":{"a":"encourage","b":"address","c":"encourage","d":"address","e":"encourage","f":"address"},"relearn":"Telling you, keeping privacy and asking first are healthy; sharing info, meeting strangers and open location are risks.","persona":"Vikram","source":"encourage or address"},
  {"id":"tk-070","cat":"middle-years","type":"branch","hook":"Your pre-teen asks a frank question about sex, earlier than you expected.","options":[{"text":"Answer honestly and age-appropriately, without shame","consequence":"You keep trust and give safe, true info.","outcome":"honest","best":true},{"text":"Act scandalised and refuse to answer","consequence":"Acting scandalised teaches them not to ask you again."}],"debrief":"Answer an earlier-than-expected frank question honestly and age-appropriately, without shame.","relearn":"Answer frank pre-teen questions honestly and without shame; being scandalised just sends them elsewhere.","persona":"Divya","source":"answer honestly"},
  {"id":"tk-071","cat":"middle-years","type":"spot","hook":"Spot the two moves that leave a pre-teen unprepared for the years ahead.","scene":[{"id":"a","text":"Honest prep before changes and online life","trick":false},{"id":"b","text":"Leaving them to learn from peers and feeds","trick":true},{"id":"c","text":"An open door for any worry","trick":false},{"id":"d","text":"Saying nothing until problems show up","trick":true},{"id":"e","text":"Pairing a first phone with safety chats","trick":false}],"why":"Leaving them to peers/feeds and staying silent until problems hit leave a child exposed; honest prep and an open door ready them.","relearn":"Prepare a pre-teen with honest prep and an open door, not by leaving them to peers and the feed.","persona":"any","source":"best prep"},
  {"id":"tk-072","cat":"the-teen-talks","type":"role-play","hook":"Your teen asks about something explicit they saw online. You want to stay unflustered.","setup":"Stay unflustered:","yourLine":[{"text":"\"Thanks for asking me, a lot of that isn't how real life or real respect works, let's talk about what is.\"","best":true},{"text":"\"That's disgusting, I don't want to hear another word.\""}],"relearn":"Meeting an explicit question with calm porn-literacy keeps you the trusted source over the algorithm.","persona":"Vikram","source":"unflustered teen"},
  {"id":"tk-073","cat":"the-teen-talks","type":"role-play","hook":"Your teen is being pressured by a partner and confides in you. You want to support, not control.","setup":"Support, not control:","yourLine":[{"text":"\"I'm really glad you told me, no one should pressure you, what do you want to do, and how can I help?\"","best":true},{"text":"\"That's it, you're not seeing them again, end of discussion.\""}],"relearn":"Supporting their agency while offering help keeps a pressured teen talking to you, unlike taking over.","persona":"Vikram","source":"support not control"},
  {"id":"tk-074","cat":"the-teen-talks","type":"sort","persona":"any","source":"come or hide","hook":"Sort: keeps a teen coming to you, or pushes them to hide things?","items":[{"id":"a","text":"Calm, non-judgemental listening"},{"id":"b","text":"Punishing them for honesty"},{"id":"c","text":"Respecting their growing autonomy"},{"id":"d","text":"Snooping and shaming"},{"id":"e","text":"Thanking them for telling you hard things"},{"id":"f","text":"Threatening to tell the whole family"}],"bins":[{"id":"comes","label":"Keeps them coming","valence":"pos"},{"id":"hides","label":"Makes them hide","valence":"neg"}],"key":{"a":"comes","b":"hides","c":"comes","d":"hides","e":"comes","f":"hides"},"relearn":"Calm listening, respecting autonomy and thanking them keep a teen coming to you; punishing honesty, snooping and threats make them hide."},
  {"id":"tk-075","cat":"the-teen-talks","type":"branch","hook":"Your teen makes a choice about relationships you disagree with.","options":[{"text":"Stay connected and share your view while keeping the door open","consequence":"You keep influence and their trust.","outcome":"connected","best":true},{"text":"Issue ultimatums that end the conversation","consequence":"Ultimatums end the conversation and your sway with it."}],"debrief":"Stay connected and share your view on a teen's choice while keeping the door open, rather than issuing ultimatums.","relearn":"Keep the door open on choices you dislike; ultimatums cost you both influence and trust.","persona":"Vikram","source":"keep the door open"},
  {"id":"tk-076","cat":"facts-and-values","type":"role-play","hook":"Your child asks something where your values are strong. You want to give facts and your view honestly.","setup":"Give both honestly:","yourLine":[{"text":"\"Here's how it actually works, and here's what we believe about it in our family, both matter.\"","best":true},{"text":"\"Never mind the facts, just do as we say.\""}],"relearn":"Pairing the honest facts with your stated values gives a child both safety and your guidance to weigh.","persona":"Vikram","source":"both honestly"},
  {"id":"tk-077","cat":"facts-and-values","type":"sort","hook":"Sort: an honest fact a child needs for safety, or a value you choose to share?","items":[{"id":"a","text":"How conception and contraception work"},{"id":"b","text":"When your family feels is the right time"},{"id":"c","text":"Consent and how to stay safe"},{"id":"d","text":"Your hopes for their relationships"},{"id":"e","text":"What a healthy, respectful body is owed"},{"id":"f","text":"The role you hope marriage plays one day"}],"bins":[{"id":"fact","label":"Safety fact","valence":"pos"},{"id":"value","label":"Shared value","valence":"tell"}],"key":{"a":"fact","b":"value","c":"fact","d":"value","e":"fact","f":"value"},"relearn":"How bodies, consent and respect work are safety facts; the 'right time' and your hopes are values you choose to share.","persona":"any","source":"fact or value"},
  {"id":"tk-078","cat":"facts-and-values","type":"sort","hook":"Sort: protects a child, or leaves them exposed?","items":[{"id":"a","text":"Honest facts plus your values"},{"id":"b","text":"Silence to 'protect innocence'"},{"id":"c","text":"An open, shame-free door"},{"id":"d","text":"Letting the feed teach instead"},{"id":"e","text":"Answering questions calmly and truthfully"},{"id":"f","text":"Shutting down a question with anger"}],"bins":[{"id":"protects","label":"Protects them","valence":"pos"},{"id":"exposed","label":"Leaves them exposed","valence":"neg"}],"key":{"a":"protects","b":"exposed","c":"protects","d":"exposed","e":"protects","f":"exposed"},"relearn":"Honest facts with values, an open door and calm answers protect; silence, the feed and anger leave a child exposed.","persona":"any","source":"protect or expose"},
  {"id":"tk-079","cat":"facts-and-values","type":"branch","hook":"You worry that giving facts will clash with what grandparents want kept quiet.","options":[{"text":"Give your child the safety facts while respecting elders kindly","consequence":"Your child stays informed and safe.","outcome":"informed","best":true},{"text":"Withhold facts to keep the peace at home","consequence":"Withholding the facts for peace leaves your child unsafe."}],"debrief":"Give your child the safety facts they need while handling elders kindly; don't withhold them to keep the peace.","relearn":"Prioritise your child's safety facts over keeping the silence elders prefer; do it kindly, but do it.","persona":"Vikram","source":"facts over silence"},
  {"id":"tk-080","cat":"facts-and-values","type":"match","hook":"Match a values-laden question to a both-and reply.","pairs":[{"left":"'Is it wrong to want that?'","right":"Here are the facts; here's what we believe"},{"left":"'Everyone's doing it'","right":"Let's separate facts from pressure, and our values"},{"left":"'Why can't I yet?'","right":"The honest reasons, plus our family's view"},{"left":"'You're being old-fashioned'","right":"Fair, here's the fact and why we still feel it"},{"left":"'My friends are allowed'","right":"Their facts may differ; here's ours and our values"}],"relearn":"Values-laden questions each get a both-and reply: honest facts first, then your family's view.","persona":"any","source":"both-and replies"},
  {"id":"tk-081","cat":"tools-and-help","type":"role-play","hook":"You froze on a question yesterday and want to go back and repair it. You reopen it.","setup":"Reopen it warmly:","yourLine":[{"text":"\"I didn't answer you well yesterday, I was caught off guard, let's talk about it properly now.\"","best":true},{"text":"\"Let's just forget you ever asked that.\""}],"relearn":"Going back to repair a fumbled answer models honesty and shows your child the door is genuinely always open.","persona":"Divya","source":"repair a fumble"},
  {"id":"tk-082","cat":"tools-and-help","type":"sort","hook":"Sort: a realistic, sustainable parenting-talk habit, or an unrealistic one?","items":[{"id":"a","text":"Tiny talks in the car or at bedtime"},{"id":"b","text":"One scheduled formal lecture"},{"id":"c","text":"Answering as questions arise"},{"id":"d","text":"Waiting until you feel fully expert"},{"id":"e","text":"Using everyday cues to start"},{"id":"f","text":"Cramming everything into a single talk"}],"bins":[{"id":"real","label":"Realistic habit","valence":"pos"},{"id":"unreal","label":"Unrealistic","valence":"neg"}],"key":{"a":"real","b":"unreal","c":"real","d":"unreal","e":"real","f":"unreal"},"relearn":"Tiny everyday talks, answering as questions arise and using cues are realistic; a formal lecture, waiting to feel expert and cramming aren't.","persona":"any","source":"realistic habit"},
  {"id":"tk-083","cat":"tools-and-help","type":"spot","hook":"Spot the two moves that make a parent less askable, among the ones that build trust over time.","scene":[{"id":"a","text":"Welcoming questions without shame","trick":false},{"id":"b","text":"Reacting with anger or panic","trick":true},{"id":"c","text":"Repairing when you get one wrong","trick":false},{"id":"d","text":"Mocking a question as silly","trick":true},{"id":"e","text":"Thanking them for coming to you","trick":false}],"why":"Anger or panic and mocking a question are the red flags that make you less askable.","relearn":"Become more askable by welcoming questions, repairing missteps and thanking them, not by reacting with anger or mocking.","persona":"any","source":"more askable"},
  {"id":"tk-084","cat":"tools-and-help","type":"match","hook":"Match each age to the headline focus of the talks.","pairs":[{"left":"Around 3-6","right":"Correct names, body safety, consent basics"},{"left":"Around 9-12","right":"Prepare for puberty and online life"},{"left":"13+","right":"Consent, online-literacy, respect in relationships"},{"left":"Any age, after a fumble","right":"Repair it and reopen the door"},{"left":"Any age, a safety worry","right":"Route to help and take it seriously"}],"relearn":"Each age has a headline focus: body safety young, puberty prep before, consent in the teens, plus repair and routing worries at any age.","persona":"any","source":"age to focus"},
  {"id":"tk-900","type":"strike-rewrite","persona":"Divya","source":"names aren't dirty","hook":"“Using pet names like 'susu-place' keeps it innocent; real names sound dirty.”","myth":{"un":"Using pet names for private parts keeps it innocent; real names sound dirty.","re":"Real names aren't dirty. They let a child describe clearly what happened and who touched where.","why":"A clear word is a safety tool; a vague pet name can hide a disclosure."},"relearn":"Pet names can blur a disclosure; correct names let a child say clearly what happened, which keeps them safer.","cat":"early-years"},
  {"id":"tk-901","type":"strike-rewrite","persona":"Priya","source":"curiosity is normal","hook":"“A young child who touches their own body or asks about it is misbehaving.”","myth":{"un":"A young child who touches their own body or asks about it is misbehaving.","re":"Body curiosity is normal at this age; calmly teach privacy ('that's something we do in private') without shame.","why":"Shaming normal curiosity teaches secrecy, which makes a child less safe, not more."},"relearn":"Body curiosity is normal; redirect to privacy calmly instead of shaming, so a child stays open with you.","cat":"early-years"},
  {"id":"tk-902","type":"strike-rewrite","persona":"any","source":"no exception for family","hook":"“Safe-touch rules are for strangers; you don't need them for family.”","myth":{"un":"Safe-touch rules are for strangers; you don't need them for family.","re":"Most who harm a child are known to them, so the same rules apply to everyone, family included.","why":"'Stranger danger' alone leaves a child unprotected from the people they actually meet."},"relearn":"Safe-touch rules apply to everyone a child knows, not just strangers. 'Stranger danger' alone isn't enough.","cat":"early-years"},
  {"id":"tk-903","type":"strike-rewrite","persona":"any","source":"start small not at school","hook":"“Body-safety talk can wait until school teaches it.”","myth":{"un":"Body-safety talk can wait until school teaches it.","re":"Start at home, in tiny everyday moments, like bath time or getting dressed, long before any class covers it.","why":"A child needs these words before they ever face a situation, not after."},"relearn":"Body safety starts at home in small everyday moments, well before school covers it. Don't outsource it.","cat":"early-years"},
  {"id":"tk-904","type":"strike-rewrite","persona":"Divya","source":"private not shameful","hook":"“Telling a child their private parts are 'private' will make them feel ashamed of their body.”","myth":{"un":"Calling private parts 'private' will make a child feel ashamed of their body.","re":"'Private' means just-for-you, like a diary. It's about boundaries, not shame, and you can say it warmly.","why":"Framed as a boundary, not a flaw, privacy protects without teaching disgust."},"relearn":"'Private' means just-for-you, a boundary not a shame. Framed warmly it protects a child without disgust.","cat":"early-years"},
  {"id":"tk-905","type":"strike-rewrite","persona":"Priya","source":"tickling counts too","hook":"“If a child laughs while being tickled, it can't be unwanted touch.”","myth":{"un":"If a child laughs while being tickled, it can't be unwanted touch.","re":"A laugh can be a reflex, not a yes. If they say 'stop', stop, so they learn their 'stop' is always honoured.","why":"Honouring 'stop' even in play is how a child learns their no counts everywhere."},"relearn":"A laugh isn't consent. Stopping a tickle when a child says 'stop' teaches them their no is always honoured.","cat":"early-years"},
  {"id":"tk-906","type":"strike-rewrite","persona":"any","source":"boys need it too","hook":"“Body-safety and consent talks are really only needed for daughters.”","myth":{"un":"Body-safety and consent talks are really only needed for daughters.","re":"Boys are harmed too and grow into the adults who must respect a no. Every child needs both.","why":"Skipping sons leaves them unprotected and unprepared to respect others."},"relearn":"Body-safety and consent are for every child, not only daughters. Sons are harmed too and must learn to respect a no.","cat":"early-years"},
  {"id":"tk-907","type":"strike-rewrite","persona":"Divya","source":"repeat not once","hook":"“Once I've told my child the safe-touch rule, the job is done.”","myth":{"un":"Once I've told my child the safe-touch rule, the job is done.","re":"Little ones forget; revisit it lightly and often, like 'look both ways', until it's simply known.","why":"Repetition over years is what makes a safety rule stick at this age."},"relearn":"Safe-touch isn't a one-time talk. Revisit it lightly and often until it's as automatic as looking both ways.","cat":"early-years"},
  {"id":"tk-908","type":"strike-rewrite","persona":"any","source":"answer beats silence","hook":"“If I just ignore my child's body question, they'll forget they asked.”","myth":{"un":"If I ignore my child's body question, they'll forget they asked.","re":"They won't forget. They'll learn you're not the place to ask and take the question elsewhere.","why":"Silence doesn't end curiosity; it just redirects it away from you."},"relearn":"Ignoring a body question doesn't end it. It teaches a child to ask someone, or something, less safe than you.","cat":"early-years"},
  {"id":"tk-909","type":"strike-rewrite","persona":"Priya","source":"feelings have a no","hook":"“Making a child finish a kiss for grandma is just teaching respect.”","myth":{"un":"Making a child finish a kiss for grandma is just teaching respect.","re":"Offer a choice, like a hug, wave or high-five, so respect and a child's bodily 'no' both get to be real.","why":"Forcing affection teaches a child their body's no can be overruled by a grown-up."},"relearn":"Let a child pick how to greet, like a hug, wave or high-five, so they learn respect without losing the right to say no.","cat":"early-years"},
  {"id":"tk-910","type":"strike-rewrite","persona":"Divya","source":"calm keeps the door","hook":"“Acting shocked when my toddler says a body word will teach them not to say it.”","myth":{"un":"Acting shocked when my toddler says a body word will teach them not to say it.","re":"Shock teaches the word is dangerous and you're not safe to ask. Stay calm and just name it plainly.","why":"A calm face keeps you the person they bring the next, bigger thing to."},"relearn":"Reacting with shock teaches a child the topic is unsafe with you. A calm, plain answer keeps the door open.","cat":"early-years"},
  {"id":"tk-911","type":"sort","persona":"any","source":"safe vs unsafe touch","hook":"Sort each touch as one a young child can flag as safe, or one to tell about.","items":[{"id":"a","text":"A doctor checking you with a parent in the room"},{"id":"b","text":"Someone touching your private parts"},{"id":"c","text":"A hug you said yes to"},{"id":"d","text":"Being asked to keep a touch secret"},{"id":"e","text":"A high-five from a friend"},{"id":"f","text":"A touch that makes you feel 'uh-oh' inside"}],"bins":[{"id":"safe","label":"Safe touch","valence":"pos"},{"id":"tell","label":"Tell a grown-up","valence":"tell"}],"key":{"a":"safe","b":"tell","c":"safe","d":"tell","e":"safe","f":"tell"},"relearn":"Wanted hugs, high-fives and a checkup with a parent are safe; private-part touches, 'keep it secret' and an 'uh-oh' feeling are ones to tell about.","cat":"early-years"},
  {"id":"tk-912","type":"sort","persona":"Divya","source":"now vs later names","hook":"Sort: a body fact a four-year-old is ready for, or one for when they're older?","items":[{"id":"a","text":"The correct name for each private part"},{"id":"b","text":"How pregnancy actually happens"},{"id":"c","text":"Private parts are covered by swimwear"},{"id":"d","text":"What contraception is"},{"id":"e","text":"Everyone's body is a bit different"},{"id":"f","text":"The mechanics of sex"}],"bins":[{"id":"now","label":"Ready now","valence":"pos"},{"id":"later","label":"For later","valence":"uhoh"}],"key":{"a":"now","b":"later","c":"now","d":"later","e":"now","f":"later"},"relearn":"Correct names, the swimwear rule and 'bodies differ' fit a four-year-old; how pregnancy happens, contraception and the mechanics of sex come later.","cat":"early-years"},
  {"id":"tk-913","type":"sort","persona":"any","source":"who is a safe grown-up","hook":"Sort: a 'safe grown-up' a young child could tell, or not a good safety pick?","items":[{"id":"a","text":"A parent or guardian"},{"id":"b","text":"A grown-up who told them to keep a secret"},{"id":"c","text":"A trusted teacher"},{"id":"d","text":"Anyone who gives them sweets"},{"id":"e","text":"A grandparent they feel easy with"},{"id":"f","text":"Whoever says 'don't tell your parents'"}],"bins":[{"id":"safe","label":"A safe grown-up","valence":"pos"},{"id":"no","label":"Not a safe pick","valence":"neg"}],"key":{"a":"safe","b":"no","c":"safe","d":"no","e":"safe","f":"no"},"relearn":"A parent, trusted teacher or easy grandparent are safe grown-ups; anyone wanting secrets, bribing with sweets or saying 'don't tell your parents' is not.","cat":"early-years"},
  {"id":"tk-914","type":"sort","persona":"Divya","source":"good answer vs not","hook":"Sort a reply to a toddler's body question: keeps the door open, or closes it?","items":[{"id":"a","text":"“Great question! That's called a vulva.”"},{"id":"b","text":"“That's rude, don't ask that.”"},{"id":"c","text":"“I don't know. Let's find out together.”"},{"id":"d","text":"“You're too little to know.”"},{"id":"e","text":"“Let's talk about it after lunch.”"},{"id":"f","text":"“We never talk about that here.”"}],"bins":[{"id":"open","label":"Keeps door open","valence":"pos"},{"id":"shut","label":"Closes the door","valence":"neg"}],"key":{"a":"open","b":"shut","c":"open","d":"shut","e":"open","f":"shut"},"relearn":"Naming it calmly, 'let's find out' and 'let's talk after lunch' keep the door open; 'that's rude', 'too little' and 'we never talk about that' close it.","cat":"early-years"},
  {"id":"tk-915","type":"sort","persona":"any","source":"consent moments","hook":"Sort each everyday moment: it can teach a young child consent, or it overrides it?","items":[{"id":"a","text":"Letting them choose a hug or a wave"},{"id":"b","text":"Forcing a kiss for a relative"},{"id":"c","text":"Asking before you tickle them"},{"id":"d","text":"Making them sit on a lap they shrink from"},{"id":"e","text":"Pausing a game when they say stop"},{"id":"f","text":"Telling them their no doesn't count with family"}],"bins":[{"id":"teach","label":"Teaches consent","valence":"pos"},{"id":"over","label":"Overrides it","valence":"neg"}],"key":{"a":"teach","b":"over","c":"teach","d":"over","e":"teach","f":"over"},"relearn":"Offering a choice, asking before tickling and pausing at 'stop' teach consent; a forced kiss, a forced lap or 'your no doesn't count' override it.","cat":"early-years"},
  {"id":"tk-916","type":"sort","persona":"Priya","source":"red flag or normal","hook":"Sort what a child reports: a normal moment, or an 'uh-oh' to take seriously?","items":[{"id":"a","text":"“Auntie hugged me, it was nice.”"},{"id":"b","text":"“He touched me and said don't tell.”"},{"id":"c","text":"“My friend and I played tag.”"},{"id":"d","text":"“Uncle says our game is our secret.”"},{"id":"e","text":"“The doctor checked my ear today.”"},{"id":"f","text":"“Someone showed me a scary picture.”"}],"bins":[{"id":"ok","label":"Normal","valence":"pos"},{"id":"uhoh","label":"Take seriously","valence":"uhoh"}],"key":{"a":"ok","b":"uhoh","c":"ok","d":"uhoh","e":"ok","f":"uhoh"},"relearn":"A wanted hug, tag and an ear check are normal; a 'don't tell' touch, a 'secret game' and a scary picture are 'uh-oh' reports to take seriously.","cat":"early-years"},
  {"id":"tk-917","type":"sort","persona":"Vikram","source":"underwear rule","hook":"Sort: fits the simple 'underwear rule' for a young child, or doesn't belong in it?","items":[{"id":"a","text":"Parts under your swimsuit are private"},{"id":"b","text":"You must obey every adult, always"},{"id":"c","text":"No one should ask to see or touch them"},{"id":"d","text":"Keep nice secrets and bad secrets alike"},{"id":"e","text":"If someone tries, tell a safe grown-up"},{"id":"f","text":"It's your fault if something happens"}],"bins":[{"id":"in","label":"Part of the rule","valence":"pos"},{"id":"out","label":"Doesn't belong","valence":"neg"}],"key":{"a":"in","b":"out","c":"in","d":"out","e":"in","f":"out"},"relearn":"The underwear rule: private parts are private, no one may ask to see or touch them, and you tell a safe grown-up. It's never your fault.","cat":"early-years"},
  {"id":"tk-918","type":"sort","persona":"Divya","source":"feelings name it","hook":"Sort each body-feeling word a young child can learn to name, or one that isn't a feeling?","items":[{"id":"a","text":"Safe and comfy"},{"id":"b","text":"The colour blue"},{"id":"c","text":"An 'uh-oh' tummy feeling"},{"id":"d","text":"The number seven"},{"id":"e","text":"Squirmy and wanting to leave"},{"id":"f","text":"A type of fruit"}],"bins":[{"id":"feel","label":"A body-feeling","valence":"pos"},{"id":"not","label":"Not a feeling","valence":"neutral"}],"key":{"a":"feel","b":"not","c":"feel","d":"not","e":"feel","f":"not"},"relearn":"Naming body-feelings, like safe, an 'uh-oh' tummy, or squirmy, helps a child notice and flag unsafe touch; colours, numbers and fruit aren't feelings.","cat":"early-years"},
  {"id":"tk-919","type":"match","persona":"Divya","source":"name each part","hook":"Match each gentle teaching moment to the correct, plain word to use.","pairs":[{"left":"Bath time, washing","right":"“We wash your vulva and your bottom.”"},{"left":"Getting dressed","right":"“Underwear covers your private parts.”"},{"left":"A scrape near the groin","right":"“Let's clean near your penis.”"},{"left":"Pointing at a picture","right":"“That's a belly button, this is a nipple.”"},{"left":"A toddler's question","right":"“Those are the proper names, like elbow.”"}],"relearn":"Everyday moments, like bath, dressing, a scrape, a picture, or a question, are all chances to use the plain, correct word with no fuss.","cat":"early-years"},
  {"id":"tk-920","type":"match","persona":"any","source":"rule to reason","hook":"Match each body-safety rule to the simple reason a young child can grasp.","pairs":[{"left":"Private parts are private","right":"They're just for you, not for others"},{"left":"No body secrets","right":"Secrets about bodies aren't safe to keep"},{"left":"You can say no","right":"Your body belongs to you"},{"left":"Tell a safe grown-up","right":"They'll help and you won't be in trouble"},{"left":"Trust the 'uh-oh' feeling","right":"It warns you something isn't right"}],"relearn":"Each rule pairs with a child-sized reason: privacy, no body secrets, your body is yours, telling helps, and the 'uh-oh' feeling is a warning.","cat":"early-years"},
  {"id":"tk-921","type":"match","persona":"Priya","source":"calm reply scripts","hook":"Match each tricky toddler question to a calm one-line reply.","pairs":[{"left":"'Why is mummy's body different?'","right":"“Grown-up and child bodies differ.”"},{"left":"'What's a period?'","right":"“A normal thing many bodies do.”"},{"left":"'Why can't I be naked outside?'","right":"“Private parts stay private in public.”"},{"left":"'Did I grow in your tummy?'","right":"“Yes, in a place called the womb.”"},{"left":"'Can boys have long hair?'","right":"“Yes, hair's for everyone.”"}],"relearn":"Each toddler question has a calm, true one-liner ready: no perfect speech needed, just a plain honest answer.","cat":"early-years"},
  {"id":"tk-922","type":"match","persona":"any","source":"safe vs unsafe sort","hook":"Match each touch a young child might meet to whether it's safe or one to tell about.","pairs":[{"left":"A hug you wanted","right":"A safe touch"},{"left":"A touch on a private part","right":"Tell a safe grown-up"},{"left":"A doctor checking, parent present","right":"A safe, okay touch"},{"left":"A 'keep it secret' touch","right":"Tell, even if asked not to"},{"left":"A high-five from a pal","right":"A friendly, safe touch"}],"relearn":"Wanted hugs, a parent-present checkup and a high-five are safe; private-part touches and 'keep it secret' touches are always ones to tell about.","cat":"early-years"},
  {"id":"tk-923","type":"match","persona":"Divya","source":"feeling to action","hook":"Match each body-feeling a young child notices to what they can do about it.","pairs":[{"left":"Feeling safe and happy","right":"Enjoy it, you're okay"},{"left":"An 'uh-oh' tummy feeling","right":"Move away and tell someone"},{"left":"Squirmy, wanting to leave","right":"You're allowed to say 'stop'"},{"left":"Confused by what an adult did","right":"Ask a safe grown-up about it"},{"left":"Scared to tell a secret","right":"Tell anyway, you won't be in trouble"}],"relearn":"A child can pair each feeling with an action: enjoy safe, move away from 'uh-oh', say stop when squirmy, ask when confused, and tell even scary secrets.","cat":"early-years"},
  {"id":"tk-924","type":"match","persona":"Vikram","source":"good answer model","hook":"Match each parent move to what it teaches a young child.","pairs":[{"left":"Answering calmly, no fuss","right":"This topic is safe to ask about"},{"left":"Using the correct names","right":"My body has real, plain words"},{"left":"Respecting their 'no' to a hug","right":"My body belongs to me"},{"left":"Saying 'tell me anything'","right":"I won't get in trouble for telling"},{"left":"Admitting 'I'll find out'","right":"Not knowing is okay"}],"relearn":"Each calm parent move teaches a lesson: the topic is safe, bodies have real words, my body is mine, telling is safe, and not-knowing is fine.","cat":"early-years"},
  {"id":"tk-925","type":"match","persona":"any","source":"myth to truth","hook":"Match each common worry to the reassuring early-years truth.","pairs":[{"left":"'Correct names sound dirty'","right":"They're a protection, like elbow or knee"},{"left":"'Talking gives them ideas'","right":"It makes them safer, not earlier"},{"left":"'They're too young for this'","right":"Body safety starts around age four"},{"left":"'Only girls need consent talks'","right":"Every child needs them"},{"left":"'School will handle it'","right":"It starts at home, in small moments"}],"relearn":"Each worry has a calm truth: names protect, talking makes kids safer, it starts at four, every child needs it, and it begins at home.","cat":"early-years"},
  {"id":"tk-926","type":"match","persona":"Priya","source":"where babies come from","hook":"Match each age-step of 'where do babies come from?' to a simple true answer.","pairs":[{"left":"First, simplest version","right":"“Babies grow in a special place inside.”"},{"left":"'How does it get out?'","right":"“Through an opening, or by surgery.”"},{"left":"'How does it start?'","right":"“From a tiny cell from two grown-ups.”"},{"left":"If you don't know what to say","right":"“Good question! Let's find out.”"},{"left":"What never to say","right":"A stork story or 'don't ask that'"}],"relearn":"'Where do babies come from?' builds in simple true steps: grows inside, comes out a real way, starts from two cells.","cat":"early-years"},
  {"id":"tk-927","type":"branch","persona":"Divya","source":"toddler in the supermarket","hook":"In a busy shop your three-year-old loudly asks, 'What's a penis?'","options":[{"text":"Answer calmly and quietly, then move on","consequence":"The word stays normal; you're safe to ask.","outcome":"calm","best":true},{"text":"Shush them: 'we don't say that'","consequence":"The word feels shameful; they stop telling you.","outcome":"shush"},{"text":"Laugh and change the subject fast","consequence":"It feels awkward; they learn to ask elsewhere.","outcome":"dodge"}],"debrief":"A calm, quiet, plain answer keeps you askable; shushing or dodging teaches the topic is shameful.","relearn":"Answer a loud public body question calmly and plainly. Shushing or dodging teaches it's shameful.","cat":"early-years"},
  {"id":"tk-928","type":"branch","persona":"Priya","source":"relative gasps at the word","hook":"Your child says 'vulva' at lunch and your mother-in-law looks horrified.","options":[{"text":"Calmly say you teach proper names for safety","consequence":"You back your child; safety words stay.","outcome":"back","best":true},{"text":"Apologise, promise to stop 'those words'","consequence":"A safety tool dropped for comfort.","outcome":"apologise"},{"text":"Scold your child for embarrassing you","consequence":"They learn the right word means trouble.","outcome":"scold"}],"debrief":"Calmly backing the names protects your child; apologising or scolding trades safety for comfort.","relearn":"Back the proper names calmly when a relative gasps. Don't apologise them away or scold.","cat":"early-years"},
  {"id":"tk-929","type":"branch","persona":"any","source":"child resists a relative","hook":"At a party your child clings to you and won't go to an uncle who wants a hug.","options":[{"text":"Let them choose a wave instead, no pressure","consequence":"You honour their instinct; their no counts.","outcome":"respect","best":true},{"text":"Push them forward so uncle isn't hurt","consequence":"An adult's feelings outrank their body.","outcome":"push"},{"text":"Bribe them with a sweet to go hug","consequence":"Affection gets traded for treats.","outcome":"bribe"}],"debrief":"Respecting a child's 'no', even with family, protects them; pushing or bribing overrules it.","relearn":"Let a child choose a wave over a hug, even with family. Pushing or bribing overrules their bodily no.","cat":"early-years"},
  {"id":"tk-930","type":"branch","persona":"Meena","source":"child hints at a secret","hook":"Your child says, 'Uncle and I have a secret game I can't tell.'","options":[{"text":"Stay calm, say no body secrets, gently ask more","consequence":"They keep talking; you can check they're safe.","outcome":"calm","best":true},{"text":"Panic and fire off questions","consequence":"They get scared, tell you less.","outcome":"panic"},{"text":"Say 'that's nice', let it go","consequence":"You miss a possible grooming sign.","outcome":"dismiss"}],"debrief":"Stay calm, reaffirm 'no body secrets', ask more; panic or dismissing fail. If worried, Childline 1098.","relearn":"A hinted 'secret game' can be a grooming sign. Stay calm, reaffirm no body secrets and ask gently; don't brush it off.","cat":"early-years"},
  {"id":"tk-931","type":"branch","persona":"Vikram","source":"caught looking at bodies","hook":"You find your five-year-old and a friend curiously comparing bodies.","options":[{"text":"Stay calm, redirect to a game, later mention privacy","consequence":"Curiosity stays normal; privacy matters.","outcome":"calm","best":true},{"text":"Shout and shame them both","consequence":"They learn bodies are dirty and they're in trouble.","outcome":"shame"},{"text":"Pretend you saw nothing","consequence":"You miss a chance to teach privacy.","outcome":"ignore"}],"debrief":"Normal curiosity is best met by calmly redirecting and later teaching privacy; shaming teaches disgust.","relearn":"Met with calm and a later privacy chat, body curiosity stays normal; shouting teaches disgust.","cat":"early-years"},
  {"id":"tk-932","type":"branch","persona":"Divya","source":"you fumbled the answer","hook":"You snapped 'don't ask that!' at a body question and your child went quiet.","options":[{"text":"Go back, say sorry, answer it properly","consequence":"You model repair; the door is open again.","outcome":"repair","best":true},{"text":"Decide it's done, never revisit it","consequence":"They keep learning the topic is off-limits.","outcome":"leave"},{"text":"Hope they ask someone else","consequence":"They take questions to less safe sources.","outcome":"deflect"}],"debrief":"Going back to repair a fumble reopens the door and models honesty; leaving it locks the topic away.","relearn":"You can repair a fumble. Go back, apologise and answer; leaving it teaches the topic is off-limits.","cat":"early-years"},
  {"id":"tk-933","type":"branch","persona":"any","source":"child says it hurt","hook":"Your young child says a touch from someone 'felt yucky and hurt.'","options":[{"text":"Stay calm, believe them, thank them, ask gently","consequence":"They feel safe and keep talking.","outcome":"believe","best":true},{"text":"Say 'you must have imagined it'","consequence":"They learn telling is pointless.","outcome":"doubt"},{"text":"Get furious they didn't stop it","consequence":"They feel blamed and shut down.","outcome":"blame"}],"debrief":"Stay calm, believe, thank and ask. Doubt or blame teaches silence. If someone hurt your child, Childline 1098.","relearn":"If a child says a touch hurt, stay calm, believe and thank them. Doubt or blame teaches silence. Childline 1098 helps.","cat":"early-years"},
  {"id":"tk-934","type":"branch","persona":"Priya","source":"co-parent disagrees","hook":"Your partner says teaching a four-year-old about 'private parts' is 'too soon.'","options":[{"text":"Share it's age-right, agree a plan","consequence":"You become two aligned, askable doors.","outcome":"align","best":true},{"text":"Drop it to avoid an argument","consequence":"Your child loses age-right safety words.","outcome":"drop"},{"text":"Teach it secretly, behind their back","consequence":"Mixed messages split the parenting.","outcome":"secret"}],"debrief":"Aligning with a co-parent doubles a child's doors; dropping it leaves them less protected.","relearn":"Bring a hesitant co-parent on board. Two aligned parents double a child's doors; dropping it leaves them exposed.","cat":"early-years"},
  {"id":"tk-935","type":"reflect","persona":"any","source":"named at four","hook":"Lensy: teaching 'you're the boss of your own body' at age four plants consent for life.","prompt":"How does that land for you?","options":["Powerful","Never thought of it that way","I can do that"],"affirm":"Telling a small child they're the boss of their own body is the first, deepest root of consent, and you're already planting it.","relearn":"'You're the boss of your own body', taught at four, is the foundation of consent for life.","cat":"early-years"},
  {"id":"tk-936","type":"reflect","persona":"Divya","source":"raised in silence","hook":"Lensy: many of us were raised never hearing the real words. None of that is your fault.","prompt":"What comes up for you?","options":["A bit sad","Determined to change it","Relieved to hear that"],"affirm":"Being raised in silence isn't a failing of yours, and choosing to do it differently for your child is something to be proud of.","relearn":"Being raised in silence isn't your fault; choosing to talk openly with your own child is something to be proud of.","cat":"early-years"},
  {"id":"tk-937","type":"reflect","persona":"any","source":"small talks not one","hook":"Lensy: it's not one dreaded 'talk' to get perfect, just many tiny, age-right chats.","prompt":"Does that feel more doable?","options":["Much less scary","Yes, I can do small","Still nervous but okay"],"affirm":"There's no big speech to nail: just lots of small, calm moments, and every one you manage already counts.","relearn":"It's not one dreaded 'talk': just many small, age-right chats, and you can do them.","cat":"early-years"},
  {"id":"tk-938","type":"reflect","persona":"Priya","source":"calm face matters","hook":"Lensy: your calm face is the safety net. It tells a child you're safe to come to.","prompt":"How do you feel about that?","options":["Reassuring","A lot rides on it","I'll practise staying calm"],"affirm":"You don't need perfect words. A calm face is enough to tell your child you're the safe place to bring anything.","relearn":"A calm, unshocked face keeps you the person your child brings the next, bigger thing to.","cat":"early-years"},
  {"id":"tk-939","type":"reflect","persona":"any","source":"i don't know is fine","hook":"Lensy: 'I don't know, but let's find out together' is a great, honest answer.","prompt":"What do you make of that?","options":["Such a relief","Takes the pressure off","I'll use that"],"affirm":"You don't have to know everything. Willingness to find out together teaches your child more than any expert ever could.","relearn":"'I don't know, but let's find out together' is a good, honest answer; willingness beats expertise.","cat":"early-years"},
  {"id":"tk-940","type":"reflect","persona":"Divya","source":"protection not innocence","hook":"Lensy: correct names aren't a loss of innocence. They're a shield you hand your child.","prompt":"How does that sit with you?","options":["Reframes it for me","Makes sense","I feel braver about it"],"affirm":"Teaching the real words isn't taking childhood away. It's giving your child a tool that helps keep them safe.","relearn":"Correct names aren't a loss of innocence. They're a protection you hand your child.","cat":"early-years"},
  {"id":"tk-941","type":"reflect","persona":"any","source":"door you are building","hook":"Lensy: every calm little answer makes the next, harder question easier for them to ask.","prompt":"What does that stir in you?","options":["Hopeful","Worth the effort","I see the long game"],"affirm":"Each small calm answer is a brick in a door your child keeps coming back through. You're building it already.","relearn":"Every calm little answer makes the next, harder question easier for your child to ask.","cat":"early-years"},
  {"id":"tk-942","type":"spot","persona":"Divya","source":"catch the shaming lines","hook":"Spot the two replies to a body question that shut a child down.","scene":[{"id":"a","text":"“Great question! That's the proper name.”","trick":false},{"id":"b","text":"“That's a dirty thing to ask.”","trick":true},{"id":"c","text":"“I don't know, let's find out.”","trick":false},{"id":"d","text":"“Good children don't ask that.”","trick":true},{"id":"e","text":"“Let's talk about it after lunch.”","trick":false}],"why":"'That's dirty' and 'good children don't ask' shame a child into silence; the others keep the door open with a calm, honest answer.","relearn":"Calm, honest replies keep the door open; 'that's dirty' and 'good children don't ask' shame a child into taking questions elsewhere.","cat":"early-years"},
  {"id":"tk-943","type":"spot","persona":"any","source":"catch the grooming lines","hook":"Spot the two things an adult might say that a child should always tell you about.","scene":[{"id":"a","text":"“Your parents know I'm here today.”","trick":false},{"id":"b","text":"“This is our secret, don't tell.”","trick":true},{"id":"c","text":"“Let's stay where mum can see us.”","trick":false},{"id":"d","text":"“If you tell, you'll be in big trouble.”","trick":true},{"id":"e","text":"“You can stop any time you like.”","trick":false}],"why":"'Our secret, don't tell' and 'you'll be in trouble if you tell' are grooming red flags to report; the others are safe.","relearn":"'Keep this secret' and 'you'll be in trouble if you tell' are grooming red flags to report. Open 'you can stop' talk is safe.","cat":"early-years"},
  {"id":"tk-944","type":"spot","persona":"any","source":"catch the unsafe rules","hook":"Spot the two 'rules' that actually make a young child less safe.","scene":[{"id":"a","text":"You can say no to unwanted touch","trick":false},{"id":"b","text":"Always do what any grown-up says","trick":true},{"id":"c","text":"Tell me anything, no body secrets","trick":false},{"id":"d","text":"Never question or refuse an elder","trick":true},{"id":"e","text":"Your body belongs to you","trick":false}],"why":"'Obey any grown-up' and 'never refuse an elder' strip a child's ability to refuse harm; the others build real safety.","relearn":"'Obey every grown-up' and 'never refuse an elder' make a child less safe; 'you can say no', 'no body secrets' and 'your body is yours' protect.","cat":"early-years"},
  {"id":"tk-945","type":"spot","persona":"Priya","source":"catch overriding consent","hook":"Spot the two moments that override a young child's bodily 'no'.","scene":[{"id":"a","text":"Letting them wave instead of hug","trick":false},{"id":"b","text":"Forcing a kiss for a relative","trick":true},{"id":"c","text":"Asking before tickling them","trick":false},{"id":"d","text":"Making them sit on a lap they shrink from","trick":true},{"id":"e","text":"Stopping a game when they say stop","trick":false}],"why":"Forcing a kiss and a shrunk-from lap override a child's no; offering a wave, asking first and stopping at 'stop' teach consent.","relearn":"Forcing a kiss or a shrunk-from lap overrides a child's no; offering a wave, asking before tickling and stopping at 'stop' teach consent.","cat":"early-years"},
  {"id":"tk-946","type":"spot","persona":"Divya","source":"catch wrong-time facts","hook":"Spot the two things that are NOT age-right for a four-year-old.","scene":[{"id":"a","text":"The correct names for private parts","trick":false},{"id":"b","text":"The graphic mechanics of sex","trick":true},{"id":"c","text":"Private parts are private","trick":false},{"id":"d","text":"Explicit adult relationship details","trick":true},{"id":"e","text":"Safe vs unsafe touch","trick":false}],"why":"Graphic sex mechanics and explicit adult-relationship details are for much later; names, privacy and safe-vs-unsafe touch fit a four-year-old.","relearn":"Correct names, privacy and safe-vs-unsafe touch fit a four-year-old; graphic sex mechanics and explicit adult details come much later.","cat":"early-years"},
  {"id":"tk-947","type":"spot","persona":"any","source":"catch the myths","hook":"Spot the two statements about early body-safety that are myths.","scene":[{"id":"a","text":"Correct names help a child stay safe","trick":false},{"id":"b","text":"Talking about bodies gives kids ideas","trick":true},{"id":"c","text":"Body safety can start around age four","trick":false},{"id":"d","text":"Only girls need consent talks","trick":true},{"id":"e","text":"'No body secrets' protects children","trick":false}],"why":"'Talking gives ideas' and 'only girls need consent' are myths; correct names, an early start and 'no body secrets' protect.","relearn":"'Talking gives ideas' and 'only girls need consent' are myths; correct names, an early start and 'no body secrets' protect every child.","cat":"early-years"},
  {"id":"tk-948","type":"spot","persona":"Meena","source":"catch the brush-offs","hook":"Spot the two reactions to a child's worry that miss a warning sign.","scene":[{"id":"a","text":"“Thank you for telling me.”","trick":false},{"id":"b","text":"“Stop making things up.”","trick":true},{"id":"c","text":"“You're not in any trouble.”","trick":false},{"id":"d","text":"“Don't be silly, he's family.”","trick":true},{"id":"e","text":"“Let's talk about what happened.”","trick":false}],"why":"'Stop making things up' and 'don't be silly, he's family' brush off a warning sign; believing and gently asking keeps a child safe.","relearn":"'Stop making things up' and 'don't be silly, he's family' brush off a worry; thank, reassure and ask gently. If worried, Childline 1098.","cat":"early-years"},
  {"id":"tk-949","type":"role-play","persona":"Divya","source":"name at bathtime","hook":"At bath time your toddler points and asks what their private part is called.","setup":"Answer plainly:","yourLine":[{"text":"“That's your vulva. It's just the proper name, like elbow or knee.”","best":true},{"text":"“Never mind that, let's get you clean.”"}],"relearn":"Naming a body part as plainly as an elbow removes shame and gives a child a word that keeps them safe.","cat":"early-years"},
  {"id":"tk-950","type":"role-play","persona":"any","source":"teach the no-secrets rule","hook":"You want your young child to know the 'no body secrets' rule.","setup":"Say it simply:","yourLine":[{"text":"“No one should ask you to keep a secret about your body. Tell me, and you'll never be in trouble.”","best":true},{"text":"“Some secrets are fine to keep if a grown-up says so.”"}],"relearn":"No one should ask a child to keep a body secret: 'tell me, you'll never be in trouble' gives them permission to disclose.","cat":"early-years"},
  {"id":"tk-951","type":"role-play","persona":"Priya","source":"redirect at the table","hook":"At dinner your child loudly asks where babies come from and the table goes silent, all eyes on you.","setup":"Answer without flinching:","yourLine":[{"text":"“Good question, babies grow in a special place in the body. I'll tell you more after dinner.”","best":true},{"text":"“We don't talk about that at the table. Go finish your food.”"}],"relearn":"Giving a calm true answer and a 'more later' keeps the question open instead of teaching them it's shameful to ask.","cat":"early-years"},
  {"id":"tk-952","type":"role-play","persona":"Vikram","source":"consent in greetings","hook":"A relative reaches for a hug and your child stiffens and pulls back.","setup":"Offer your child a choice:","yourLine":[{"text":"“Would you like a hug, a wave or a high-five? You can choose.”","best":true},{"text":"“Go on, give uncle a hug, don't be rude.”"}],"relearn":"Offering a child a choice of greeting teaches consent; forcing the hug tells them their bodily 'no' can be overruled.","cat":"early-years"},
  {"id":"tk-953","type":"role-play","persona":"Divya","source":"where babies come from","hook":"Your four-year-old asks, 'Where do babies come from?' and you freeze.","setup":"Give a simple, true start:","yourLine":[{"text":"“Babies grow in a special place in the body called the womb.”","best":true},{"text":"“The stork brings them. Now off you go and play.”"}],"relearn":"Give a little child a simple, true answer about where babies come from, not a stork story or a shutdown.","cat":"early-years"},
  {"id":"tk-954","type":"role-play","persona":"any","source":"i don't know answer","hook":"Your child asks a body question and you honestly don't know the answer.","setup":"Be honest and willing:","yourLine":[{"text":"“Great question! I'm not sure, so let's find out together.”","best":true},{"text":"“That's a silly thing to ask, stop it.”"}],"relearn":"'I'm not sure, so let's find out together' keeps you the askable parent; 'that's silly' sends the question elsewhere.","cat":"early-years"},
  {"id":"tk-955","type":"role-play","persona":"Priya","source":"park a question kindly","hook":"Your child asks a big body question while you're busy at the stove.","setup":"Honour it and park it kindly:","yourLine":[{"text":"“That's a great question. Let's talk about it properly after dinner.”","best":true},{"text":"“We don't talk about things like that.”"}],"relearn":"You can honour a question and park it briefly. That keeps it safe to ask, without a shutdown.","cat":"early-years"},
  {"id":"tk-956","type":"role-play","persona":"any","source":"safe grown-up rule","hook":"You want to teach your child what to do if a touch feels wrong.","setup":"Explain it simply:","yourLine":[{"text":"“If any touch feels wrong, come tell me. You'll never be in trouble for telling.”","best":true},{"text":"“Just be good and do whatever grown-ups tell you.”"}],"relearn":"'Tell me, you'll never be in trouble' gives a child permission to disclose; 'obey grown-ups' takes it away.","cat":"early-years"},
  {"id":"tk-957","type":"role-play","persona":"Divya","source":"repair a snap","hook":"Yesterday you snapped at a body question. You want to go back and repair it.","setup":"Reopen the door:","yourLine":[{"text":"“I was wrong to snap yesterday. It's a good question, so ask me anything.”","best":true},{"text":"“Let's just forget you ever asked that.”"}],"relearn":"Going back to repair a fumbled answer models honesty and shows the door is genuinely always open.","cat":"early-years"},
  {"id":"tk-958","type":"role-play","persona":"any","source":"teach private means private","hook":"Your child asks why they can't be naked when guests are over.","setup":"Frame privacy warmly:","yourLine":[{"text":"“Your private parts are just for you. We keep them covered around others.”","best":true},{"text":"“Because it's shameful and naughty, that's why.”"}],"relearn":"Framing privacy as 'just for you', a boundary not a shame, protects a child without teaching disgust.","cat":"early-years"},
  {"id":"tk-959","type":"role-play","persona":"Meena","source":"believe a disclosure","hook":"Your young child quietly says someone touched them where they didn't like.","setup":"Respond so they keep talking:","yourLine":[{"text":"“Thank you for telling me. You're not in any trouble. Can you tell me more?”","best":true},{"text":"“Are you sure? You mustn't make up stories.”"}],"relearn":"Staying calm, believing and thanking a child keeps them talking; doubting them teaches silence. If worried, Childline 1098.","cat":"early-years"},
  {"id":"tk-990","cat":"facts-and-values","type":"strike-rewrite","hook":"\"If I just teach my values, the facts will sort themselves out.\"","myth":{"un":"If I just teach my values, the facts will sort themselves out.","re":"Values alone leave gaps a child fills from peers or the feed; pair them with honest facts so guidance has something true to stand on.","why":"Values guide; facts keep safe. A child needs both."},"relearn":"Values without facts leave gaps others fill; give the honest facts too, so your guidance stands on what's true.","persona":"any","source":"values need facts"},
  {"id":"tk-991","cat":"facts-and-values","type":"strike-rewrite","hook":"\"Facts are cold; sharing my values would just be preaching.\"","myth":{"un":"Facts are cold; sharing my values would just be preaching.","re":"Sharing your values isn't preaching; it's offering your view alongside the facts so a child can weigh both and still feel free to choose.","why":"Said as your view, not a verdict, values invite thought."},"relearn":"Sharing your values as your view, not a verdict, isn't preaching; it gives a child something to weigh with the facts.","persona":"Priya","source":"values not preaching"},
  {"id":"tk-992","cat":"facts-and-values","type":"strike-rewrite","hook":"\"My child is too young for facts, so I'll just give the rule.\"","myth":{"un":"My child is too young for facts, so I'll just give the rule.","re":"A rule with no honest 'why' is easy to drop later; an age-right fact behind it makes the value stick and travel with them.","why":"'Because I said so' fades; an honest reason lasts."},"relearn":"A rule needs an age-right reason; the honest fact behind a value is what makes it stick and travel with a child.","persona":"any","source":"rule needs reason"},
  {"id":"tk-993","cat":"facts-and-values","type":"strike-rewrite","hook":"\"If the facts and my beliefs disagree, I should hide the facts.\"","myth":{"un":"If the facts and my beliefs disagree, I should hide the facts.","re":"Hiding facts a child needs to stay safe doesn't protect your beliefs; give the facts, then share your belief honestly as your own.","why":"A hidden fact gets learned anyway, without your voice."},"relearn":"Don't hide safety facts that clash with a belief; give the facts, then share your belief honestly as your own.","persona":"Vikram","source":"don't hide facts"},
  {"id":"tk-994","cat":"facts-and-values","type":"strike-rewrite","hook":"\"Sharing my values will pressure my child into agreeing with me.\"","myth":{"un":"Sharing my values will pressure my child into agreeing with me.","re":"Stated as 'here's what I believe and why', your values are a gift to weigh, not a command; that respect keeps a child talking to you.","why":"Offered, not imposed, values invite rather than push."},"relearn":"Offered as 'what I believe and why', your values invite thought, not pressure; that respect keeps a child talking to you.","persona":"Priya","source":"offer not impose"},
  {"id":"tk-995","cat":"facts-and-values","type":"strike-rewrite","hook":"\"Keeping quiet keeps me neutral and lets my child decide freely.\"","myth":{"un":"Keeping quiet keeps me neutral and lets my child decide freely.","re":"Silence isn't neutral; it just lets peers, media and the feed decide for you. Your honest values belong in the mix your child weighs.","why":"Someone always fills the silence; let it be you too."},"relearn":"Silence isn't neutral; it cedes the choice to peers and the feed, so put your honest values in the mix your child weighs.","persona":"any","source":"silence not neutral"},
  {"id":"tk-996","cat":"facts-and-values","type":"strike-rewrite","hook":"\"Talking openly about facts means I'm abandoning our family's culture.\"","myth":{"un":"Talking openly about facts means I'm abandoning our family's culture.","re":"Breaking the silence isn't betraying your culture; it lets you pass on its best parts on purpose, instead of leaving the feed to teach.","why":"Naming your values out loud is how culture passes on."},"relearn":"Open talk doesn't betray your culture; it lets you pass on its best parts on purpose, rather than ceding them to the feed.","persona":"any","source":"pass on the best"},
  {"id":"tk-997","cat":"facts-and-values","type":"strike-rewrite","hook":"\"My child can't handle both honest facts and our family's beliefs at once.\"","myth":{"un":"My child can't handle both honest facts and our family's beliefs at once.","re":"Children hold both with ease: the facts to stay safe and your values to guide. It's adults who treat them as a choice.","why":"'How it works' and 'what we believe' aren't rivals."},"relearn":"Children can hold both at once, the facts to stay safe and your values to guide; only adults treat them as a choice.","persona":"Divya","source":"kids hold both"},
  {"id":"tk-998","cat":"facts-and-values","type":"strike-rewrite","hook":"\"I'll wait for school to give the facts, then I'll add our values.\"","myth":{"un":"I'll wait for school to give the facts, then I'll add our values.","re":"Lessons may be partial or late, and the feed never waits; give the honest facts yourself, with your values, so your voice is the first they trust.","why":"Being the first trusted source is the whole advantage."},"relearn":"Don't outsource the facts and wait; give them yourself with your values, so your trusted voice is the one a child hears first.","persona":"any","source":"don't outsource"},
  {"id":"tk-999","cat":"facts-and-values","type":"strike-rewrite","hook":"\"If I give the facts, my child will think I approve of everything.\"","myth":{"un":"If I give the facts, my child will think I approve of everything.","re":"Knowing how something works isn't the same as a green light; you can give the honest fact and clearly say where you stand on it.","why":"Information and approval are two separate messages."},"relearn":"Giving a fact isn't approval; you can explain how something works and still say clearly where your family stands on it.","persona":"Vikram","source":"facts aren't approval"},
  {"id":"tk-1000","cat":"facts-and-values","type":"strike-rewrite","hook":"\"Strong values mean I don't really need to bother with the facts.\"","myth":{"un":"Strong values mean I don't really need to bother with the facts.","re":"The strongest values still need true information to act on; without the facts, a child can't tell where your guidance actually applies.","why":"Values point the way; facts are the ground to walk on."},"relearn":"Even strong values need true facts to act on; without them a child can't tell where your guidance really applies.","persona":"any","source":"values need ground"},
  {"id":"tk-1001","cat":"facts-and-values","type":"sort","hook":"Sort: a both-and reply that gives facts and values, or a reply that picks just one?","items":[{"id":"a","text":"\"Here's how it works, and here's what we believe.\""},{"id":"b","text":"\"Don't ask, just follow the rule.\""},{"id":"c","text":"\"The facts are these; my hope for you is this.\""},{"id":"d","text":"\"I won't say; you'll learn it somewhere.\""},{"id":"e","text":"\"True answer first, then our family's view.\""},{"id":"f","text":"\"Facts don't matter, only what we believe.\""}],"bins":[{"id":"both","label":"Gives both","valence":"pos"},{"id":"one","label":"Picks just one","valence":"neg"}],"key":{"a":"both","b":"one","c":"both","d":"one","e":"both","f":"one"},"relearn":"A both-and reply pairs the honest fact with your value; picking just one drops safety or your voice.","persona":"any","source":"both or one"},
  {"id":"tk-1002","cat":"facts-and-values","type":"sort","hook":"Sort: which order makes a tricky answer land, or which order shuts it down?","items":[{"id":"a","text":"Honest fact first, then our family's view"},{"id":"b","text":"\"You're too young\" before any answer"},{"id":"c","text":"Calm fact, then 'here's what I hope'"},{"id":"d","text":"A lecture before letting them ask"},{"id":"e","text":"Answer the question, then add the value"},{"id":"f","text":"Shame the question, give nothing"}],"bins":[{"id":"lands","label":"Lands well","valence":"pos"},{"id":"shuts","label":"Shuts it down","valence":"neg"}],"key":{"a":"lands","b":"shuts","c":"lands","d":"shuts","e":"lands","f":"shuts"},"relearn":"Honest facts first, then your values, lands the answer; leading with shame or a lecture shuts the door.","persona":"any","source":"order that lands"},
  {"id":"tk-1003","cat":"facts-and-values","type":"sort","hook":"Sort: an honest fact about respect and bodies, or a value your family shares?","items":[{"id":"a","text":"A 'no' must always be respected"},{"id":"b","text":"We hope you'll wait for someone you trust"},{"id":"c","text":"Bodies change at different times for everyone"},{"id":"d","text":"In our home, we value loyalty and honesty"},{"id":"e","text":"Saying yes must be free, not pressured"},{"id":"f","text":"We believe relationships deserve care"}],"bins":[{"id":"fact","label":"Honest fact","valence":"pos"},{"id":"value","label":"Family value","valence":"tell"}],"key":{"a":"fact","b":"value","c":"fact","d":"value","e":"fact","f":"value"},"relearn":"How consent and bodies work are honest facts; your hopes about waiting, loyalty and care are values you share.","persona":"Vikram","source":"respect facts vs values"},
  {"id":"tk-1004","cat":"facts-and-values","type":"sort","hook":"Sort: when facts and elders' silence clash, which protects a child, which keeps the silence?","items":[{"id":"a","text":"Give the safety fact kindly, but give it"},{"id":"b","text":"Stay quiet so no relative is upset"},{"id":"c","text":"Answer the child, then tell elders gently"},{"id":"d","text":"Tell the child 'we don't discuss that'"},{"id":"e","text":"Prioritise the child's safety facts"},{"id":"f","text":"Let 'log kya kahenge' decide"}],"bins":[{"id":"protect","label":"Protects the child","valence":"pos"},{"id":"silence","label":"Keeps the silence","valence":"neg"}],"key":{"a":"protect","b":"silence","c":"protect","d":"silence","e":"protect","f":"silence"},"relearn":"Give the safety facts kindly even when elders prefer silence; safety beats 'log kya kahenge'.","persona":"Priya","source":"facts over silence sort"},
  {"id":"tk-1005","cat":"facts-and-values","type":"sort","hook":"Sort: a fact-plus-value 'both-and' reply, or a reply that hides facts to protect a belief?","items":[{"id":"a","text":"\"That's how it works; we believe in waiting.\""},{"id":"b","text":"\"I won't explain; it's against our values.\""},{"id":"c","text":"\"Here's the honest truth, and our hope.\""},{"id":"d","text":"\"Better you don't know that at all.\""},{"id":"e","text":"\"The facts are these; here's our view.\""},{"id":"f","text":"\"We don't talk facts in this family.\""}],"bins":[{"id":"bothand","label":"Both-and","valence":"pos"},{"id":"hides","label":"Hides the facts","valence":"neg"}],"key":{"a":"bothand","b":"hides","c":"bothand","d":"hides","e":"bothand","f":"hides"},"relearn":"A both-and reply pairs the fact with your belief; hiding facts to guard a belief leaves a child unsafe.","persona":"Vikram","source":"both-and vs hide"},
  {"id":"tk-1006","cat":"facts-and-values","type":"sort","hook":"Sort: a calm 'facts + values' habit, or a habit that cedes the field to the feed?","items":[{"id":"a","text":"Answer questions honestly, share your view"},{"id":"b","text":"Hope school or the internet covers it"},{"id":"c","text":"Talk early, in small everyday moments"},{"id":"d","text":"Avoid the topic till there's a crisis"},{"id":"e","text":"Pair each fact with what you believe"},{"id":"f","text":"Let the algorithm answer the hard ones"}],"bins":[{"id":"yours","label":"Your voice in the mix","valence":"pos"},{"id":"feed","label":"Cedes to the feed","valence":"neg"}],"key":{"a":"yours","b":"feed","c":"yours","d":"feed","e":"yours","f":"feed"},"relearn":"Honest answers, early small talks and pairing fact with value keep your voice in the mix; avoiding it cedes to the feed.","persona":"any","source":"voice vs feed"},
  {"id":"tk-1007","cat":"facts-and-values","type":"sort","hook":"Sort: an honest fact that keeps a teen safe, or a value you choose to pass on?","items":[{"id":"a","text":"What consent looks like in a real moment"},{"id":"b","text":"The kind of partner we hope you choose"},{"id":"c","text":"That a lot of online content isn't real"},{"id":"d","text":"Why we value treating people with dignity"},{"id":"e","text":"How to leave a situation that feels off"},{"id":"f","text":"Our hope that you'll never settle for less"}],"bins":[{"id":"fact","label":"Safety fact","valence":"pos"},{"id":"value","label":"Value to pass on","valence":"tell"}],"key":{"a":"fact","b":"value","c":"fact","d":"value","e":"fact","f":"value"},"relearn":"Consent, online reality and how to leave are safety facts; the partner you hope for and dignity are values to pass on.","persona":"Vikram","source":"teen facts vs values"},
  {"id":"tk-1008","cat":"facts-and-values","type":"sort","hook":"Sort: which closes the gap others would fill, which leaves the gap wide open?","items":[{"id":"a","text":"Share your honest view on a hard topic"},{"id":"b","text":"Change the subject every time it comes up"},{"id":"c","text":"Be the first to give the true answer"},{"id":"d","text":"Assume they'll 'just know' the right thing"},{"id":"e","text":"Name what your family believes and why"},{"id":"f","text":"Leave the topic to whoever asks first"}],"bins":[{"id":"closes","label":"Closes the gap","valence":"pos"},{"id":"open","label":"Leaves it open","valence":"neg"}],"key":{"a":"closes","b":"open","c":"closes","d":"open","e":"closes","f":"open"},"relearn":"Sharing your view, answering first and naming your beliefs close the gap; avoiding it leaves it for others to fill.","persona":"any","source":"close the gap"},
  {"id":"tk-1009","cat":"facts-and-values","type":"sort","hook":"Sort: honest facts a young child needs, or family values you choose to add?","items":[{"id":"a","text":"The correct names for body parts"},{"id":"b","text":"How we greet guests in our home"},{"id":"c","text":"That no one may touch their private parts"},{"id":"d","text":"The traditions we love to celebrate"},{"id":"e","text":"They can always tell a safe grown-up"},{"id":"f","text":"The kindness we hope they show others"}],"bins":[{"id":"fact","label":"Honest fact","valence":"pos"},{"id":"value","label":"Family value","valence":"tell"}],"key":{"a":"fact","b":"value","c":"fact","d":"value","e":"fact","f":"value"},"relearn":"Correct names, body safety and telling a safe adult are facts a young child needs; greetings and traditions are values.","persona":"Divya","source":"early facts vs values"},
  {"id":"tk-1010","cat":"facts-and-values","type":"sort","hook":"Sort: a reply that respects a child's freedom to think, or one that shuts thinking down?","items":[{"id":"a","text":"\"Here's what I believe, and here's why.\""},{"id":"b","text":"\"Believe exactly what I say, full stop.\""},{"id":"c","text":"\"These are the facts; what do you think?\""},{"id":"d","text":"\"There's nothing for you to think about.\""},{"id":"e","text":"\"I'll share my view; you can weigh it.\""},{"id":"f","text":"\"Questioning this isn't allowed here.\""}],"bins":[{"id":"respects","label":"Respects thinking","valence":"pos"},{"id":"shuts","label":"Shuts it down","valence":"neg"}],"key":{"a":"respects","b":"shuts","c":"respects","d":"shuts","e":"respects","f":"shuts"},"relearn":"Sharing your view with a 'why' and inviting their thoughts respects a child; banning questions doesn't.","persona":"Priya","source":"respect thinking"},
  {"id":"tk-1011","cat":"facts-and-values","type":"branch","hook":"Your ten-year-old asks a frank question whose honest answer brushes your beliefs.","options":[{"text":"Give the true, age-right answer, then what your family believes","consequence":"Safety plus guidance; they keep asking you.","outcome":"both","best":true},{"text":"Dodge the fact, recite only the rule","consequence":"The fact is learned elsewhere, minus you."},{"text":"Tell them they're too young to ask","consequence":"They ask the feed instead."}],"debrief":"Answer honestly and age-right, then add your values.","relearn":"Answer truly, then add your values; dodging hands it to the feed.","persona":"any","source":"frank question"},
  {"id":"tk-1012","cat":"facts-and-values","type":"branch","hook":"A relative says you'll 'spoil' your child by explaining facts; teach values only.","options":[{"text":"Keep giving honest facts with your values; explain kindly why both matter","consequence":"Child stays safe and guided.","outcome":"both","best":true},{"text":"Drop the facts to keep the relative happy","consequence":"Child loses safety facts; learns silence."},{"text":"Argue loudly in front of the child","consequence":"Child learns the topic means conflict."}],"debrief":"Hold to facts-plus-values and explain it kindly.","relearn":"Keep giving facts with your values under pressure; explain kindly, don't drop them.","persona":"Priya","source":"relative pressure"},
  {"id":"tk-1013","cat":"facts-and-values","type":"branch","hook":"Your teen quotes an online 'fact' that's false and clashes with your values.","options":[{"text":"Calmly correct the fact, then share your view on the values part","consequence":"Teen learns to check claims, hears your guidance.","outcome":"both","best":true},{"text":"Just declare it 'against our values'","consequence":"The lie stays; the values get tuned out."},{"text":"Ban the app in anger","consequence":"Teen hides their feed from you."}],"debrief":"Correct the false fact calmly first, then offer your values.","relearn":"Fix the false fact, then share your values; values alone leave the lie standing.","persona":"Vikram","source":"online false fact"},
  {"id":"tk-1014","cat":"facts-and-values","type":"branch","hook":"Your child asks where babies come from; you fear the honest answer harms 'innocence'.","options":[{"text":"Give a simple, true answer at their level, warmed by your values","consequence":"Curiosity met; they trust you with the next one.","outcome":"both","best":true},{"text":"Tell a stork story to protect innocence","consequence":"They learn it was untrue, trust you less."},{"text":"Say it's a secret for grown-ups","consequence":"They sense shame and ask elsewhere."}],"debrief":"Answer simply and truly at their level, warmed by your values.","relearn":"A simple true answer keeps trust; a stork story or 'secret' sends them elsewhere.","persona":"Divya","source":"where babies"},
  {"id":"tk-1015","cat":"facts-and-values","type":"branch","hook":"You gave only the rule yesterday and skipped the honest reason behind it.","options":[{"text":"Go back today; add the age-right fact behind the value, calmly","consequence":"The value gains a 'why' that sticks.","outcome":"both","best":true},{"text":"Leave it; the rule was enough","consequence":"A rule with no reason is easy to drop."},{"text":"Hope they never ask why","consequence":"The feed's reason arrives; yours doesn't."}],"debrief":"Circle back and give the honest reason; a value with a 'why' lasts.","relearn":"Add the reason behind a bare rule; a 'why' makes a value stick, and going back models repair.","persona":"any","source":"add the reason"},
  {"id":"tk-1016","cat":"facts-and-values","type":"branch","hook":"Your child's question has a clear factual answer but your view is still forming.","options":[{"text":"Give the honest fact now; say the value is still forming for you","consequence":"Truth delivered; honest reflection modelled.","outcome":"both","best":true},{"text":"Stall on the fact till your view settles","consequence":"They get the fact, minus you, elsewhere."},{"text":"Pretend a firm view you don't hold","consequence":"The made-up certainty unravels."}],"debrief":"Give the fact now and be honest the value is still forming.","relearn":"Give the honest fact now even if your view is forming; truth needn't wait on a settled value.","persona":"any","source":"fact now value forming"},
  {"id":"tk-1017","cat":"facts-and-values","type":"branch","hook":"A puberty question lands at a family dinner; elders signal you to 'not here'.","options":[{"text":"Acknowledge it warmly; promise a proper, honest talk soon","consequence":"They stay comfortable asking you.","outcome":"both","best":true},{"text":"Shush the child to keep the peace","consequence":"They learn the topic is shameful."},{"text":"Loudly insist on answering at the table","consequence":"They recall the tension, not the answer."}],"debrief":"Honour the question and park it kindly for a real talk.","relearn":"Honour the question and park it for a real talk; shushing teaches shame, a scene teaches it's risky.","persona":"any","source":"park at dinner"},
  {"id":"tk-1018","cat":"facts-and-values","type":"branch","hook":"Your teen says 'just tell me the facts, keep your opinions out of it'.","options":[{"text":"Give the facts clearly, then 'here's my view, take it or leave it'","consequence":"Truth and your view, no pressure.","outcome":"both","best":true},{"text":"Give facts only, swallow your view","consequence":"Louder voices fill your guidance."},{"text":"Refuse facts till they hear your view","consequence":"They get the facts from the feed."}],"debrief":"Give the facts, then offer your view to weigh.","relearn":"Give the facts, then offer your value to weigh; silence on values lets louder voices win.","persona":"Vikram","source":"keep opinions out"},
  {"id":"tk-1019","cat":"facts-and-values","type":"match","hook":"Match the honest fact to the family value a parent might pair with it.","pairs":[{"left":"Consent means a free, clear yes","right":"We hope you treat people with care"},{"left":"Bodies develop on their own timeline","right":"No one should be rushed or shamed"},{"left":"A lot of online content isn't real","right":"We value seeing people as whole"},{"left":"You can always leave if it feels unsafe","right":"Come home rather than stay polite"},{"left":"Anyone can say no at any point","right":"We trust you to honour a no"}],"relearn":"Each fact pairs with a value: the fact keeps a child safe, the value carries your family's hope.","persona":"Vikram","source":"fact to value"},
  {"id":"tk-1020","cat":"facts-and-values","type":"match","hook":"Match the child's line to a 'facts then values' reply.","pairs":[{"left":"'What's a condom for?'","right":"It prevents this; here's our hope for you"},{"left":"'My friend has a crush'","right":"Crushes are normal; we value being kind"},{"left":"'Is it bad to feel this?'","right":"Feelings are normal; here's how we act"},{"left":"'Why wait?'","right":"The honest reasons, and what we believe"},{"left":"'Everyone's online dating'","right":"Here are the real risks; here's our view"}],"relearn":"Each line gets the honest fact first, then your value, so a child has the truth and your guidance.","persona":"any","source":"line to reply"},
  {"id":"tk-1021","cat":"facts-and-values","type":"match","hook":"Match a parent's fear to the reframe that lets facts and values sit together.","pairs":[{"left":"'Facts will rob their innocence'","right":"Facts protect; silence leaves them open"},{"left":"'My values will sound preachy'","right":"As your view, values invite, not push"},{"left":"'It's facts or our culture'","right":"Naming values is how culture passes on"},{"left":"'They can't hold both'","right":"Kids carry facts to stay safe, values to guide"},{"left":"'School will handle it'","right":"Be the first trusted voice; lessons run late"}],"relearn":"Each fear has a reframe: facts protect, values invite, both belong, your voice first.","persona":"any","source":"fear to reframe"},
  {"id":"tk-1022","cat":"facts-and-values","type":"match","hook":"Match the topic to a both-and line that gives the fact and your family's value.","pairs":[{"left":"Periods","right":"Here's what happens; we treat it as normal, never shameful"},{"left":"Saying no","right":"A no is always valid; we honour it, always"},{"left":"Online strangers","right":"Here's the real risk; we keep private things private"},{"left":"Respect","right":"Respect means real consent; we expect it both ways"},{"left":"Pornography","right":"Most of it isn't real; we value seeing people whole"}],"relearn":"Each topic gets a both-and line: the honest fact to stay safe and the family value you choose to share.","persona":"Vikram","source":"topic to bothand"},
  {"id":"tk-1023","cat":"facts-and-values","type":"match","hook":"Match what a parent says to whether it's giving a fact, a value, or both.","pairs":[{"left":"\"This is how the body works\"","right":"An honest fact"},{"left":"\"We hope you'll wait for trust\"","right":"A value you share"},{"left":"\"Here's the truth, and our view\"","right":"Both, together"},{"left":"\"No one may touch you here\"","right":"A safety fact"},{"left":"\"In our home we value honesty\"","right":"A family belief"}],"relearn":"Naming whether a line is a fact, a value, or both helps a parent make sure each answer carries both.","persona":"any","source":"label fact or value"},
  {"id":"tk-1024","cat":"facts-and-values","type":"match","hook":"Match the slip to the both-and repair.","pairs":[{"left":"Gave only the rule","right":"Go back and add the honest reason"},{"left":"Gave only the fact","right":"Return and share what you believe"},{"left":"Hid a fact to protect a belief","right":"Offer the fact, then name your belief honestly"},{"left":"Stayed silent to stay neutral","right":"Put your honest view into the mix"},{"left":"Outsourced it to the feed","right":"Be the next trusted voice they hear"}],"relearn":"Every facts-or-values slip has a repair: add what was missing, so a child ends up with both the truth and your view.","persona":"any","source":"slip to repair"},
  {"id":"tk-1025","cat":"facts-and-values","type":"match","hook":"Match the parent's worry about saying their values to the gentle truth that frees them.","pairs":[{"left":"'They'll think I'm controlling'","right":"Offered, not imposed, values respect choice"},{"left":"'I'll get the facts wrong'","right":"'Let's check' is an honest answer"},{"left":"'They won't listen anyway'","right":"A stated value lands quietly over time"},{"left":"'It'll start an argument'","right":"Calm 'here's my view' invites, not fights"},{"left":"'It's not my place'","right":"Your trusted voice is the one they need"}],"relearn":"Each worry about voicing values has a gentle truth: offered calmly, your view belongs.","persona":"Priya","source":"worry to truth"},
  {"id":"tk-1026","cat":"facts-and-values","type":"reflect","hook":"Lensy: giving your child a clear fact today doesn't lock in their choices for later. It just means they decide informed. Sit right?","prompt":"What do you think?","options":["Sits right","They decide informed","Facts now, choices later"],"affirm":"Sharing an accurate fact equips a child to make informed choices later; it doesn't dictate what those choices will be.","relearn":"A fact today doesn't decide their future for them. It means they'll choose with their eyes open.","persona":"any","source":"informed not decided"},
  {"id":"tk-1027","cat":"facts-and-values","type":"reflect","hook":"Lensy: sharing your honest view isn't preaching; it's a gift your child gets to weigh. Sit right?","prompt":"What's your take?","options":["Sits right","A gift to weigh","Not preaching"],"affirm":"Offered as your view rather than a verdict, your values invite a child to think, not feel pushed; they belong in the mix.","relearn":"Sharing your view, offered not imposed, isn't preaching; it's something honest your child gets to weigh.","persona":"Priya","source":"not preaching reflect"},
  {"id":"tk-1028","cat":"facts-and-values","type":"reflect","hook":"Lensy: staying silent doesn't keep you neutral; it just lets someone else fill the gap. Land for you?","prompt":"Does that land?","options":["It lands","Silence isn't neutral","I'll speak up"],"affirm":"Silence on values isn't neutral; peers, media and the feed will fill the gap, so your honest voice belongs in the mix.","relearn":"Silence isn't neutral; it cedes the choice to others, so put your honest voice in the mix your child weighs.","persona":"any","source":"not neutral reflect"},
  {"id":"tk-1029","cat":"facts-and-values","type":"reflect","hook":"Lensy: if you stay quiet, your child still learns about this, just from a screen or a classmate instead of you. Land?","prompt":"What's your take?","options":["Lands","Better from me","Someone fills the gap"],"affirm":"A child learns about these topics whether or not the parent speaks; silence simply hands the teaching to less trustworthy sources.","relearn":"Your silence isn't neutral: if you don't fill it, a screen or a classmate will.","persona":"any","source":"silence isn't neutral"},
  {"id":"tk-1030","cat":"facts-and-values","type":"reflect","hook":"Lensy: 'here's how it works, and here's what we believe' is one sentence your child can hold whole. Feel true?","prompt":"How's that sit?","options":["Feels true","One whole sentence","I can say that"],"affirm":"Pairing the fact and your value in a single calm breath shows a child the two aren't rivals; they belong together.","relearn":"'Here's how it works, and here's what we believe' is one honest sentence; the fact and the value belong together.","persona":"any","source":"one sentence reflect"},
  {"id":"tk-1031","cat":"facts-and-values","type":"reflect","hook":"Lensy: giving a fact isn't the same as approving of it; you can be honest and still say where you stand. True for you?","prompt":"Sound right?","options":["Sounds right","Fact isn't approval","I can do both"],"affirm":"Explaining how something works and saying clearly where your family stands are two separate, honest messages.","relearn":"Giving a fact isn't approval; you can explain how something works and still say where your family stands.","persona":"Vikram","source":"fact not approval reflect"},
  {"id":"tk-1032","cat":"facts-and-values","type":"reflect","hook":"Lensy: not having a settled opinion yet is okay; you can still give your child the honest fact today. Resonate?","prompt":"What do you feel?","options":["Resonates","Truth needn't wait","I'll be honest"],"affirm":"An honest fact doesn't have to wait for a settled view; you can give the truth now and say the value is still forming.","relearn":"You can give the honest fact today even if your view is still forming; truth needn't wait on a settled opinion.","persona":"any","source":"value still forming reflect"},
  {"id":"tk-1033","cat":"facts-and-values","type":"reflect","hook":"Lensy: the goal isn't to win agreement; it's to give the facts and your view, and trust your child to weigh them. Sit well?","prompt":"How's that feel?","options":["Sits well","Trust them to weigh","Not about winning"],"affirm":"Giving honest facts and your values, then trusting a child to weigh them, keeps the door open far better than demanding agreement.","relearn":"The aim isn't agreement; give the facts and your view and trust your child to weigh both, with the door open.","persona":"Priya","source":"not about winning"},
  {"id":"tk-1034","cat":"facts-and-values","type":"role-play","hook":"Your child asks something where your values are strong. You want to give facts and your view honestly.","setup":"Give both honestly:","yourLine":[{"text":"\"Here's how it actually works, and here's what we believe about it, both matter to me.\"","best":true},{"text":"\"Never mind the facts, just do as we say.\""}],"relearn":"Pairing the honest facts with your stated values gives a child both safety and your guidance to weigh.","persona":"Vikram","source":"both honestly"},
  {"id":"tk-1035","cat":"facts-and-values","type":"role-play","hook":"Your teen pushes back: 'you're just forcing your beliefs on me'. You want to offer, not impose.","setup":"Offer it, don't impose it:","yourLine":[{"text":"\"These are the facts. Here's my view too, take it or leave it; you get to decide.\"","best":true},{"text":"\"You'll believe what I believe, end of discussion.\""}],"relearn":"Offering your view as theirs to weigh, not a command, respects a teen and keeps them willing to keep talking.","persona":"Vikram","source":"offer not impose roleplay"},
  {"id":"tk-1036","cat":"facts-and-values","type":"role-play","hook":"A relative scolds you for explaining a fact, saying values are all a child needs. You back the facts kindly.","setup":"Hold the line, warmly:","yourLine":[{"text":"\"We teach the honest facts and our values both, so she stays safe and knows what we believe.\"","best":true},{"text":"\"You're right, I'll stop explaining things to her.\""}],"relearn":"Backing the facts kindly in front of a relative keeps a child safe and shows the door to honest talk stays open.","persona":"Priya","source":"back facts to relative"},
  {"id":"tk-1037","cat":"facts-and-values","type":"role-play","hook":"Your child asks a frank question and you feel the urge to dodge. You give the fact, then your value.","setup":"Fact first, then your view:","yourLine":[{"text":"\"Good question. Here's the honest answer, and here's what our family hopes for you.\"","best":true},{"text":"\"That's not something we talk about, just trust the rule.\""}],"relearn":"Answering the frank question honestly, then adding your value, keeps you the trusted source instead of the feed.","persona":"any","source":"fact then value roleplay"},
  {"id":"tk-1038","cat":"facts-and-values","type":"role-play","hook":"Your teen repeats a false 'fact' from online that also clashes with your values. You correct calmly, then share your view.","setup":"Correct, then add your view:","yourLine":[{"text":"\"Actually that part isn't true, here's how it really works, and here's what I believe about it.\"","best":true},{"text":"\"That's nonsense and against our values, drop it.\""}],"relearn":"Correcting the false fact calmly, then offering your view, fixes the error and keeps a teen bringing claims to you.","persona":"Vikram","source":"correct then view roleplay"},
  {"id":"tk-1039","cat":"facts-and-values","type":"role-play","hook":"You gave only a rule yesterday and want to repair it by adding the honest reason today.","setup":"Go back and add the why:","yourLine":[{"text":"\"I gave you the rule but not the reason; here's the honest why behind what we believe.\"","best":true},{"text":"\"The rule's the rule, you don't need a reason.\""}],"relearn":"Going back to add the honest reason behind a rule gives a value a 'why' that lasts and models honest repair.","persona":"any","source":"add why roleplay"},
  {"id":"tk-1040","cat":"facts-and-values","type":"role-play","hook":"Your child senses you're nervous and asks if the topic is bad. You normalise it: facts are okay, and you have values too.","setup":"Normalise it, then guide:","yourLine":[{"text":"\"It's not a bad thing to ask; here are the real facts, and here's what we believe about it.\"","best":true},{"text":"\"Shh, we don't say those words, it's not nice.\""}],"relearn":"Normalising the question and giving facts plus your values shows a child the topic is safe to bring to you.","persona":"Divya","source":"normalise roleplay"},
  {"id":"tk-1041","cat":"facts-and-values","type":"spot","hook":"Spot the two lines that drop either the facts or your values instead of giving both.","scene":[{"id":"a","text":"\"Here's how it works, and here's what we believe.\"","trick":false},{"id":"b","text":"\"Just follow the rule; the facts don't matter.\"","trick":true},{"id":"c","text":"\"The honest answer is this; my hope is that.\"","trick":false},{"id":"d","text":"\"I'll give facts but keep my views to myself.\"","trick":true},{"id":"e","text":"\"True answer first, then our family's view.\"","trick":false}],"why":"A bare rule with no facts, or facts with your values withheld, each gives a child only half.","relearn":"A both-and reply gives the fact and your value; dropping either leaves a child with half.","persona":"any","source":"spot dropped half"},
  {"id":"tk-1042","cat":"facts-and-values","type":"spot","hook":"Spot the two moves that cede the field instead of putting your voice in the mix.","scene":[{"id":"a","text":"Share your honest view on the hard topic","trick":false},{"id":"b","text":"Stay silent and call it staying neutral","trick":true},{"id":"c","text":"Answer the question before the feed does","trick":false},{"id":"d","text":"Leave it for the algorithm to explain","trick":true},{"id":"e","text":"Name what your family believes and why","trick":false}],"why":"Silence isn't neutral and the algorithm doesn't wait; both hand the lesson to others, not your voice.","relearn":"Silence and the feed cede the field; sharing your view and answering first keep your voice in the mix.","persona":"any","source":"spot cede the field"},
  {"id":"tk-1043","cat":"facts-and-values","type":"spot","hook":"Spot the two replies that hide a fact to protect a belief, instead of giving both.","scene":[{"id":"a","text":"\"That's how it works; we believe in waiting.\"","trick":false},{"id":"b","text":"\"Better you never learn that fact at all.\"","trick":true},{"id":"c","text":"\"Here's the honest truth, and here's our hope.\"","trick":false},{"id":"d","text":"\"We don't explain that; it's against our values.\"","trick":true},{"id":"e","text":"\"The facts are these; here's our family's view.\"","trick":false}],"why":"Refusing a fact to guard a belief leaves a child unsafe; it gets learned anyway, minus you.","relearn":"Hiding a needed fact to guard a belief leaves a child unsafe; give the fact, then the belief.","persona":"Vikram","source":"spot hide fact"},
  {"id":"tk-1044","cat":"facts-and-values","type":"spot","hook":"Spot the two reactions that teach a child the topic is shameful rather than safe to ask.","scene":[{"id":"a","text":"\"Good question, let's talk about it properly.\"","trick":false},{"id":"b","text":"\"Don't ever say that word again.\"","trick":true},{"id":"c","text":"\"Here's the honest answer at your level.\"","trick":false},{"id":"d","text":"Gasping and changing the subject fast","trick":true},{"id":"e","text":"\"No question is silly; ask me anything.\"","trick":false}],"why":"Snapping at a word or flinching teaches a child the topic is shameful and sends the next question elsewhere.","relearn":"Calm, welcoming answers keep a child asking you; shock or flinching teach shame and send them to the feed.","persona":"any","source":"spot shame reaction"},
  {"id":"tk-1045","cat":"facts-and-values","type":"spot","hook":"Spot the two myths this game exists to bust about facts and values.","scene":[{"id":"a","text":"Honest facts and your values both protect","trick":false},{"id":"b","text":"\"Giving facts gives kids the wrong ideas\"","trick":true},{"id":"c","text":"Kids can hold the facts and your values","trick":false},{"id":"d","text":"\"It's facts or our values, never both\"","trick":true},{"id":"e","text":"Your trusted voice belongs in the mix","trick":false}],"why":"'Facts give ideas' and 'it's one or the other' are the myths the game busts; both facts and your values protect.","relearn":"Facts don't 'give ideas', and it's never facts-or-values; the honest facts and your values protect a child together.","persona":"any","source":"spot the myths"},
  {"id":"tk-1046","cat":"facts-and-values","type":"spot","hook":"Spot the two ordering mistakes that shut a tricky answer down before the value can land.","scene":[{"id":"a","text":"Give the honest fact, then add your view","trick":false},{"id":"b","text":"Open with \"you're too young to know\"","trick":true},{"id":"c","text":"Answer first, then share what you hope","trick":false},{"id":"d","text":"Lecture for ten minutes before they ask","trick":true},{"id":"e","text":"Reassure with the fact, then guide gently","trick":false}],"why":"Leading with 'too young' or a long lecture shuts the child down, so the value never gets a chance to land.","relearn":"Give the honest fact first, then your value; leading with 'too young' or a lecture shuts the answer down.","persona":"any","source":"spot order mistake"},
  {"id":"tk-1047","cat":"facts-and-values","type":"spot","hook":"Spot the two replies that leave a teen's guidance to louder voices instead of yours.","scene":[{"id":"a","text":"\"Here are the facts, and here's my view.\"","trick":false},{"id":"b","text":"\"Figure the values out yourself.\"","trick":true},{"id":"c","text":"\"That's how it works; here's my hope.\"","trick":false},{"id":"d","text":"\"No comment; your friends' view is fine.\"","trick":true},{"id":"e","text":"\"True answer first, then where I stand.\"","trick":false}],"why":"Refusing to share your view hands a teen's guidance to friends and the feed; your voice belongs in the mix.","relearn":"Silence on values leaves a teen's guidance to louder voices; give the facts and your honest view.","persona":"Vikram","source":"spot leave to others"},
  {"id":"tk-1048","cat":"facts-and-values","type":"sort","hook":"Sort: a true thing to confirm for your child, or an online myth to correct kindly?","items":[{"id":"a","text":"A clear 'no' must always be respected"},{"id":"b","text":"\"Real relationships look like what's on screen\""},{"id":"c","text":"Bodies vary, and that's normal"},{"id":"d","text":"\"Pressuring someone is just being confident\""},{"id":"e","text":"Consent can be taken back at any time"},{"id":"f","text":"\"If they liked you once, they always owe you\""}],"bins":[{"id":"true","label":"True, confirm it","valence":"pos"},{"id":"myth","label":"Online myth, correct it","valence":"neg"}],"key":{"a":"true","b":"myth","c":"true","d":"myth","e":"true","f":"myth"},"relearn":"Confirm the true facts about consent and bodies; correct the online myths kindly, so your voice is the trusted one.","persona":"Vikram","source":"true or online myth"},
  {"id":"tk-1049","cat":"facts-and-values","type":"match","hook":"Match the child's stage to the facts-plus-values headline that fits it.","pairs":[{"left":"Early years","right":"Correct names and body safety, plus our kindness"},{"left":"Before puberty","right":"What's coming and why, plus 'never be ashamed'"},{"left":"Teen years","right":"Consent and online reality, plus respect both ways"},{"left":"Any age","right":"Honest answers, plus what our family believes"},{"left":"After a fumble","right":"The true correction, plus 'you can always ask me'"}],"relearn":"Each stage gets honest facts paired with your values; the facts shift with age, the both-and habit stays the same.","persona":"any","source":"stage to headline"},
  {"id":"tk-1080","type":"strike-rewrite","persona":"Divya","source":"start small now","hook":"\"I'll wait until my child is old enough to bring these things up themselves.\"","myth":{"un":"I'll wait until my child is old enough to bring these things up themselves.","re":"Start small now; a child who's never invited to ask usually stays quiet and learns from the feed instead.","why":"Waiting for them to start often means the talks never begin."},"relearn":"Don't wait for a child to raise it; start small, age-right chats now so they know they can come to you.","cat":"how-to-talk"},
  {"id":"tk-1081","type":"strike-rewrite","persona":"Vikram","source":"answering keeps you source","hook":"\"If I answer their questions, I'm just putting ideas in their head.\"","myth":{"un":"If I answer their questions, I'm just putting ideas in their head.","re":"Honest, age-right answers don't plant ideas; they keep you the trusted source instead of the internet.","why":"Answering protects; silence hands the topic to the algorithm."},"relearn":"Answering honestly doesn't put ideas in a child's head; it keeps you their trusted source over the feed.","cat":"how-to-talk"},
  {"id":"tk-1082","type":"strike-rewrite","persona":"Vikram","source":"both parents askable","hook":"\"These talks are really the mother's job, not mine.\"","myth":{"un":"These talks are really the mother's job, not mine.","re":"A child with two askable parents has two open doors; both of you being calm and willing doubles the safety.","why":"Two askable parents are better than one."},"relearn":"These talks aren't only a mother's job; both parents being askable gives a child two open doors.","cat":"how-to-talk"},
  {"id":"tk-1083","type":"strike-rewrite","persona":"any","source":"plain words land","hook":"\"I have to explain it perfectly, like a textbook, or I'll get it wrong.\"","myth":{"un":"I have to explain it perfectly, like a textbook, or I'll get it wrong.","re":"Simple, plain words at the child's level land far better than a perfect textbook speech.","why":"Clear and simple beats correct-but-overwhelming."},"relearn":"You don't need textbook-perfect answers; simple, plain words at a child's level land best.","cat":"how-to-talk"},
  {"id":"tk-1084","type":"strike-rewrite","persona":"Divya","source":"fumbling is fine","hook":"\"If I blush or stumble over my words, I've ruined the whole conversation.\"","myth":{"un":"If I blush or stumble over my words, I've ruined the whole conversation.","re":"Blushing or fumbling doesn't ruin it; staying warm and open is what your child actually remembers.","why":"Children remember that you stayed open, not that you were smooth."},"relearn":"Stumbling doesn't ruin a talk; staying warm and open is what your child remembers, not your polish.","cat":"how-to-talk"},
  {"id":"tk-1085","type":"strike-rewrite","persona":"any","source":"calm is the goal","hook":"\"If I stay calm and don't react, they'll think they can ask me anything.\"","myth":{"un":"If I stay calm and don't react, they'll think they can ask me anything.","re":"A child being able to ask you anything is exactly the goal; your calm is what keeps that door open.","why":"Being the one they can ask anything is the win, not the risk."},"relearn":"Staying calm so a child can ask you anything is the goal, not a danger; your calm keeps the door open.","cat":"how-to-talk"},
  {"id":"tk-1086","type":"strike-rewrite","persona":"Divya","source":"silence cedes field","hook":"\"They'll come and ask me when they're ready, so I don't need to start.\"","myth":{"un":"They'll come and ask me when they're ready, so I don't need to start.","re":"Most children won't raise it first; if you don't open the door, friends and screens answer instead.","why":"Your silence doesn't keep them neutral; it lets others teach them."},"relearn":"Most children won't bring it up first; if you stay silent, peers and screens fill the gap instead of you.","cat":"how-to-talk"},
  {"id":"tk-1087","type":"strike-rewrite","persona":"any","source":"many not one","hook":"\"Once I've had one good talk about all this, my job is basically done.\"","myth":{"un":"Once I've had one good talk about all this, my job is basically done.","re":"It's never one-and-done; it's many small chats over years as your child grows and new questions arise.","why":"Children grow into new questions; the door stays useful for years."},"relearn":"One talk is never enough; it's many small, age-right chats over the years as a child keeps growing.","cat":"how-to-talk"},
  {"id":"tk-1088","type":"strike-rewrite","persona":"any","source":"honour and park","hook":"\"I have to answer the very second they ask, and answer it perfectly.\"","myth":{"un":"I have to answer the very second they ask, and answer it perfectly.","re":"You can honour the question and park it briefly: 'great question, let's talk properly after dinner.'","why":"A warm 'let's talk later' keeps it safe to ask without rushing you."},"relearn":"You needn't answer perfectly on the spot; honour the question and park it warmly for a calmer moment.","cat":"how-to-talk"},
  {"id":"tk-1089","type":"strike-rewrite","persona":"Priya","source":"calm reassures","hook":"\"Talking about bodies and growing up will only frighten my child.\"","myth":{"un":"Talking about bodies and growing up will only frighten my child.","re":"Calm, honest, age-right answers reassure children; it's confusion and silence that leave them anxious.","why":"A calm answer settles a child; an avoided question worries them more."},"relearn":"Calm, age-right talks reassure rather than frighten; it's silence and confusion that leave a child anxious.","cat":"how-to-talk"},
  {"id":"tk-1090","type":"strike-rewrite","persona":"Vikram","source":"find out together","hook":"\"If I look unsure or don't know the answer, my child will lose trust in me.\"","myth":{"un":"If I look unsure or don't know the answer, my child will lose trust in me.","re":"'I don't know, let's find out together' builds trust; it models honesty and keeps you their go-to.","why":"Honest not-knowing earns more trust than a confident guess."},"relearn":"Not knowing won't cost you trust; 'let's find out together' models honesty and keeps you their go-to.","cat":"how-to-talk"},
  {"id":"tk-1091","type":"branch","persona":"Divya","source":"babies at dinner","hook":"At dinner your young child suddenly asks, in front of everyone, where babies come from.","options":[{"text":"Answer simply and truthfully at their level, calmly, right there","consequence":"Your child learns it's a normal thing to ask you.","outcome":"calm","best":true},{"text":"Laugh it off and say 'not at the table, ask later'","consequence":"Brushing it off teaches them it's shameful to ask you."}],"debrief":"Answer 'where do babies come from' simply and truthfully at the child's level, not with shame.","relearn":"Meet 'where do babies come from' with a simple, true, calm answer at their level, not a brush-off.","cat":"how-to-talk"},
  {"id":"tk-1092","type":"branch","persona":"any","source":"repair a fumble","hook":"Yesterday you snapped 'not now' at your child's question and you've felt bad since.","options":[{"text":"Go back: 'Sorry I shut you down yesterday. Ask me again, I'm listening now'","consequence":"Your child sees the door is genuinely always open.","outcome":"repair","best":true},{"text":"Say nothing and hope they forget they ever asked","consequence":"Silence teaches them not to bother asking again."}],"debrief":"Repair a fumbled answer by going back to it; it models honesty and shows the door is open.","relearn":"If you shut a question down, circle back and repair it; it reopens the door and models honesty.","cat":"how-to-talk"},
  {"id":"tk-1093","type":"branch","persona":"Vikram","source":"question in traffic","hook":"Your child asks a big body question while you're driving in heavy traffic and can't fully focus.","options":[{"text":"'Great question, I'll answer it properly when we park, remind me'","consequence":"Your child learns the question is welcome.","outcome":"park-it","best":true},{"text":"'Stop asking me weird things while I'm driving'","consequence":"Snapping teaches them the topic makes you angry."}],"debrief":"If you can't answer well now, honour the question and promise a proper answer soon, don't snap.","relearn":"Can't answer well in the moment? Honour the question and promise a proper answer soon, not a snap.","cat":"how-to-talk"},
  {"id":"tk-1094","type":"branch","persona":"Vikram","source":"saw cousin's phone","hook":"Your child says they saw something on an older cousin's phone and asks you what it meant.","options":[{"text":"Stay calm, thank them for asking, and explain simply and honestly","consequence":"They keep bringing you the confusing things they see.","outcome":"calm","best":true},{"text":"React with alarm and demand to know everything they saw","consequence":"Alarm teaches them to hide what they stumble on."}],"debrief":"Thank a child for bringing you something they saw and answer calmly, so they keep coming.","relearn":"When a child reports something they saw, stay calm and thank them, so they keep coming back.","cat":"how-to-talk"},
  {"id":"tk-1095","type":"branch","persona":"any","source":"a word from school","hook":"Your child repeats a crude word they heard at school and asks what it means.","options":[{"text":"Calmly explain what it means and why it can hurt, without scolding","consequence":"Your child learns the word and trusts you to explain anything.","outcome":"explain","best":true},{"text":"Scold them: 'Where did you hear that? Never say it again!'","consequence":"Scolding sends the next question to friends."}],"debrief":"When a child repeats a word they don't understand, explain it calmly, don't scold.","relearn":"Explain a word a child repeats calmly, not with a scolding; scolding just sends the next question away.","cat":"how-to-talk"},
  {"id":"tk-1096","type":"branch","persona":"Vikram","source":"don't know puberty","hook":"Your child asks a specific puberty question and you genuinely don't know the answer.","options":[{"text":"'Good question, I'm not sure, let's look it up together properly'","consequence":"Your child learns it's fine not to know and how to find out.","outcome":"together","best":true},{"text":"Make up an answer so you don't look unsure","consequence":"A made-up answer can mislead and erode trust later."}],"debrief":"If you don't know, say so and find out together; willingness beats pretending to know.","relearn":"Don't fake an answer you lack; say 'let's find out together'; willingness beats false certainty.","cat":"how-to-talk"},
  {"id":"tk-1097","type":"branch","persona":"Divya","source":"asked again","hook":"Your young child asks the very same body question for the fourth time this week.","options":[{"text":"Answer warmly again; repetition is how young children make sense of things","consequence":"Your child feels safe to keep processing with you.","outcome":"patient","best":true},{"text":"'I've already told you, stop asking me that'","consequence":"'Stop asking' teaches them their curiosity annoys you."}],"debrief":"Re-answer a repeated question warmly; repetition is how young children learn, not a reason to snap.","relearn":"Young children repeat questions to make sense of them; answer warmly again, not 'stop asking me'.","cat":"how-to-talk"},
  {"id":"tk-1098","type":"branch","persona":"Priya","source":"partner waves it off","hook":"Your child asks a body question and your partner instantly waves it off with 'you're too small'.","options":[{"text":"Gently step in: 'It's a great question, let me answer it'","consequence":"Your child sees at least one door stays open.","outcome":"open-door","best":true},{"text":"Stay quiet so you don't contradict your partner","consequence":"Silence lets the question get shut down twice over."}],"debrief":"If a question gets waved off, gently keep the door open yourself so the child has an askable adult.","relearn":"If your partner brushes a question off, gently keep the door open; a child needs one askable adult.","cat":"how-to-talk"},
  {"id":"tk-1099","type":"branch","persona":"any","source":"asked at a function","hook":"At a family function your child loudly asks why their aunt's tummy is so big.","options":[{"text":"Calmly: 'She's growing a baby, I'll tell you more at home'","consequence":"Your child gets an honest start and a calm follow-up promised.","outcome":"calm","best":true},{"text":"Hush them sharply and apologise to everyone","consequence":"Sharp hushing teaches them curiosity is embarrassing."}],"debrief":"Give a calm, true short answer in public and offer more later, not a hushing in shame.","relearn":"In public, give a calm true short answer and offer more later, not a hushing in embarrassment.","cat":"how-to-talk"},
  {"id":"tk-1100","type":"branch","persona":"any","source":"went quiet","hook":"You overreacted to a question last month and your child hasn't asked you anything since.","options":[{"text":"Gently reopen it: 'You can always ask me anything, I'll stay calm, I promise'","consequence":"Your child slowly learns the door is open again.","outcome":"reopen","best":true},{"text":"Wait and assume they'll start asking again on their own","consequence":"Waiting can let the silence quietly harden."}],"debrief":"If a child has gone quiet after you overreacted, actively reopen the door, don't wait.","relearn":"After overreacting, actively reopen the door with a calm invitation; don't just wait for them to try.","cat":"how-to-talk"},
  {"id":"tk-1101","type":"match","persona":"any","source":"line to effect","hook":"Match each thing a parent says to what it does for the child.","pairs":[{"left":"'Great question'","right":"Rewards them for coming to you"},{"left":"'Let's find out together'","right":"Models honesty when you don't know"},{"left":"'You can ask me anything'","right":"Opens the lifelong door"},{"left":"'Let's talk properly after dinner'","right":"Honours it while you find a calm moment"},{"left":"'That's normal and okay'","right":"Settles their worry"}],"relearn":"Phrases like 'great question' and 'you can ask me anything' reward curiosity and keep the door open.","cat":"how-to-talk"},
  {"id":"tk-1102","type":"match","persona":"any","source":"move to door effect","hook":"Match each parent move to its effect on the door staying open.","pairs":[{"left":"Staying calm and unshocked","right":"Keeps you their trusted source"},{"left":"Answering at the child's level","right":"Makes the answer actually land"},{"left":"Welcoming awkward questions","right":"Keeps them willing to ask"},{"left":"Repairing a fumbled answer","right":"Shows the door is truly always open"},{"left":"Many small chats over years","right":"Beats one dreaded big lecture"}],"relearn":"Calm answers, child-level wording, welcoming questions and repairing fumbles all keep the door open.","cat":"how-to-talk"},
  {"id":"tk-1103","type":"match","persona":"any","source":"moment to opener","hook":"Match each tricky moment to a calm way to open it.","pairs":[{"left":"You don't know the answer","right":"'Let's find out together'"},{"left":"A bad time to talk right now","right":"'Great question, let's talk after dinner'"},{"left":"You shut them down yesterday","right":"'Sorry, ask me again, I'm listening'"},{"left":"Starting the first conversation","right":"'You can always ask me anything'"},{"left":"They saw something confusing","right":"'Thanks for telling me, let's talk it through'"}],"relearn":"Each tricky moment has a calm opener that keeps you the askable parent, from 'let's find out together' on.","cat":"how-to-talk"},
  {"id":"tk-1104","type":"match","persona":"any","source":"reaction to message","hook":"Match each reaction to the hidden message a child takes from it.","pairs":[{"left":"Calm, warm answer","right":"'It's safe to ask my parent'"},{"left":"Shock or anger","right":"'I'd better not ask again'"},{"left":"'Ask your mother / father'","right":"'This door is closed'"},{"left":"'No question is silly'","right":"'My curiosity is welcome here'"},{"left":"Changing the subject","right":"'We don't talk about this at home'"}],"relearn":"A child reads your reaction: calm warmth says 'safe to ask'; shock or dodging says 'this door is closed'.","cat":"how-to-talk"},
  {"id":"tk-1105","type":"match","persona":"any","source":"tone to outcome","hook":"Match each tone a parent uses to where it leads.","pairs":[{"left":"Matter-of-fact and easy","right":"The topic feels ordinary, not shameful"},{"left":"Panicked and flustered","right":"The child senses danger in asking"},{"left":"Curious alongside them","right":"Learning together feels safe"},{"left":"Lecturing and long","right":"The child tunes out and stops asking"},{"left":"Gentle and unhurried","right":"There's room for the next question"}],"relearn":"A matter-of-fact, gentle tone makes the topic ordinary; panic or lecturing teaches a child to stop asking.","cat":"how-to-talk"},
  {"id":"tk-1106","type":"match","persona":"any","source":"habit to why","hook":"Match each open-door habit to why it works.","pairs":[{"left":"Little chats as things come up","right":"No single talk has to carry it all"},{"left":"Answering honestly, not perfectly","right":"Trust grows from honesty, not polish"},{"left":"Thanking them for asking","right":"Curiosity gets rewarded, so it continues"},{"left":"Staying askable through eye-rolls","right":"You remain a resource as they grow"},{"left":"Sharing your own gaps","right":"They learn not-knowing is normal"}],"relearn":"Open-door habits work because they reward curiosity and let trust grow from honesty over many small chats.","cat":"how-to-talk"},
  {"id":"tk-1107","type":"match","persona":"any","source":"style to effect","hook":"Match each answer style to its effect on a child.","pairs":[{"left":"Short and simple","right":"They take it in and come back for more"},{"left":"Long and anxious","right":"They feel overwhelmed and switch off"},{"left":"Honest 'I don't know'","right":"They trust you and learn to find out"},{"left":"Honouring and parking it","right":"It stays safe to ask later"},{"left":"Shaming the question","right":"They take it to friends instead"}],"relearn":"Short honest answers keep a child coming back; long anxious or shaming ones send them away from you.","cat":"how-to-talk"},
  {"id":"tk-1108","type":"reflect","persona":"any","source":"askable beats expert","hook":"Lensy: you don't have to be an expert on every topic, just the parent your child feels safe asking. Sit right?","prompt":"What's your take?","options":["Sits right","Askable over expert","Yes"],"affirm":"Being the askable, safe parent matters far more than knowing every answer; willingness beats expertise.","relearn":"You don't have to be an expert; being the askable parent your child feels safe with matters far more.","cat":"how-to-talk"},
  {"id":"tk-1109","type":"reflect","persona":"any","source":"each chat a deposit","hook":"Lensy: every small, calm chat is a little deposit in the trust that lets the big questions come later. Worth it?","prompt":"What do you think?","options":["Worth it","Small chats add up","Yes"],"affirm":"Each small calm chat deposits trust, so when the bigger, harder questions come, your child brings them to you.","relearn":"Every small, calm chat deposits trust, so the bigger questions later get brought to you, not the feed.","cat":"how-to-talk"},
  {"id":"tk-1110","type":"reflect","persona":"Vikram","source":"okay not to know","hook":"Lensy: it's completely okay not to have every answer ready; 'let's find out together' is a real answer. Agree?","prompt":"What's your take?","options":["Agree","Not-knowing is fine","Yes"],"affirm":"You don't need every answer ready; 'let's find out together' is honest, and it keeps you your child's guide.","relearn":"It's okay not to have every answer; 'let's find out together' is honest and keeps you your child's guide.","cat":"how-to-talk"},
  {"id":"tk-1111","type":"reflect","persona":"Divya","source":"calm is a gift","hook":"Lensy: your calm face when a child asks something hard is a gift, it tells them this is safe ground. Ring true?","prompt":"What do you think?","options":["Rings true","Calm is a gift","Yes"],"affirm":"A calm face when a child asks something hard tells them the topic is safe ground, and keeps them coming to you.","relearn":"Your calm when a child asks something hard tells them it's safe ground and keeps them coming to you.","cat":"how-to-talk"},
  {"id":"tk-1112","type":"reflect","persona":"any","source":"door reopens","hook":"Lensy: whatever's happened before, the door can reopen today with one calm 'you can always ask me'. Believe it?","prompt":"What's your take?","options":["Believe it","It's never too late","Yes"],"affirm":"It's never too late: whatever happened before, one calm invitation can reopen the door with your child today.","relearn":"Whatever happened before, the door reopens today with one calm 'you can always ask me'; it's never too late.","cat":"how-to-talk"},
  {"id":"tk-1113","type":"reflect","persona":"any","source":"honesty over perfect","hook":"Lensy: your child needs honest more than they need perfect; an honest fumble beats a polished silence. Sit right?","prompt":"What do you think?","options":["Sits right","Honest over perfect","Yes"],"affirm":"Children need honesty more than polish; an honest, fumbling answer beats a perfect-looking silence every time.","relearn":"Children need honest more than perfect; an honest, fumbling answer beats a polished silence every time.","cat":"how-to-talk"},
  {"id":"tk-1114","type":"reflect","persona":"Priya","source":"your voice belongs","hook":"Lensy: if you stay silent, the feed and the playground answer instead; your voice belongs in the mix. Agree?","prompt":"What's your take?","options":["Agree","My voice belongs","Yes"],"affirm":"Your voice belongs in the mix; staying silent doesn't keep a child neutral, it just lets others teach them.","relearn":"Staying silent doesn't keep a child neutral; the feed and peers fill the gap, so your voice belongs in it.","cat":"how-to-talk"},
  {"id":"tk-1115","type":"reflect","persona":"any","source":"curiosity is healthy","hook":"Lensy: a child's curiosity about bodies and growing up is healthy, not a problem to be managed. Ring true?","prompt":"What do you think?","options":["Rings true","Curiosity is healthy","Yes"],"affirm":"A child's curiosity about bodies and growing up is healthy and normal, not a problem; it's an invitation to talk.","relearn":"A child's curiosity about bodies and growing up is healthy and normal; treat it as an invitation to talk.","cat":"how-to-talk"},
  {"id":"tk-1116","type":"spot","persona":"any","source":"sends to internet","hook":"Spot the two reactions that send a child to the internet instead of to you.","scene":[{"id":"a","text":"Calm, honest answer at their level","trick":false},{"id":"b","text":"'You're too young to know that'","trick":true},{"id":"c","text":"'Great question, let's talk'","trick":false},{"id":"d","text":"Shock and a sharp 'who told you that?'","trick":true},{"id":"e","text":"Thanking them for asking you","trick":false}],"why":"'You're too young' and shocked interrogation are the door-closers that send a child to the feed for answers.","relearn":"Answer calmly and thank a child for asking; 'you're too young' and shock send them to the feed instead.","cat":"how-to-talk"},
  {"id":"tk-1117","type":"spot","persona":"any","source":"shuts a question down","hook":"Spot the two lines that shut a child's question down.","scene":[{"id":"a","text":"'Let me explain that simply'","trick":false},{"id":"b","text":"'We don't talk about that in this house'","trick":true},{"id":"c","text":"'No question is silly'","trick":false},{"id":"d","text":"'Ask me again after dinner, I'll answer'","trick":false},{"id":"e","text":"'Wait till you're older, not now'","trick":true}],"why":"'We don't talk about that' and 'wait till you're older' shut the door; the others keep it open.","relearn":"'We don't talk about that' and 'wait till you're older' shut a question down; keep the door open instead.","cat":"how-to-talk"},
  {"id":"tk-1118","type":"spot","persona":"any","source":"teaches shame","hook":"Spot the two responses that teach a child to feel ashamed for asking.","scene":[{"id":"a","text":"Answering warmly and matter-of-factly","trick":false},{"id":"b","text":"'Chee, don't be dirty, why ask that?'","trick":true},{"id":"c","text":"Using the calm, correct words","trick":false},{"id":"d","text":"A disgusted face and silence","trick":true},{"id":"e","text":"'I'm glad you asked me'","trick":false}],"why":"Calling a question dirty and reacting with disgust teach shame; warm, matter-of-fact answers don't.","relearn":"Calling a question dirty or reacting with disgust teaches shame; answer warmly and matter-of-factly instead.","cat":"how-to-talk"},
  {"id":"tk-1119","type":"spot","persona":"any","source":"closes the door","hook":"Spot the two moves that quietly close the door for next time.","scene":[{"id":"a","text":"'You can always come to me'","trick":false},{"id":"b","text":"Laughing at the child for asking","trick":true},{"id":"c","text":"Answering honestly, even if unsure","trick":false},{"id":"d","text":"'Go ask someone else, not me'","trick":true},{"id":"e","text":"Staying calm and unshocked","trick":false}],"why":"Laughing at the child and 'go ask someone else' close the door; the rest keep you the askable parent.","relearn":"Laughing at a child or 'go ask someone else' quietly closes the door; stay calm and answer to keep it open.","cat":"how-to-talk"},
  {"id":"tk-1120","type":"spot","persona":"any","source":"harder next time","hook":"Spot the two reactions that make the next, harder question tougher to ask.","scene":[{"id":"a","text":"A calm, simple answer","trick":false},{"id":"b","text":"Getting angry at the question","trick":true},{"id":"c","text":"'Thanks for trusting me with that'","trick":false},{"id":"d","text":"Changing the subject in a panic","trick":true},{"id":"e","text":"Welcoming the awkwardness","trick":false}],"why":"Anger and panicked subject-changing make the next question harder; calm, welcoming answers make it easier.","relearn":"Anger and panicked subject-changing make the next question harder; calm, welcoming answers make it easier.","cat":"how-to-talk"},
  {"id":"tk-1121","type":"spot","persona":"Vikram","source":"sends to peers","hook":"Spot the two responses that hand the topic over to a teen's friends.","scene":[{"id":"a","text":"Staying open and non-lecturing","trick":false},{"id":"b","text":"A long, judgemental lecture","trick":true},{"id":"c","text":"'I won't freak out, you can tell me'","trick":false},{"id":"d","text":"'That's disgusting, never mention it'","trick":true},{"id":"e","text":"Answering honestly without judging","trick":false}],"why":"Judgemental lectures and 'that's disgusting' send a teen to friends; staying open and honest keeps you in the loop.","relearn":"Judgemental lectures and 'that's disgusting' send a teen to friends; stay open and honest to keep them talking.","cat":"how-to-talk"},
  {"id":"tk-1122","type":"spot","persona":"any","source":"punishes curiosity","hook":"Spot the two reactions that punish a child for being curious.","scene":[{"id":"a","text":"'What a thoughtful thing to wonder'","trick":false},{"id":"b","text":"Snapping 'stop asking me that!'","trick":true},{"id":"c","text":"Answering at their level","trick":false},{"id":"d","text":"Embarrassing them in front of others","trick":true},{"id":"e","text":"A patient re-answer when they repeat it","trick":false}],"why":"Snapping and public embarrassment punish curiosity; patient, welcoming answers reward it instead.","relearn":"Snapping at or embarrassing a child punishes curiosity; patient, welcoming answers reward it instead.","cat":"how-to-talk"},
  {"id":"tk-1123","type":"role-play","persona":"Divya","source":"how did baby get in","hook":"Your young child asks, wide-eyed, 'How did the baby get inside the aunty's tummy?'","setup":"Answer simply and truthfully:","yourLine":[{"text":"'A baby grows in a special place inside a woman called the womb; I can tell you more as you grow.'","best":true},{"text":"'The stork brings it, now stop asking silly things.'"}],"relearn":"Give a simple, true answer about where a baby grows, not a stork story or a shutdown.","cat":"how-to-talk"},
  {"id":"tk-1124","type":"role-play","persona":"Divya","source":"why bodies differ","hook":"Your child asks why boys' and girls' bodies look different from each other.","setup":"Explain calmly and simply:","yourLine":[{"text":"'Bodies come in different kinds, and these are just the proper names for the parts; everyone's body is their own.'","best":true},{"text":"'That's not something nice children ask about.'"}],"relearn":"Explain body differences calmly with the proper names, not by shaming the child for wondering.","cat":"how-to-talk"},
  {"id":"tk-1125","type":"role-play","persona":"Vikram","source":"open first talk","hook":"You want to start the very first conversation with your child, before any awkward question arises.","setup":"Open the door warmly:","yourLine":[{"text":"'You can ask me anything about your body or growing up, anytime; no question is ever silly to me.'","best":true},{"text":"'We'll get into all of that when you're much, much older.'"}],"relearn":"Open the lifelong door with a clear invitation that any question is welcome, rather than deferring it for years.","cat":"how-to-talk"},
  {"id":"tk-1126","type":"role-play","persona":"any","source":"asked while cooking","hook":"Your child asks a big question while your hands are full at the stove.","setup":"Honour it without dropping everything:","yourLine":[{"text":"'Really good question. Give me two minutes to finish this, then I'll sit with you and answer it.'","best":true},{"text":"'Can't you see I'm busy? Don't bother me with that now.'"}],"relearn":"Honour a question even when busy and promise a proper answer soon, instead of brushing the child off.","cat":"how-to-talk"},
  {"id":"tk-1127","type":"role-play","persona":"any","source":"word from a song","hook":"Your child asks what a word means that they heard in a film song.","setup":"Answer it openly:","yourLine":[{"text":"'I'm glad you asked me instead of guessing. Let me tell you what it means and why some words can hurt.'","best":true},{"text":"'Where did you pick that up? Don't ever repeat it.'"}],"relearn":"Welcome a question about a word a child heard and explain it, rather than scolding them for asking.","cat":"how-to-talk"},
  {"id":"tk-1128","type":"role-play","persona":"any","source":"repair after snapping","hook":"You snapped at your child's question earlier and want to make it right.","setup":"Repair the moment:","yourLine":[{"text":"'I'm sorry I got short with you earlier. It was a fair question, ask me again and I'll answer it properly.'","best":true},{"text":"'Let's just forget you ever asked that.'"}],"relearn":"Repair a snapped answer by apologising and reopening it; that shows the door is genuinely always open.","cat":"how-to-talk"},
  {"id":"tk-1129","type":"role-play","persona":"any","source":"standing invitation","hook":"At bedtime you want to leave your child with a standing invitation to come back anytime.","setup":"Leave the door open:","yourLine":[{"text":"'Whatever you wonder about, big or small, my door's always open; you'll never be in trouble for asking.'","best":true},{"text":"'Only come to me if it's really, really important.'"}],"relearn":"Leave a child with a standing, no-trouble invitation to ask anything, rather than a high bar that closes the door.","cat":"how-to-talk"},
  {"id":"tk-1130","type":"role-play","persona":"Vikram","source":"kissing on TV","hook":"Your child sees people kissing on TV and asks you, puzzled, what they're doing.","setup":"Answer matter-of-factly:","yourLine":[{"text":"'They're showing they care about each other; it's something grown-ups who like each other sometimes do.'","best":true},{"text":"'Don't look at that! Change the channel and forget it.'"}],"relearn":"Give a calm, matter-of-fact answer about affection on screen, not a panicked 'don't look'.","cat":"how-to-talk"},
  {"id":"tk-1131","type":"role-play","persona":"Vikram","source":"saying I don't know","hook":"Your child asks something about how bodies work and you honestly don't know the answer.","setup":"Be honest about not knowing:","yourLine":[{"text":"'Honestly, I'm not sure about that one; let's look it up together and we'll both learn.'","best":true},{"text":"'Stop asking things even I don't know, it's annoying.'"}],"relearn":"Saying 'I'm not sure, let's find out together' models honesty and keeps you your child's go-to.","cat":"how-to-talk"},
  {"id":"tk-1132","type":"role-play","persona":"Priya","source":"backed in front of family","hook":"In front of relatives, your child asks a body question and the room goes quiet, eyes on you.","setup":"Back the question calmly:","yourLine":[{"text":"'That's a good thing to wonder about; I'll give you a proper answer when it's just us.'","best":true},{"text":"'How embarrassing, don't ask such things in front of everyone.'"}],"relearn":"Back a child's question calmly in front of others and promise a proper answer later, instead of shaming them.","cat":"how-to-talk"},
  {"id":"tk-1133","type":"role-play","persona":"any","source":"only got one word out","hook":"Your child asks a question and you freeze, only managing a flustered 'um'.","setup":"Recover and stay open:","yourLine":[{"text":"'Sorry, you caught me off guard, but it's a great question; let me gather my thoughts and answer it.'","best":true},{"text":"'Never mind, just don't ask me that again.'"}],"relearn":"If a question catches you off guard, name it and stay open; freezing then shutting down closes the door.","cat":"how-to-talk"},
  {"id":"tk-1134","type":"sort","persona":"any","source":"opens vs shuts","hook":"Sort each parent move: does it open the door or shut it?","items":[{"id":"a","text":"Calm, honest answer at their level"},{"id":"b","text":"Shock and a raised voice"},{"id":"c","text":"'Great question, let's talk'"},{"id":"d","text":"'You're too young to ask that'"},{"id":"e","text":"Thanking them for coming to you"},{"id":"f","text":"Changing the subject in a panic"}],"bins":[{"id":"open","label":"Opens the door","valence":"pos"},{"id":"shut","label":"Shuts it down","valence":"neg"}],"key":{"a":"open","b":"shut","c":"open","d":"shut","e":"open","f":"shut"},"relearn":"Calm honest answers and welcoming questions open the door; shock, 'too young' and panic shut it down.","cat":"how-to-talk"},
  {"id":"tk-1135","type":"sort","persona":"any","source":"source vs away","hook":"Sort each reaction: does it keep you the source, or send your child away?","items":[{"id":"a","text":"Answering simply and truthfully"},{"id":"b","text":"'Go ask your friends'"},{"id":"c","text":"Staying calm and unshocked"},{"id":"d","text":"Getting angry at the question"},{"id":"e","text":"'Let's find out together'"},{"id":"f","text":"Disgust and a 'chee, don't'"}],"bins":[{"id":"source","label":"Keeps you the source","valence":"pos"},{"id":"away","label":"Sends them away","valence":"neg"}],"key":{"a":"source","b":"away","c":"source","d":"away","e":"source","f":"away"},"relearn":"Calm, honest answers keep you a child's source; anger, disgust and 'ask your friends' send them away.","cat":"how-to-talk"},
  {"id":"tk-1136","type":"sort","persona":"any","source":"now vs later content","hook":"Sort what's age-right to answer NOW for a young child, versus saved for LATER.","items":[{"id":"a","text":"The correct names for body parts"},{"id":"b","text":"Explicit details of adult sex"},{"id":"c","text":"'Private parts are just for you'"},{"id":"d","text":"The complexities of adult relationships"},{"id":"e","text":"'You're the boss of your own body'"},{"id":"f","text":"Graphic specifics they didn't ask for"}],"bins":[{"id":"now","label":"Age-right now","valence":"pos"},{"id":"later","label":"Save for later","valence":"uhoh"}],"key":{"a":"now","b":"later","c":"now","d":"later","e":"now","f":"later"},"relearn":"Correct names, privacy and body ownership are age-right now; explicit adult details are saved for later.","cat":"how-to-talk"},
  {"id":"tk-1137","type":"sort","persona":"any","source":"builds vs erodes trust","hook":"Sort each habit: does it build a child's trust, or erode it?","items":[{"id":"a","text":"Honest answers, even 'I don't know'"},{"id":"b","text":"Making up an answer to look sure"},{"id":"c","text":"Going back to repair a fumble"},{"id":"d","text":"Pretending the question never happened"},{"id":"e","text":"Keeping your calm every time"},{"id":"f","text":"Laughing the question off"}],"bins":[{"id":"builds","label":"Builds trust","valence":"pos"},{"id":"erodes","label":"Erodes trust","valence":"neg"}],"key":{"a":"builds","b":"erodes","c":"builds","d":"erodes","e":"builds","f":"erodes"},"relearn":"Honesty, repairing fumbles and staying calm build trust; faking answers and laughing them off erode it.","cat":"how-to-talk"},
  {"id":"tk-1138","type":"sort","persona":"any","source":"invites vs deters","hook":"Sort each thing you say: does it invite the next question or deter it?","items":[{"id":"a","text":"'No question is silly'"},{"id":"b","text":"'We don't discuss such things'"},{"id":"c","text":"'You can ask me anything'"},{"id":"d","text":"'Wait until you're much older'"},{"id":"e","text":"'I'm glad you came to me'"},{"id":"f","text":"'That's not a nice thing to ask'"}],"bins":[{"id":"invites","label":"Invites the next question","valence":"pos"},{"id":"deters","label":"Deters it","valence":"neg"}],"key":{"a":"invites","b":"deters","c":"invites","d":"deters","e":"invites","f":"deters"},"relearn":"'No question is silly' and 'ask me anything' invite the next question; 'we don't discuss that' deters it.","cat":"how-to-talk"},
  {"id":"tk-1139","type":"sort","persona":"any","source":"calm vs panicked","hook":"Sort each response into calm-and-askable, or panicked-and-closing.","items":[{"id":"a","text":"A steady, matter-of-fact tone"},{"id":"b","text":"A flustered, flushed shut-down"},{"id":"c","text":"'Let me think and answer properly'"},{"id":"d","text":"Snapping 'why would you ask that?'"},{"id":"e","text":"A warm 'thanks for asking'"},{"id":"f","text":"Quickly changing the subject"}],"bins":[{"id":"calm","label":"Calm and askable","valence":"pos"},{"id":"panic","label":"Panicked and closing","valence":"neg"}],"key":{"a":"calm","b":"panic","c":"calm","d":"panic","e":"calm","f":"panic"},"relearn":"A steady, warm, matter-of-fact response stays askable; flustering, snapping and dodging close the door.","cat":"how-to-talk"},
  {"id":"tk-1140","type":"sort","persona":"any","source":"one talk myth vs truth","hook":"Sort each idea about RSE talks as a myth to drop, or a truth to keep.","items":[{"id":"a","text":"It's many small chats over years"},{"id":"b","text":"It's one big dreaded talk"},{"id":"c","text":"'I don't know' is a fine answer"},{"id":"d","text":"I must have every answer ready"},{"id":"e","text":"Willingness beats expertise"},{"id":"f","text":"Talking gives children ideas"}],"bins":[{"id":"keep","label":"True, keep it","valence":"pos"},{"id":"drop","label":"Myth, drop it","valence":"neg"}],"key":{"a":"keep","b":"drop","c":"keep","d":"drop","e":"keep","f":"drop"},"relearn":"Truths to keep: many small chats, 'I don't know' is fine, willingness beats expertise; drop the dreaded-talk myths.","cat":"how-to-talk"},
  {"id":"tk-1170","cat":"middle-years","type":"strike-rewrite","hook":"\"If I mention periods early, I'll just scare her.\"","myth":{"un":"If I mention periods early, I'll just scare her.","re":"A calm heads-up before periods start makes the first one feel expected and supported, not a frightening shock.","why":"Warned in advance, she meets it ready, not afraid."},"relearn":"A warm, early heads-up about periods makes the first one feel expected, not frightening.","persona":"Divya","source":"early heads-up calms"},
  {"id":"tk-1171","cat":"middle-years","type":"strike-rewrite","hook":"\"My son doesn't need to know anything about periods.\"","myth":{"un":"My son doesn't need to know anything about periods.","re":"Every child learns about everyone's puberty, periods and wet dreams alike, so they grow up with empathy instead of teasing.","why":"Knowing the facts ends the giggling and the shame."},"relearn":"All children learn about everyone's puberty; it builds empathy and ends teasing.","persona":"Vikram","source":"boys learn periods too"},
  {"id":"tk-1172","cat":"middle-years","type":"strike-rewrite","hook":"\"Hand a child a phone and they'll work the safety out themselves.\"","myth":{"un":"Hand a child a phone and they'll work the safety out themselves.","re":"Pair a first device with simple, ongoing talks about privacy and telling you about anything off; don't hand it over in silence.","why":"A device plus a conversation beats a device alone."},"relearn":"Pair a first device with simple online-safety talks, not a silent handover.","persona":"Vikram","source":"device needs a talk"},
  {"id":"tk-1173","cat":"middle-years","type":"strike-rewrite","hook":"\"A wet dream means something is wrong with my child.\"","myth":{"un":"A wet dream means something is wrong with my child.","re":"Wet dreams are a normal, healthy part of growing up; a calm word beforehand stops a child thinking they've done something bad.","why":"Named as normal, it never feels like a fault."},"relearn":"Wet dreams are normal; a calm, matter-of-fact heads-up prevents needless shame.","persona":"any","source":"wet dreams are normal"},
  {"id":"tk-1174","cat":"middle-years","type":"strike-rewrite","hook":"\"If she reports a scary video, taking the phone away keeps her safe.\"","myth":{"un":"If she reports a scary video, taking the phone away keeps her safe.","re":"Thank a child for telling you and talk it through; punishing the messenger only teaches them to hide the next scary thing.","why":"Thanked, she keeps coming to you; punished, she goes quiet."},"relearn":"Thank a child for reporting scary content; punishment teaches them to hide it.","persona":"Vikram","source":"thank not punish"},
  {"id":"tk-1175","cat":"middle-years","type":"strike-rewrite","hook":"\"There's plenty of time, I'll start once the changes actually begin.\"","myth":{"un":"There's plenty of time, I'll start once the changes actually begin.","re":"The pre-puberty years are the golden window; a child prepared before the changes start handles them far better.","why":"Prepared early, the changes arrive as no surprise."},"relearn":"Prepare before puberty starts; the pre-puberty years are the golden window.","persona":"any","source":"golden window"},
  {"id":"tk-1176","cat":"middle-years","type":"strike-rewrite","hook":"\"If I look unsure answering a frank question, I've already failed.\"","myth":{"un":"If I look unsure answering a frank question, I've already failed.","re":"\"I'm not sure, let's find out together\" is an honest answer; willingness to stay in the talk matters more than a perfect reply.","why":"Staying in the conversation is the real win."},"relearn":"\"Let's find out together\" is a good answer; willingness beats perfect expertise.","persona":"any","source":"let's find out together"},
  {"id":"tk-1177","cat":"middle-years","type":"strike-rewrite","hook":"\"Schools cover all the puberty talk, so I can leave it to them.\"","myth":{"un":"Schools cover all the puberty talk, so I can leave it to them.","re":"A lesson at school is a start, not the whole story; your calm answers at home make you the source your child keeps returning to.","why":"Home talks are where the real questions land."},"relearn":"School lessons help, but your home talks keep you the source your child returns to.","persona":"Priya","source":"home not just school"},
  {"id":"tk-1178","cat":"middle-years","type":"sort","hook":"Sort: prepare a child for this before puberty, or save it for the teen years?","items":[{"id":"a","text":"Periods are a normal, healthy sign of growing up"},{"id":"b","text":"Wet dreams happen and nothing is wrong"},{"id":"c","text":"Basic privacy and online safety"},{"id":"d","text":"Detailed advice on adult relationships"},{"id":"e","text":"What sweat, hair and mood changes mean"},{"id":"f","text":"Navigating consent in a dating relationship"}],"bins":[{"id":"now","label":"Prep before puberty","valence":"pos"},{"id":"later","label":"Save for the teen years","valence":"uhoh"}],"key":{"a":"now","b":"now","c":"now","d":"later","e":"now","f":"later"},"relearn":"Periods, wet dreams, body changes and online basics suit pre-puberty; detailed adult relationship advice waits.","persona":"any","source":"now or teen years"},
  {"id":"tk-1179","cat":"middle-years","type":"sort","hook":"Sort each online habit: a green habit, or a risk to talk through?","items":[{"id":"a","text":"Telling you about a creepy message"},{"id":"b","text":"Sending a stranger their address"},{"id":"c","text":"Keeping the account private"},{"id":"d","text":"Meeting an online 'friend' alone"},{"id":"e","text":"Asking before downloading an app"},{"id":"f","text":"Sharing location with everyone"}],"bins":[{"id":"green","label":"Green habit","valence":"pos"},{"id":"risk","label":"Risk to address","valence":"neg"}],"key":{"a":"green","b":"risk","c":"green","d":"risk","e":"green","f":"risk"},"relearn":"Telling you, staying private and asking first are green; sharing details, meeting strangers and open location are risks.","persona":"Vikram","source":"green habit or risk"},
  {"id":"tk-1180","cat":"middle-years","type":"sort","hook":"Sort how you reacted when your pre-teen asked about bodies: kept the door open, or shut it?","items":[{"id":"a","text":"\"Great question, let me explain simply\""},{"id":"b","text":"\"That's dirty, don't ask me that\""},{"id":"c","text":"\"You can ask me anything, anytime\""},{"id":"d","text":"\"You're too young to know\""},{"id":"e","text":"\"I'm not sure, let's look it up together\""},{"id":"f","text":"Laughing it off and changing the subject"}],"bins":[{"id":"open","label":"Keeps the door open","valence":"pos"},{"id":"shut","label":"Shuts the door","valence":"neg"}],"key":{"a":"open","b":"shut","c":"open","d":"shut","e":"open","f":"shut"},"relearn":"Welcoming the question and offering to find out together keeps the door open; shaming or dismissing shuts it.","persona":"any","source":"door open or shut"},
  {"id":"tk-1181","cat":"middle-years","type":"sort","hook":"Sort: which belong in the 'before her first period' heads-up?","items":[{"id":"a","text":"What a period is, in simple words"},{"id":"b","text":"That it's normal and you'll help her"},{"id":"c","text":"Where pads are kept at home"},{"id":"d","text":"A long lecture on adult reproduction"},{"id":"e","text":"That she can come to you anytime"},{"id":"f","text":"A warning to keep it a secret"}],"bins":[{"id":"pack","label":"Include it","valence":"pos"},{"id":"leave","label":"Leave it out","valence":"neg"}],"key":{"a":"pack","b":"pack","c":"pack","d":"leave","e":"pack","f":"leave"},"relearn":"A first-period heads-up gives simple facts, reassurance, where supplies are and an open invitation; no lectures, no secrecy.","persona":"Divya","source":"first-period kit"},
  {"id":"tk-1182","cat":"middle-years","type":"sort","hook":"Sort each line: a calm, normalising reply about body changes, or one that lands as shame?","items":[{"id":"a","text":"\"Everyone's body changes, it's healthy\""},{"id":"b","text":"\"Why are you so obsessed with this?\""},{"id":"c","text":"\"That's a normal part of growing up\""},{"id":"d","text":"\"Nice children don't talk like that\""},{"id":"e","text":"\"Good question, here's how it works\""},{"id":"f","text":"\"Stop being so dramatic about it\""}],"bins":[{"id":"calm","label":"Calm and normalising","valence":"pos"},{"id":"shame","label":"Lands as shame","valence":"neg"}],"key":{"a":"calm","b":"shame","c":"calm","d":"shame","e":"calm","f":"shame"},"relearn":"Naming changes as normal and healthy reassures; calling a child obsessed, dramatic or not-nice teaches shame.","persona":"any","source":"calm or shame"},
  {"id":"tk-1183","cat":"middle-years","type":"sort","hook":"Sort each first-phone move: a safety step to set up, or a habit to rethink?","items":[{"id":"a","text":"Agreeing screen-time limits together"},{"id":"b","text":"Letting them follow back any stranger"},{"id":"c","text":"Setting up reporting and block buttons"},{"id":"d","text":"Keeping the phone secret from you"},{"id":"e","text":"Promising to tell you about anything scary"},{"id":"f","text":"Posting their daily location publicly"}],"bins":[{"id":"setup","label":"Set it up","valence":"pos"},{"id":"rethink","label":"Rethink it","valence":"neg"}],"key":{"a":"setup","b":"rethink","c":"setup","d":"rethink","e":"setup","f":"rethink"},"relearn":"Shared limits, block/report tools and a promise to tell you are safety steps; secret phones, following strangers and public location are not.","persona":"Vikram","source":"phone setup or rethink"},
  {"id":"tk-1184","cat":"middle-years","type":"sort","hook":"Sort what a pre-teen is ready to understand about periods and puberty now.","items":[{"id":"a","text":"Periods are a normal monthly cycle"},{"id":"b","text":"Hair grows in new places as you grow"},{"id":"c","text":"How to manage cramps and supplies"},{"id":"d","text":"Graphic, explicit sexual detail"},{"id":"e","text":"Voices and bodies change at different paces"},{"id":"f","text":"Adult contraception choices in depth"}],"bins":[{"id":"ready","label":"Ready for it now","valence":"pos"},{"id":"wait","label":"Wait until older","valence":"uhoh"}],"key":{"a":"ready","b":"ready","c":"ready","d":"wait","e":"ready","f":"wait"},"relearn":"Cycles, body hair, managing periods and different paces suit now; explicit detail and in-depth contraception wait.","persona":"any","source":"ready now or wait"},
  {"id":"tk-1185","cat":"middle-years","type":"sort","hook":"Sort: when your child shows you something online, which reactions keep them telling you?","items":[{"id":"a","text":"\"Thank you for showing me\""},{"id":"b","text":"Shouting and snatching the device"},{"id":"c","text":"\"Let's look at it together calmly\""},{"id":"d","text":"\"You're banned from the internet now\""},{"id":"e","text":"\"You did the right thing telling me\""},{"id":"f","text":"Mocking them for being upset by it"}],"bins":[{"id":"keeps","label":"Keeps them telling you","valence":"pos"},{"id":"silences","label":"Silences them","valence":"neg"}],"key":{"a":"keeps","b":"silences","c":"keeps","d":"silences","e":"keeps","f":"silences"},"relearn":"Thanking them, looking together calmly and praising the telling keep the door open; shouting, banning and mocking close it.","persona":"Vikram","source":"keeps telling or silences"},
  {"id":"tk-1186","cat":"middle-years","type":"branch","hook":"Your daughter, nearly ten, hasn't started periods yet, and you haven't mentioned them.","options":[{"text":"Bring it up warmly now, before they start","consequence":"She meets her first period feeling expected and supported.","outcome":"prepared","best":true},{"text":"Wait and explain it only once they begin","consequence":"Waiting risks a frightening shock when it arrives with no warning."}],"debrief":"Prepare a child for periods before they begin so the first one feels expected, not a frightening surprise.","relearn":"Explain periods before they start so the first never comes as a shock.","persona":"Divya","source":"before they start"},
  {"id":"tk-1187","cat":"middle-years","type":"branch","hook":"Your son says boys at school tease a classmate who got her period in class.","options":[{"text":"Explain periods are normal and teasing is cruel, calmly","consequence":"He learns empathy and the giggling loses its grip.","outcome":"empathy","best":true},{"text":"Say it's girls' business and none of his concern","consequence":"Leaving him ignorant lets the teasing and shame carry on."}],"debrief":"Teaching every child about everyone's puberty builds empathy and ends the teasing and shame.","relearn":"All children learn about everyone's puberty; it builds empathy and ends teasing.","persona":"Vikram","source":"end the teasing"},
  {"id":"tk-1188","cat":"middle-years","type":"branch","hook":"Your pre-teen is about to get their first phone for the bus journey to school.","options":[{"text":"Hand it over with a few simple online-safety talks","consequence":"They start their online life with a safety net and you in the loop.","outcome":"safe-start","best":true},{"text":"Hand it over with no conversation at all","consequence":"A silent handover leaves them to figure out the internet alone."}],"debrief":"Pair a first device with simple talks on privacy, kindness and telling you anything scary.","relearn":"Pair a first device with simple online-safety talks, not a silent handover.","persona":"Vikram","source":"first phone talk"},
  {"id":"tk-1189","cat":"middle-years","type":"branch","hook":"Your child says a video popped up that frightened them while they were on the tablet.","options":[{"text":"Stay calm, thank them for telling you, talk it through","consequence":"They learn that telling you is safe and worth doing again.","outcome":"safe-telling","best":true},{"text":"Get angry and confiscate the tablet as punishment","consequence":"Anger and punishment teach them to hide the next scary thing."}],"debrief":"Thank a child for reporting scary content and talk it through; anger teaches them to hide it.","relearn":"Thank a child for reporting scary content; punishment teaches them to hide it.","persona":"Vikram","source":"calm and thank"},
  {"id":"tk-1190","cat":"middle-years","type":"branch","hook":"Your nine-year-old asks, point-blank, \"How do babies actually get made?\"","options":[{"text":"Give a simple, true, age-right answer without shame","consequence":"You stay their trusted source for the harder questions ahead.","outcome":"honest","best":true},{"text":"Tell them a stork brought them and laugh it off","consequence":"A made-up story teaches them you won't give straight answers."}],"debrief":"Answer \"where do babies come from?\" with a simple, true answer at the child's level, never a stork story.","relearn":"Give a simple, honest answer; never a stork story or a shutdown.","persona":"any","source":"simple true answer"},
  {"id":"tk-1191","cat":"middle-years","type":"branch","hook":"You realise your child will hit puberty before you've said a word about it.","options":[{"text":"Start small, age-right chats now, before the changes","consequence":"You catch the golden window and they arrive prepared.","outcome":"golden-window","best":true},{"text":"Decide it's too awkward and hope school covers it","consequence":"Hoping school covers it leaves them to face changes unwarned."}],"debrief":"Use the pre-puberty golden window: small age-right chats now so the changes never shock them.","relearn":"Prepare before puberty starts; the pre-puberty years are the golden window.","persona":"any","source":"use the window"},
  {"id":"tk-1192","cat":"middle-years","type":"branch","hook":"A frank pre-teen question catches you out and you genuinely don't know the answer.","options":[{"text":"Say \"I'm not sure, let's find out together\"","consequence":"They see honesty modelled and the door stays open.","outcome":"learn-together","best":true},{"text":"Bluff a wrong answer so you don't look unsure","consequence":"A bluff risks bad facts and being caught out later."}],"debrief":"\"I don't know, let's find out together\" is an honest answer; willingness beats expertise.","relearn":"\"Let's find out together\" is a good answer; willingness beats perfect expertise.","persona":"any","source":"don't know is fine"},
  {"id":"tk-1193","cat":"middle-years","type":"branch","hook":"Your pre-teen says an online 'friend' they've never met wants to video-call alone.","options":[{"text":"Thank them and set the rule together: no solo contact with strangers","consequence":"They stay safe and learn telling you keeps them in control.","outcome":"safe-rule","best":true},{"text":"Panic, ban all internet, lecture angrily","consequence":"A blanket ban teaches them not to mention it next time."}],"debrief":"Video-calling online strangers alone is a risk; thank the child for telling and set the rule calmly.","relearn":"Talk through stranger-contact calmly; meeting strangers is a risk to address.","persona":"Vikram","source":"online stranger rule"},
  {"id":"tk-1194","cat":"middle-years","type":"branch","hook":"Your child is anxious that they're developing later than their friends.","options":[{"text":"Reassure them everyone's body changes at its own pace","consequence":"Their worry eases and they keep confiding in you.","outcome":"reassured","best":true},{"text":"Brush it off with \"don't worry about silly things\"","consequence":"Brushing it off tells them this worry isn't safe to share."}],"debrief":"Reassure a child that bodies change at different paces; taking the worry seriously keeps them confiding.","relearn":"Bodies change at different paces; take the worry seriously and reassure, don't dismiss.","persona":"any","source":"different paces"},
  {"id":"tk-1195","cat":"middle-years","type":"branch","hook":"Your son asks shyly what the boys mean by 'wet dreams', clearly worried about himself.","options":[{"text":"Calmly explain it's a normal, healthy part of growing up","consequence":"His worry lifts and he learns nothing is wrong with him.","outcome":"normalised","best":true},{"text":"Tell him that's not something to discuss with you","consequence":"Refusing leaves his worry unanswered and sends him to peers."}],"debrief":"Explain wet dreams calmly as a normal part of growing up so a child knows nothing is wrong.","relearn":"Wet dreams are normal; a calm, matter-of-fact answer prevents needless shame.","persona":"any","source":"wet dream worry"},
  {"id":"tk-1196","cat":"middle-years","type":"branch","hook":"A relative says you're 'spoiling' your pre-teen by explaining puberty so openly.","options":[{"text":"Calmly say preparing her keeps her safe and unafraid","consequence":"You hold your ground and the talks continue.","outcome":"backed","best":true},{"text":"Apologise and stop the 'early' talks","consequence":"Backing down signals the talks were wrong and silences them."}],"debrief":"Stand by age-right preparation calmly; it keeps a child safer, even if a relative disapproves.","relearn":"Preparing a child for puberty keeps them safer; hold the line if relatives disapprove.","persona":"Priya","source":"back the talks"},
  {"id":"tk-1197","cat":"middle-years","type":"match","hook":"Match each pre-teen topic to a calm, normalising way to open it.","pairs":[{"left":"Periods","right":"\"A normal, healthy sign of growing up.\""},{"left":"Wet dreams","right":"\"This happens to bodies; nothing's wrong.\""},{"left":"Body odour","right":"\"Time to add a wash routine, that's all.\""},{"left":"Mood swings","right":"\"Big feelings come with these changes too.\""},{"left":"Growth spurts","right":"\"Everyone grows at their own pace.\""}],"relearn":"Periods, wet dreams, odour, moods and growth each have a calm, normalising line to open the conversation.","persona":"any","source":"normalising openers"},
  {"id":"tk-1198","cat":"middle-years","type":"match","hook":"Match each first-phone worry to the simple safety habit that answers it.","pairs":[{"left":"Strangers messaging","right":"Tell me about anyone who makes you uneasy"},{"left":"Oversharing details","right":"Keep your name, school and address private"},{"left":"Scary content","right":"Show me anything that frightens you"},{"left":"Account safety","right":"Use a private setting and a strong password"},{"left":"Endless scrolling","right":"Agree screen-time limits together"}],"relearn":"Each online worry has a simple habit: tell me, keep details private, show me scary things, lock accounts, agree limits.","persona":"Vikram","source":"worry to habit"},
  {"id":"tk-1199","cat":"middle-years","type":"match","hook":"Match each pre-teen question to a calm, honest opener you could use.","pairs":[{"left":"\"What's a period?\"","right":"\"It's a normal monthly cycle; let me explain.\""},{"left":"\"Why is my body changing?\"","right":"\"That's puberty, it happens to everyone.\""},{"left":"\"Where do babies come from?\"","right":"\"A simple, true answer at your level.\""},{"left":"\"What's that word online?\"","right":"\"Good you asked; here's what it really means.\""},{"left":"\"Am I normal?\"","right":"\"Yes, bodies change at their own pace.\""}],"relearn":"Each frank pre-teen question has a calm, honest opener that keeps you the trusted source.","persona":"any","source":"question to opener"},
  {"id":"tk-1200","cat":"middle-years","type":"match","hook":"Match each puberty change to the practical kit or routine that helps with it.","pairs":[{"left":"First period","right":"Pads kept somewhere she can reach"},{"left":"Body odour","right":"A daily wash-and-deodorant routine"},{"left":"Oily skin","right":"A gentle face-wash habit"},{"left":"Cramps","right":"A warm compress and rest"},{"left":"Faster growth","right":"Bigger clothes and good sleep"}],"relearn":"Each puberty change pairs with a simple, practical routine, so the changes feel manageable, not alarming.","persona":"Divya","source":"change to routine"},
  {"id":"tk-1201","cat":"middle-years","type":"match","hook":"Match each pre-teen reaction with the parent line that keeps the door open.","pairs":[{"left":"Embarrassed to ask","right":"\"No question is silly, ask me anything.\""},{"left":"Asked something you don't know","right":"\"Let's find out together.\""},{"left":"Showed you scary content","right":"\"Thank you for telling me.\""},{"left":"Worried they're 'late'","right":"\"Everyone changes at their own pace.\""},{"left":"Caught off-guard mid-chore","right":"\"Great question, let's talk after dinner.\""}],"relearn":"Each pre-teen reaction has a parent line, welcoming, honest, grateful, reassuring, that keeps the door open.","persona":"any","source":"reaction to line"},
  {"id":"tk-1202","cat":"middle-years","type":"match","hook":"Match each online red flag your pre-teen might meet to the safe move.","pairs":[{"left":"A stranger asks to meet up","right":"Say no and tell a parent"},{"left":"Someone asks for a photo","right":"Don't send it; show me"},{"left":"A message feels threatening","right":"Block, report and tell me"},{"left":"An app wants your location","right":"Keep it off unless we agree"},{"left":"A friend dares a risky post","right":"Pause and check with me first"}],"relearn":"Each online red flag has a safe move: refuse, don't send, block and report, keep location off, check first.","persona":"Vikram","source":"red flag to safe move"},
  {"id":"tk-1203","cat":"middle-years","type":"match","hook":"Match each pre-teen myth to the calm truth that replaces it.","pairs":[{"left":"\"Only girls learn about periods\"","right":"Every child learns; it builds empathy"},{"left":"\"Wait until puberty starts\"","right":"Prepare before, so it's no shock"},{"left":"\"A device needs no talk\"","right":"Pair a first phone with safety chats"},{"left":"\"Reporting scary content is punished\"","right":"Telling me is always thanked"},{"left":"\"Asking about bodies is shameful\"","right":"No body question is silly"}],"relearn":"Each pre-teen myth has a calm truth: everyone learns, prepare early, talk, thank reporting, no shame.","persona":"any","source":"myth to truth"},
  {"id":"tk-1204","cat":"middle-years","type":"reflect","hook":"Lensy: a child warned about periods before her first one feels ready, not terrified. What's your take?","prompt":"What do you think?","options":["Worth doing early","Ready, not scared","Yes, prepare her"],"affirm":"Preparing a child before periods start swaps fear and shame for readiness and confidence.","relearn":"A child prepared for periods before they start feels ready, not terrified.","persona":"Divya","source":"ready not scared"},
  {"id":"tk-1205","cat":"middle-years","type":"reflect","hook":"Lensy: when every child learns about everyone's puberty, the teasing fades. Agree?","prompt":"What's your view?","options":["Agree","Ends the teasing","Everyone should learn"],"affirm":"All children learning about everyone's puberty builds empathy and ends the shame and teasing.","relearn":"All children learn about everyone's puberty; it builds empathy and ends teasing.","persona":"Vikram","source":"empathy ends teasing"},
  {"id":"tk-1206","cat":"middle-years","type":"reflect","hook":"Lensy: a first phone is easier when it comes with a few simple safety chats. Sound right?","prompt":"What do you reckon?","options":["Sounds right","Phone plus a talk","Yes, talk it through"],"affirm":"Pairing a first device with simple safety talks gives a child a net instead of leaving them alone online.","relearn":"Pair a first device with simple online-safety talks, not a silent handover.","persona":"Vikram","source":"phone plus talk"},
  {"id":"tk-1207","cat":"middle-years","type":"reflect","hook":"Lensy: thanking a child for reporting something scary makes them likelier to tell you again. True for you?","prompt":"What do you think?","options":["True","Thanks keeps them telling","Yes, stay calm"],"affirm":"Thanking a child for reporting scary content, and staying calm, keeps them coming to you next time.","relearn":"Thank a child for reporting scary content; calm keeps them telling you.","persona":"any","source":"thanks keeps telling"},
  {"id":"tk-1208","cat":"middle-years","type":"reflect","hook":"Lensy: \"I don't know, let's find out together\" is a perfectly good answer to a pre-teen. Agree?","prompt":"What's your take?","options":["Agree","Honest beats perfect","Yes, find out together"],"affirm":"Admitting you don't know and finding out together models honesty and keeps the conversation open.","relearn":"\"Let's find out together\" is a good answer; willingness beats perfect expertise.","persona":"any","source":"honest beats perfect"},
  {"id":"tk-1209","cat":"middle-years","type":"reflect","hook":"Lensy: the years just before puberty are the golden window to prepare a child. Worth using?","prompt":"What do you think?","options":["Worth using","Catch the window","Yes, start now"],"affirm":"The pre-puberty years are the ideal window to prepare a child so the changes feel manageable.","relearn":"The years just before puberty are the golden window; prepared kids cope far better.","persona":"any","source":"catch the window"},
  {"id":"tk-1210","cat":"middle-years","type":"reflect","hook":"Lensy: a frank pre-teen question answered calmly makes the next, harder one easier to ask. Ring true?","prompt":"What's your view?","options":["Rings true","Each answer opens the next","Yes, stay calm"],"affirm":"Every calmly answered question makes the next, harder one easier to ask, and keeps you the source.","relearn":"A calm answer now makes the next, harder question easier to ask.","persona":"any","source":"next question easier"},
  {"id":"tk-1211","cat":"middle-years","type":"reflect","hook":"Lensy: telling a child their body changes at its own pace eases a lot of quiet pre-teen worry. Agree?","prompt":"What do you think?","options":["Agree","Own pace reassures","Yes, reassure them"],"affirm":"Reassuring a child that bodies change at their own pace eases worry and keeps them confiding in you.","relearn":"Bodies change at different paces; saying so eases pre-teen worry.","persona":"any","source":"own pace reassures"},
  {"id":"tk-1212","cat":"middle-years","type":"spot","hook":"Spot the two lines that would shame a pre-teen for asking about their changing body.","scene":[{"id":"a","text":"\"Great question, here's how it works\"","trick":false},{"id":"b","text":"\"We don't talk about dirty things like that\"","trick":true},{"id":"c","text":"\"Everyone's body changes; it's healthy\"","trick":false},{"id":"d","text":"\"You're disgusting for even asking\"","trick":true},{"id":"e","text":"\"You can ask me anything, anytime\"","trick":false}],"why":"\"Dirty things\" and \"you're disgusting\" shame a child for asking and send them elsewhere; the others keep the door open.","relearn":"Welcoming a body question keeps the door open; shaming it sends a child to peers and the feed.","persona":"any","source":"spot the shame lines"},
  {"id":"tk-1213","cat":"middle-years","type":"spot","hook":"Spot the two online habits that put a pre-teen at risk.","scene":[{"id":"a","text":"Telling you about a creepy message","trick":false},{"id":"b","text":"Sending a stranger their home address","trick":true},{"id":"c","text":"Keeping accounts private","trick":false},{"id":"d","text":"Agreeing to meet an online 'friend' alone","trick":true},{"id":"e","text":"Asking before downloading an app","trick":false}],"why":"Sharing an address and meeting a stranger alone are the real risks; telling you, staying private and asking first are healthy.","relearn":"Sharing personal info with, or meeting, online strangers are the risks to address.","persona":"Vikram","source":"spot the online risks"},
  {"id":"tk-1214","cat":"middle-years","type":"spot","hook":"Spot the two reactions that would teach a child to hide scary online content next time.","scene":[{"id":"a","text":"\"Thank you for showing me\"","trick":false},{"id":"b","text":"Shouting and snatching the phone away","trick":true},{"id":"c","text":"\"Let's look at it together calmly\"","trick":false},{"id":"d","text":"\"You're banned from the internet now\"","trick":true},{"id":"e","text":"\"You did the right thing telling me\"","trick":false}],"why":"Shouting/snatching and a blanket ban punish the telling, so a child hides it next time; thanks and calm keep them reporting.","relearn":"Punishing a child for reporting teaches them to hide it; thank them instead.","persona":"Vikram","source":"spot the silencing reactions"},
  {"id":"tk-1215","cat":"middle-years","type":"spot","hook":"Spot the two myths a parent should never pass on about pre-teen puberty.","scene":[{"id":"a","text":"Prepare before the changes begin","trick":false},{"id":"b","text":"\"Wait until puberty starts to explain it\"","trick":true},{"id":"c","text":"Periods and wet dreams are normal","trick":false},{"id":"d","text":"\"Only girls need to know about periods\"","trick":true},{"id":"e","text":"All children learn about everyone's puberty","trick":false}],"why":"\"Wait until it starts\" and \"only girls need to know\" are the myths; preparing early and teaching everyone are the truths.","relearn":"Prepare early and teach every child about everyone's puberty; don't wait or split it by gender.","persona":"any","source":"spot the puberty myths"},
  {"id":"tk-1216","cat":"middle-years","type":"spot","hook":"Spot the two replies that would scare a child about a normal body change.","scene":[{"id":"a","text":"\"Periods are normal; I'll help you\"","trick":false},{"id":"b","text":"\"Something must be wrong with you\"","trick":true},{"id":"c","text":"\"Wet dreams happen; nothing's wrong\"","trick":false},{"id":"d","text":"\"That's shameful, don't tell anyone\"","trick":true},{"id":"e","text":"\"Everyone's body grows differently\"","trick":false}],"why":"\"Something's wrong with you\" and \"that's shameful\" frighten and shame; the others name the change as normal and supported.","relearn":"Name body changes as normal and supported; never frame them as wrong or shameful.","persona":"any","source":"spot the scary replies"},
  {"id":"tk-1217","cat":"middle-years","type":"spot","hook":"Spot the two first-phone setups that leave a pre-teen exposed.","scene":[{"id":"a","text":"Agreeing screen-time limits together","trick":false},{"id":"b","text":"Letting them follow any stranger back","trick":true},{"id":"c","text":"Setting up block and report buttons","trick":false},{"id":"d","text":"Posting their daily location publicly","trick":true},{"id":"e","text":"A promise to tell you anything scary","trick":false}],"why":"Following strangers and public location expose a child; shared limits, block/report tools and an open promise protect them.","relearn":"Set shared limits, safety tools and an open promise; following strangers and public location expose a child.","persona":"Vikram","source":"spot the exposed setups"},
  {"id":"tk-1218","cat":"middle-years","type":"spot","hook":"Spot the two answers that would shut down a pre-teen's frank question.","scene":[{"id":"a","text":"\"Good you asked; here's the simple answer\"","trick":false},{"id":"b","text":"\"You're far too young to ask that\"","trick":true},{"id":"c","text":"\"I'm not sure, let's find out together\"","trick":false},{"id":"d","text":"\"Don't be disgusting, never ask again\"","trick":true},{"id":"e","text":"\"Great question; let's talk after dinner\"","trick":false}],"why":"\"Too young\" and \"don't be disgusting\" shut the door; answering simply, learning together or parking it warmly keep it open.","relearn":"Answer simply, find out together or park it warmly; \"too young\" or shaming shuts the door.","persona":"any","source":"spot the shutdowns"},
  {"id":"tk-1219","cat":"middle-years","type":"spot","hook":"Spot the two moves that leave a pre-teen unprepared for the changes ahead.","scene":[{"id":"a","text":"Honest heads-up before changes begin","trick":false},{"id":"b","text":"Leaving them to learn from peers and feeds","trick":true},{"id":"c","text":"An open door for any worry","trick":false},{"id":"d","text":"Saying \"you'll find out when it happens\"","trick":true},{"id":"e","text":"Pairing a first phone with safety chats","trick":false}],"why":"Leaving them to peers/feeds and \"find out when it happens\" leave a child unprepared; honest prep and an open door ready them.","relearn":"Prepare a pre-teen with honest prep and an open door, not by leaving them to peers and the feed.","persona":"any","source":"spot the unprepared moves"},
  {"id":"tk-1220","cat":"middle-years","type":"role-play","hook":"You want to prepare your daughter for her first period, calmly and warmly. You bring it up.","setup":"Open it warmly:","yourLine":[{"text":"\"Soon your body will start changing and one day you'll get a period; it's normal and I'll help you through it.\"","best":true},{"text":"\"You'll find out about all that when it happens.\""}],"relearn":"A warm, matter-of-fact heads-up makes a first period feel expected and supported, not frightening.","persona":"Divya","source":"open about periods"},
  {"id":"tk-1221","cat":"middle-years","type":"role-play","hook":"Your son asks what wet dreams are. You want to answer calmly so he isn't worried.","setup":"Answer matter-of-factly:","yourLine":[{"text":"\"That's a normal part of growing up; it happens to bodies and nothing is wrong with you.\"","best":true},{"text":"\"That's not something we talk about.\""}],"relearn":"Wet dreams are normal; a calm, matter-of-fact answer prevents needless shame.","persona":"any","source":"answer about wet dreams"},
  {"id":"tk-1222","cat":"middle-years","type":"role-play","hook":"You're handing over your child's first phone. You want to start the online-safety habit.","setup":"Set the tone as you give it:","yourLine":[{"text":"\"This comes with a deal: keep your details private, and tell me about anything that feels off.\"","best":true},{"text":"\"Here's the phone; just don't get into trouble.\""}],"relearn":"Pair a first device with simple online-safety talks, not a silent handover.","persona":"Vikram","source":"first-phone deal"},
  {"id":"tk-1223","cat":"middle-years","type":"role-play","hook":"Your child shows you a frightening video they found online. You want them to keep telling you.","setup":"Respond so they tell you again:","yourLine":[{"text":"\"Thank you for showing me, you did the right thing; let's look at it together.\"","best":true},{"text":"\"Why were you even watching that? Give me the phone.\""}],"relearn":"Thank a child for reporting scary content and talk it through; anger teaches them to hide it.","persona":"Vikram","source":"thank for showing"},
  {"id":"tk-1224","cat":"middle-years","type":"role-play","hook":"Your pre-teen seems embarrassed about their changing body. You want to normalise it warmly.","setup":"Reassure them:","yourLine":[{"text":"\"Everything happening to your body is normal and healthy, and you can ask me anything, anytime.\"","best":true},{"text":"\"You're being far too sensitive about all this.\""}],"relearn":"Warmly normalising the changes and inviting questions replaces embarrassment with reassurance.","persona":"Divya","source":"normalise the changes"},
  {"id":"tk-1225","cat":"middle-years","type":"role-play","hook":"A frank pre-teen question lands and you honestly don't know the answer.","setup":"Stay honest and open:","yourLine":[{"text":"\"That's a great question, I'm not sure, so let's find out together.\"","best":true},{"text":"\"Stop asking me things like that.\""}],"relearn":"\"Let's find out together\" is a good, honest answer; willingness beats perfect expertise.","persona":"any","source":"find out together"},
  {"id":"tk-1226","cat":"middle-years","type":"role-play","hook":"Your child worries they're developing later than their friends. You want to reassure them.","setup":"Ease the worry:","yourLine":[{"text":"\"Everyone's body changes at its own pace, there's no race, and you're right on track.\"","best":true},{"text":"\"Don't worry about silly things like that.\""}],"relearn":"Bodies change at different paces; reassuring a child eases worry and keeps them confiding.","persona":"any","source":"own pace reassurance"},
  {"id":"tk-1227","cat":"middle-years","type":"role-play","hook":"A relative gasps that you're explaining puberty 'too early'. You want to back your approach calmly.","setup":"Hold the line warmly:","yourLine":[{"text":"\"We just prepare her in advance, it's not too early, it keeps her safe and unafraid.\"","best":true},{"text":"\"Sorry, you're right, I'll stop bringing it up.\""}],"relearn":"Preparing a child for puberty keeps them safer; hold the line calmly if relatives disapprove.","persona":"Priya","source":"back the approach"},
  {"id":"tk-1260","cat":"the-teen-talks","type":"strike-rewrite","persona":"Vikram","source":"ban controls porn","hook":"\"If I just block porn on the wifi, my teen will never see it and we don't need to talk.\"","myth":{"un":"\"If I just block porn on the wifi, my teen will never see it and we don't need to talk.\"","re":"Filters help, but teens find content on friends' phones; only your honest porn-literacy talk truly prepares them.","why":"A block is a wall a curious teen walks around; understanding is what stays with them."},"relearn":"Filters help, but teens find content on friends' phones; only your honest porn-literacy talk truly prepares them."},
  {"id":"tk-1261","cat":"the-teen-talks","type":"strike-rewrite","persona":"Vikram","source":"manosphere antidote","hook":"\"Those 'alpha male' influencers my son watches are just harmless entertainment.\"","myth":{"un":"\"Those 'alpha male' influencers my son watches are just harmless entertainment.\"","re":"Much of that content quietly teaches contempt for girls and consent; your calm, honest voice is the antidote.","why":"If you stay silent, those voices become his only teachers about respect."},"relearn":"Much of that content quietly teaches contempt for girls and consent; your calm, honest voice is the antidote."},
  {"id":"tk-1262","cat":"the-teen-talks","type":"strike-rewrite","persona":"any","source":"consent not romance-killer","hook":"\"Teaching consent will make relationships awkward and unromantic for my teen.\"","myth":{"un":"\"Teaching consent will make relationships awkward and unromantic for my teen.\"","re":"Checking that both people freely want it makes closeness safer and kinder, not less romantic.","why":"Respect is what makes intimacy feel safe, never what spoils it."},"relearn":"Checking that both people freely want it makes closeness safer and kinder, not less romantic."},
  {"id":"tk-1263","cat":"the-teen-talks","type":"strike-rewrite","persona":"Vikram","source":"not too late at sixteen","hook":"\"My kid's already sixteen and dating, so it's far too late for me to start these talks.\"","myth":{"un":"\"My kid's already sixteen and dating, so it's far too late for me to start these talks.\"","re":"It's never too late; an open, non-judgemental parent still matters most to a teen, even one already dating.","why":"The door you open at sixteen still leads somewhere they'll walk through."},"relearn":"It's never too late; an open, non-judgemental parent still matters most to a teen, even one already dating."},
  {"id":"tk-1264","cat":"the-teen-talks","type":"strike-rewrite","persona":"any","source":"girls and boys both","hook":"\"Consent and respect talks are really only for parents of sons, not daughters.\"","myth":{"un":"\"Consent and respect talks are really only for parents of sons, not daughters.\"","re":"Every teen needs both: to give respect and to expect it; consent and boundaries protect daughters and sons alike.","why":"A daughter who knows her 'no' counts is as protected as a son who honours it."},"relearn":"Every teen needs both: to give respect and to expect it; consent and boundaries protect daughters and sons alike."},
  {"id":"tk-1265","cat":"the-teen-talks","type":"strike-rewrite","persona":"Vikram","source":"heartbreak worth talking","hook":"\"A teen breakup is just drama; there's nothing for me to actually talk about there.\"","myth":{"un":"\"A teen breakup is just drama; there's nothing for me to actually talk about there.\"","re":"How they treat an ex, and recover from heartbreak, is real relationship learning your steady support shapes.","why":"How a teen handles a breakup is rehearsal for every relationship after."},"relearn":"How they treat an ex, and recover from heartbreak, is real relationship learning your steady support shapes."},
  {"id":"tk-1266","cat":"the-teen-talks","type":"strike-rewrite","persona":"any","source":"sexting shame backfires","hook":"\"If my teen ever sends a risky photo, shaming them hard is what keeps them safe.\"","myth":{"un":"\"If my teen ever sends a risky photo, shaming them hard is what keeps them safe.\"","re":"Shame makes a teen hide the next mistake; staying a calm, problem-solving parent is what actually keeps them safe.","why":"A teen who fears your reaction stops telling you when they're in real trouble."},"relearn":"Shame makes a teen hide the next mistake; staying a calm, problem-solving parent is what actually keeps them safe."},
  {"id":"tk-1267","cat":"the-teen-talks","type":"strike-rewrite","persona":"Vikram","source":"privacy isn't secrecy","hook":"\"Reading my teen's chats in secret is just good parenting; I have a right to everything.\"","myth":{"un":"\"Reading my teen's chats in secret is just good parenting; I have a right to everything.\"","re":"Some privacy is healthy at this age; secret snooping, once found, costs the trust that keeps them talking to you.","why":"Trust is the thing that brings them to you; snooping spends it for nothing."},"relearn":"Some privacy is healthy at this age; secret snooping, once found, costs the trust that keeps them talking to you."},
  {"id":"tk-1268","cat":"the-teen-talks","type":"strike-rewrite","persona":"Vikram","source":"fun dad steps up","hook":"\"I'm the fun parent; the serious relationship and consent talks are my partner's job.\"","myth":{"un":"\"I'm the fun parent; the serious relationship and consent talks are my partner's job.\"","re":"A teen needs both parents askable; your fun, easy bond is exactly what makes a hard talk land lighter.","why":"Being the easy parent is a reason to do the talk, not to skip it."},"relearn":"A teen needs both parents askable; your fun, easy bond is exactly what makes a hard talk land lighter."},
  {"id":"tk-1269","cat":"the-teen-talks","type":"strike-rewrite","persona":"any","source":"one talk myth teen","hook":"\"I gave my teen one big sex talk years ago, so my job there is done.\"","myth":{"un":"\"I gave my teen one big sex talk years ago, so my job there is done.\"","re":"It's many small, evolving chats as they grow; consent and online life keep changing and need you to keep talking.","why":"Teens face new questions every year; one old talk can't answer them all."},"relearn":"It's many small, evolving chats as they grow; consent and online life keep changing and need you to keep talking."},
  {"id":"tk-1270","cat":"the-teen-talks","type":"strike-rewrite","persona":"Priya","source":"queer teen still talks","hook":"\"My teen came out as gay, so the usual consent and relationship talks don't really apply to them.\"","myth":{"un":"\"My teen came out as gay, so the usual consent and relationship talks don't really apply to them.\"","re":"Consent, respect and online safety matter for every teen; an affirmed, openly-guided child is a safer one.","why":"Every teen deserves the same words about respect, whoever they love."},"relearn":"Consent, respect and online safety matter for every teen; an affirmed, openly-guided child is a safer one."},
  {"id":"tk-1271","cat":"the-teen-talks","type":"sort","persona":"any","source":"green or red flag","hook":"Sort each dating sign your teen describes: green flag or red flag?","items":[{"id":"a","text":"Asks before posting a photo of you"},{"id":"b","text":"Checks your phone and demands passwords"},{"id":"c","text":"Respects it when you say not yet"},{"id":"d","text":"Sulks until you give in"},{"id":"e","text":"Likes your other friendships"},{"id":"f","text":"Says jealousy means real love"}],"bins":[{"id":"green","label":"Green flag","valence":"pos"},{"id":"red","label":"Red flag","valence":"neg"}],"key":{"a":"green","b":"red","c":"green","d":"red","e":"green","f":"red"},"relearn":"Asking, respecting a no and liking your friendships are green flags; controlling phones, sulking and jealousy are red."},
  {"id":"tk-1272","cat":"the-teen-talks","type":"sort","persona":"Vikram","source":"real or porn-myth","hook":"Sort what your teen might believe: a real fact about sex, or a porn-fed myth to gently correct?","items":[{"id":"a","text":"Both partners' comfort matters"},{"id":"b","text":"Real bodies look like the ones online"},{"id":"c","text":"A clear no means stop, always"},{"id":"d","text":"Pressuring is normal and expected"},{"id":"e","text":"Consent can be withdrawn anytime"},{"id":"f","text":"Roughness without asking is fine"}],"bins":[{"id":"real","label":"Real fact","valence":"pos"},{"id":"myth","label":"Porn-fed myth","valence":"neg"}],"key":{"a":"real","b":"myth","c":"real","d":"myth","e":"real","f":"myth"},"relearn":"Comfort, a respected no and withdrawable consent are real; matching online bodies, pressure and unasked roughness are myths."},
  {"id":"tk-1273","cat":"the-teen-talks","type":"sort","persona":"any","source":"keeps door open","hook":"Your teen just told you something hard. Sort each reply: keeps the door open, or slams it?","items":[{"id":"a","text":"Thanks for trusting me with this"},{"id":"b","text":"I'm disgusted, don't tell me more"},{"id":"c","text":"Let's figure this out together"},{"id":"d","text":"Wait till your father hears this"},{"id":"e","text":"You're not in trouble for telling me"},{"id":"f","text":"I always knew you'd mess up"}],"bins":[{"id":"open","label":"Keeps the door open","valence":"pos"},{"id":"slam","label":"Slams it shut","valence":"neg"}],"key":{"a":"open","b":"slam","c":"open","d":"slam","e":"open","f":"slam"},"relearn":"Thanks, working it out together and 'not in trouble' keep the door open; disgust, threats and 'I knew it' slam it."},
  {"id":"tk-1274","cat":"the-teen-talks","type":"sort","persona":"Vikram","source":"now or wait teen","hook":"Sort each teen topic: have it openly now, or it's genuinely fine to wait?","items":[{"id":"a","text":"What enthusiastic consent means"},{"id":"b","text":"Staying safe with online dating apps"},{"id":"c","text":"Picking their exact wedding date"},{"id":"d","text":"Handling porn they'll likely see"},{"id":"e","text":"Naming every future career choice"},{"id":"f","text":"How to leave a pressuring partner"}],"bins":[{"id":"now","label":"Talk now","valence":"tell"},{"id":"wait","label":"Can wait","valence":"neutral"}],"key":{"a":"now","b":"now","c":"wait","d":"now","e":"wait","f":"now"},"relearn":"Consent, app safety, porn-literacy and leaving pressure are now talks; wedding dates and far-off careers can wait."},
  {"id":"tk-1275","cat":"the-teen-talks","type":"sort","persona":"any","source":"respect or control online","hook":"Your teen shows you messages from their partner. Sort each: respectful, or a controlling sign?","items":[{"id":"a","text":"Asks how your day went"},{"id":"b","text":"Demands you reply within a minute"},{"id":"c","text":"Says have fun with your friends"},{"id":"d","text":"Guilt-trips you for being offline"},{"id":"e","text":"Sends a kind good-morning note"},{"id":"f","text":"Threatens to leave if you don't share locations"}],"bins":[{"id":"respect","label":"Respectful","valence":"pos"},{"id":"control","label":"Controlling","valence":"neg"}],"key":{"a":"respect","b":"control","c":"respect","d":"control","e":"respect","f":"control"},"relearn":"Caring questions, encouraging friends and kind notes are respectful; demanding instant replies, guilt-trips and location threats are control."},
  {"id":"tk-1276","cat":"the-teen-talks","type":"sort","persona":"Vikram","source":"my response teen disclosure","hook":"Your teen admits they sent a risky photo. Sort your possible reactions: helps, or harms?","items":[{"id":"a","text":"Stay calm and ask what happened"},{"id":"b","text":"Yell and confiscate everything in rage"},{"id":"c","text":"Help them report it being shared"},{"id":"d","text":"Tell relatives to shame them"},{"id":"e","text":"Reassure them you'll face it together"},{"id":"f","text":"Call them ruined and dirty"}],"bins":[{"id":"helps","label":"Helps","valence":"pos"},{"id":"harms","label":"Harms","valence":"neg"}],"key":{"a":"helps","b":"harms","c":"helps","d":"harms","e":"helps","f":"harms"},"relearn":"Staying calm, helping them report and facing it together help; yelling, shaming to relatives and 'ruined' harm."},
  {"id":"tk-1277","cat":"the-teen-talks","type":"sort","persona":"any","source":"facts or feelings teen","hook":"A teen asks why a friend got pregnant. Sort each part of a good reply: honest fact, or your family value?","items":[{"id":"a","text":"How contraception actually works"},{"id":"b","text":"When we believe is the right time"},{"id":"c","text":"What consent and safety mean"},{"id":"d","text":"Our hopes for your future first"},{"id":"e","text":"Where to get reliable health help"},{"id":"f","text":"Why we value commitment"}],"bins":[{"id":"fact","label":"Honest fact","valence":"neutral"},{"id":"value","label":"Family value","valence":"tell"}],"key":{"a":"fact","b":"value","c":"fact","d":"value","e":"fact","f":"value"},"relearn":"Contraception, consent and where to get help are honest facts; the right time, your hopes and commitment are values you share."},
  {"id":"tk-1278","cat":"the-teen-talks","type":"sort","persona":"Vikram","source":"listen or lecture teen","hook":"Your teen opens up about a crush. Sort each move: keeps them talking, or shuts them up?","items":[{"id":"a","text":"Ask gentle, curious questions"},{"id":"b","text":"Launch into a long warning lecture"},{"id":"c","text":"Take their feelings seriously"},{"id":"d","text":"Tease them in front of cousins"},{"id":"e","text":"Share a short, honest story of your own"},{"id":"f","text":"Forbid all crushes until they're older"}],"bins":[{"id":"talk","label":"Keeps them talking","valence":"pos"},{"id":"shut","label":"Shuts them up","valence":"neg"}],"key":{"a":"talk","b":"shut","c":"talk","d":"shut","e":"talk","f":"shut"},"relearn":"Curious questions, taking feelings seriously and a short honest story keep them talking; lecturing, teasing and forbidding shut them up."},
  {"id":"tk-1279","cat":"the-teen-talks","type":"branch","persona":"Vikram","source":"found porn history","hook":"You spot porn in your teen's browser history. What do you do?","options":[{"text":"Raise it calmly: a lot of that isn't real, so let's talk about respect","consequence":"You become the honest guide, not the algorithm.","outcome":"open","best":true},{"text":"Confront them in a rage and ban all devices","consequence":"Rage and bans teach hiding, not understanding."},{"text":"Say nothing and hope it stops","consequence":"Silence leaves the screen as their teacher."}],"debrief":"Meet discovered porn with calm honesty; rage hides it, silence cedes the lesson.","relearn":"Meet discovered porn with calm honesty, not rage or silence."},
  {"id":"tk-1280","cat":"the-teen-talks","type":"branch","persona":"any","source":"teen partner pressuring","hook":"Your teen confides their partner keeps pressuring them physically. Your move?","options":[{"text":"Say no one should pressure them, ask what they want, and offer help","consequence":"They keep talking and feel backed, not policed.","outcome":"open","best":true},{"text":"Order them to dump the partner now","consequence":"An ultimatum can make them defend the partner and hide."}],"debrief":"Back a pressured teen's agency and offer help; ultimatums push them to hide.","relearn":"Back a pressured teen's agency and offer help, rather than ordering them."},
  {"id":"tk-1281","cat":"the-teen-talks","type":"branch","persona":"Vikram","source":"first phone teen","hook":"You're handing your teen their first smartphone tonight. How?","options":[{"text":"Pair it with an open chat on consent, photos and telling you anything 'off'","consequence":"The phone arrives with a guide they can return to.","outcome":"open","best":true},{"text":"Just hand it over; they'll figure it out","consequence":"No talk leaves them to learn risks the hard way."},{"text":"Load it with secret spyware, say nothing","consequence":"Secret monitoring breeds distrust once found."}],"debrief":"Pair a first phone with an open safety chat, not silence or spyware.","relearn":"Pair a first phone with an honest safety talk, not silent surveillance."},
  {"id":"tk-1282","cat":"the-teen-talks","type":"branch","persona":"any","source":"teen comes out","hook":"Your teen nervously says they're attracted to the same sex. What now?","options":[{"text":"Thank them for trusting you, say you love them, stay their askable parent","consequence":"They feel safe and stay close to you.","outcome":"open","best":true},{"text":"Tell them it's a phase they'll outgrow","consequence":"Dismissal teaches them to stop confiding."},{"text":"Show shock and change the subject","consequence":"Shock signals it isn't safe to be honest with you."}],"debrief":"Meet a coming-out with love and an open door; dismissal or shock pushes them away.","relearn":"Meet a teen coming out with love and openness, not dismissal or shock."},
  {"id":"tk-1283","cat":"the-teen-talks","type":"branch","persona":"Vikram","source":"teen says know everything","hook":"Your teen insists they 'know everything' about sex and won't hear you. What now?","options":[{"text":"Stay warm, say you're always around, drop in one honest thought","consequence":"You stay a quiet resource they'll use when ready.","outcome":"open","best":true},{"text":"Force a long lecture anyway","consequence":"Forcing a lecture makes them tune out."},{"text":"Decide they don't need you, give up","consequence":"Giving up hands the topic to their feed."}],"debrief":"Stay warm and available with a know-it-all teen; lectures or quitting close the door.","relearn":"With a know-it-all teen, stay warm; lecturing or quitting lose them."},
  {"id":"tk-1284","cat":"the-teen-talks","type":"branch","persona":"any","source":"relative shames teen","hook":"At a family lunch a relative loudly shames your teen for having a boyfriend. You?","options":[{"text":"Calmly back your teen and move the talk private, keeping their dignity","consequence":"Your teen learns you're on their side.","outcome":"open","best":true},{"text":"Join the scolding to look strict","consequence":"Piling on tells your teen you can't be trusted."}],"debrief":"Back your teen and take the talk private; joining the shaming breaks their trust.","relearn":"Back your teen against public shaming and keep talks private."},
  {"id":"tk-1285","cat":"the-teen-talks","type":"branch","persona":"Vikram","source":"teen sent risky photo","hook":"Your teen tearfully admits a private photo is being passed around. First?","options":[{"text":"Reassure them it isn't their fault, then help them report and stop the spread","consequence":"They feel safe enough to let you help.","outcome":"open","best":true},{"text":"Scream that they've ruined the family name","consequence":"Blame makes them shut down when they need you."},{"text":"Tell them to delete it, never speak of it","consequence":"Brushing it off leaves them alone with it."}],"debrief":"Reassure a teen it isn't their fault and help them act, not blame or dismiss.","relearn":"When a photo spreads, reassure your teen and help them report."},
  {"id":"tk-1286","cat":"the-teen-talks","type":"branch","persona":"any","source":"teen disagrees values","hook":"Your teen makes a relationship choice that clashes with your values. You?","options":[{"text":"Share your view once, keep the door open, and stay connected","consequence":"You keep both influence and their trust.","outcome":"open","best":true},{"text":"Issue an ultimatum: end it or else","consequence":"Ultimatums end the talk and your sway with it."},{"text":"Secretly try to sabotage it","consequence":"Sabotage, once found, breaks trust for good."}],"debrief":"Share your view once and stay connected; ultimatums and sabotage cost trust.","relearn":"On choices you dislike, share your view and keep the door open."},
  {"id":"tk-1287","cat":"the-teen-talks","type":"match","persona":"any","source":"teen worry to opener","hook":"Match each teen situation to a calm opener.","pairs":[{"left":"They seem heartbroken","right":"\"Rough day? I'm here if you want to talk.\""},{"left":"They saw something explicit","right":"\"A lot of that isn't real. Let's unpack it.\""},{"left":"A partner is controlling them","right":"\"You always get a say in your own life.\""},{"left":"They're curious about dating","right":"\"Ask me anything, no judgement.\""},{"left":"They made an online mistake","right":"\"Thanks for telling me. Let's sort it.\""}],"relearn":"Heartbreak, explicit content, control, curiosity and a slip each have a calm opener that keeps a teen talking."},
  {"id":"tk-1288","cat":"the-teen-talks","type":"match","persona":"Vikram","source":"myth to truth teen","hook":"Match each thing your teen picks up online to the honest truth you can offer.","pairs":[{"left":"Real bodies look like porn","right":"\"Most of that is edited and performed.\""},{"left":"Jealousy proves love","right":"\"Trust, not control, is love.\""},{"left":"A no can be worn down","right":"\"A no means stop, every time.\""},{"left":"Pleasure is one-sided","right":"\"Both people's comfort matters.\""},{"left":"Asking ruins the mood","right":"\"Checking in is part of respect.\""}],"relearn":"Edited bodies, jealousy, worn-down nos, one-sided pleasure and asking-ruins-it each have an honest truth to counter."},
  {"id":"tk-1289","cat":"the-teen-talks","type":"match","persona":"any","source":"reaction to repair","hook":"You reacted badly to a teen's question. Match each fumble to the repair.","pairs":[{"left":"You snapped 'too young'","right":"\"Sorry I shut you down. Ask me again.\""},{"left":"You looked shocked and froze","right":"\"That surprised me, but I'm glad you asked.\""},{"left":"You lectured instead of listening","right":"\"I talked over you. Tell me your view.\""},{"left":"You said 'ask your mother'","right":"\"Let's figure this one out together.\""},{"left":"You laughed it off","right":"\"A real question deserves a real answer.\""}],"relearn":"Snapping, freezing, lecturing, deflecting and laughing each have a warm repair that reopens it."},
  {"id":"tk-1290","cat":"the-teen-talks","type":"match","persona":"Vikram","source":"topic to age-right line","hook":"Match each teen topic to a clear, respectful thing to say about it.","pairs":[{"left":"Consent","right":"\"Both people freely wanting it, every time.\""},{"left":"Breakups","right":"\"You can end things kindly and still be okay.\""},{"left":"Online strangers","right":"\"People online aren't always who they claim.\""},{"left":"Peer pressure","right":"\"Real friends never push you past your limits.\""},{"left":"Privacy","right":"\"Your body and choices are yours to share or not.\""}],"relearn":"Consent, breakups, online strangers, peer pressure and privacy each have a clear, respectful line a parent can offer."},
  {"id":"tk-1291","cat":"the-teen-talks","type":"match","persona":"any","source":"value to honest fact","hook":"A teen asks a hard question. Match each family value to the fact it pairs with.","pairs":[{"left":"We value commitment","right":"How contraception and safety work"},{"left":"We believe in the right time","right":"What consent really requires"},{"left":"We value respect for women","right":"How to spot a controlling partner"},{"left":"We honour your privacy","right":"Where to find reliable health info"},{"left":"We want you safe online","right":"How to spot and report grooming"}],"relearn":"Each family value pairs with an honest fact: commitment with safety, respect with spotting control."},
  {"id":"tk-1292","cat":"the-teen-talks","type":"match","persona":"Vikram","source":"controlling sign to response","hook":"Match each controlling thing a partner does to a steady thing you can say.","pairs":[{"left":"Demands constant location sharing","right":"\"Trust doesn't need a tracker.\""},{"left":"Isolates them from friends","right":"\"A partner who likes your friends is a keeper.\""},{"left":"Threatens to leave to get their way","right":"\"Love isn't a threat over you.\""},{"left":"Reads all their messages","right":"\"You're allowed private space.\""},{"left":"Blames them for the anger","right":"\"Their feelings aren't yours to manage.\""}],"relearn":"Tracking, isolating, threatening, snooping and blame-shifting each have a steady reframe to name."},
  {"id":"tk-1293","cat":"the-teen-talks","type":"match","persona":"any","source":"feeling to safe action","hook":"Match each thing your teen might be feeling to a safe next step you can offer.","pairs":[{"left":"Pressured by a partner","right":"\"You can always say not yet, or no.\""},{"left":"Ashamed of an online slip","right":"\"Mistakes are fixable. Let's act now.\""},{"left":"Confused by mixed messages online","right":"\"Let's sort what's real from what's performed.\""},{"left":"Scared by a stranger's messages","right":"\"Block, screenshot, and show me.\""},{"left":"Hurt by a breakup","right":"\"This pain is real and it does ease.\""}],"relearn":"Pressure, shame, confusion, fear and heartbreak each have a calm, safe next step a parent can offer."},
  {"id":"tk-1294","cat":"the-teen-talks","type":"reflect","persona":"any","source":"door open wider","hook":"Lensy: in the teen years the door to your child matters more, not less. Sit with that?","prompt":"What's your take?","options":["I feel it","The door stays open","Still their parent"],"affirm":"Your teen still wants a trusted adult; staying askable matters most exactly when they pull away.","relearn":"The door to your teen matters more in the teen years, not less."},
  {"id":"tk-1295","cat":"the-teen-talks","type":"reflect","persona":"Vikram","source":"antidote to algorithm","hook":"Lensy: every honest answer you give is one the algorithm doesn't get to give instead. Worth it?","prompt":"What do you think?","options":["Worth it","Be the antidote","Out-talk the feed"],"affirm":"Your calm, honest voice is the antidote to what the feed teaches; silence simply hands over the lesson.","relearn":"Your honest voice is the antidote to what the algorithm teaches a teen."},
  {"id":"tk-1296","cat":"the-teen-talks","type":"reflect","persona":"any","source":"not a perfect speech","hook":"Lensy: you don't need the perfect talk, just to be the parent they keep coming back to. Easier?","prompt":"How does that land?","options":["Easier","Just stay askable","I can do that"],"affirm":"It was never one flawless speech; being the askable, open-door parent is what truly protects a teen.","relearn":"You don't need a perfect talk, just to stay the askable parent a teen returns to."},
  {"id":"tk-1297","cat":"the-teen-talks","type":"reflect","persona":"Vikram","source":"calm beats control","hook":"Lensy: a teen who isn't scared of your reaction is a teen who'll tell you the scary stuff. See it?","prompt":"What's your read?","options":["I see it","Calm keeps them talking","Less fear, more truth"],"affirm":"When a teen doesn't fear your reaction, they bring you the hard things; calm keeps the truth coming.","relearn":"A teen unafraid of your reaction is one who tells you what really matters."},
  {"id":"tk-1298","cat":"the-teen-talks","type":"reflect","persona":"any","source":"both not either","hook":"Lensy: you get to give honest facts AND your family's values, never just one. Feel the relief?","prompt":"What do you think?","options":["Relief","Both, not either","Facts and values"],"affirm":"It's never facts-or-values; a teen can hold both: the facts to stay safe and your values to guide them.","relearn":"Give a teen honest facts and your values both, never just one."},
  {"id":"tk-1299","cat":"the-teen-talks","type":"reflect","persona":"any","source":"respect is the lesson","hook":"Lensy: the heart of every teen talk is one idea: both people always matter. Worth repeating?","prompt":"Your take?","options":["Worth it","Both always matter","That's the core"],"affirm":"Underneath consent, dating and online life sits one lesson: both people's wants and limits always matter.","relearn":"The core of every teen talk is that both people's wants and limits always matter."},
  {"id":"tk-1300","cat":"the-teen-talks","type":"reflect","persona":"Vikram","source":"fun dad can do hard","hook":"Lensy: being the easy, fun parent is exactly what lets a hard talk land gently. Reframe it?","prompt":"How does that sit?","options":["Reframed","My bond helps","I'm the right one"],"affirm":"Your easy, trusting bond is the very thing that lets a serious talk land softly; the fun parent can do this.","relearn":"Your fun, easy bond is what lets a hard teen talk land gently."},
  {"id":"tk-1301","cat":"the-teen-talks","type":"reflect","persona":"any","source":"trust over surveillance","hook":"Lensy: trust brings a teen to you; surveillance just teaches them to hide better. Notice the difference?","prompt":"What's your take?","options":["I notice","Trust over spying","Keep them coming"],"affirm":"Trust is what brings a teen to you with the truth; secret surveillance only teaches them to hide it better.","relearn":"Trust brings a teen to you; surveillance teaches them to hide."},
  {"id":"tk-1302","cat":"the-teen-talks","type":"spot","persona":"any","source":"two red flags chat","hook":"Read your teen's partner's messages. Spot the two red flags.","scene":[{"id":"a","text":"\"Hope your exams went okay today\"","trick":false},{"id":"b","text":"\"Why didn't you reply in five minutes?\"","trick":true},{"id":"c","text":"\"Have fun with your friends tonight\"","trick":false},{"id":"d","text":"\"Send your location or we're done\"","trick":true},{"id":"e","text":"\"No rush, talk whenever you're free\"","trick":false}],"why":"Demanding instant replies and threatening over location are control red flags; the others respect a teen's freedom.","relearn":"Demands for instant replies and location threats are red flags, not signs of love."},
  {"id":"tk-1303","cat":"the-teen-talks","type":"spot","persona":"Vikram","source":"two porn myths","hook":"Your teen lists 'facts' they picked up online. Spot the two myths to gently correct.","scene":[{"id":"a","text":"Both people's comfort should matter","trick":false},{"id":"b","text":"Real bodies look just like the videos","trick":true},{"id":"c","text":"A no means stop, every time","trick":false},{"id":"d","text":"Pressuring someone is just normal","trick":true},{"id":"e","text":"Consent can be taken back anytime","trick":false}],"why":"That real bodies match videos and that pressuring is normal are porn-fed myths; the rest are true and worth affirming.","relearn":"Real bodies match the screen and pressure-is-normal are myths to correct, not facts."},
  {"id":"tk-1304","cat":"the-teen-talks","type":"spot","persona":"any","source":"two shut-down replies","hook":"Your teen just confided something hard. Spot the two replies that slam the door.","scene":[{"id":"a","text":"\"Thank you for telling me this\"","trick":false},{"id":"b","text":"\"That's disgusting, stop talking\"","trick":true},{"id":"c","text":"\"You're not in trouble for being honest\"","trick":false},{"id":"d","text":"\"Wait till the whole family hears this\"","trick":true},{"id":"e","text":"\"Let's work through it together\"","trick":false}],"why":"Disgust and threatening to tell everyone slam the door; thanks, reassurance and teamwork keep it open.","relearn":"Disgust and threats to expose them slam the door a teen just opened."},
  {"id":"tk-1305","cat":"the-teen-talks","type":"spot","persona":"Vikram","source":"two grooming signs","hook":"An adult is messaging your teen online. Spot the two grooming red flags.","scene":[{"id":"a","text":"\"Let's keep this chat our little secret\"","trick":true},{"id":"b","text":"\"You can tell your parents about me anytime\"","trick":false},{"id":"c","text":"\"Send me a private photo, no one'll know\"","trick":true},{"id":"d","text":"\"We met in the open class group\"","trick":false},{"id":"e","text":"\"It's fine to block me if you're uneasy\"","trick":false}],"why":"Pushing secrecy and asking for a private photo are grooming red flags; the safe lines welcome parents and a block.","relearn":"Demands for secrecy and private photos are grooming red flags a teen should bring to you."},
  {"id":"tk-1306","cat":"the-teen-talks","type":"spot","persona":"any","source":"two pressure lines","hook":"Spot the two lines a partner uses to pressure a teen into 'yes'.","scene":[{"id":"a","text":"\"If you loved me you'd just do it\"","trick":true},{"id":"b","text":"\"We can stop anytime you want\"","trick":false},{"id":"c","text":"\"Everyone's done it, don't be a baby\"","trick":true},{"id":"d","text":"\"Only if you're completely sure\"","trick":false},{"id":"e","text":"\"Your comfort matters more to me\"","trick":false}],"why":"'If you loved me' and 'everyone's done it' are pressure tactics; the others respect a teen's right to choose.","relearn":"'If you loved me' and 'everyone's done it' are pressure tactics, never proof of love."},
  {"id":"tk-1307","cat":"the-teen-talks","type":"spot","persona":"Vikram","source":"two manosphere lies","hook":"Your son repeats lines from influencers. Spot the two lies that dishonour consent.","scene":[{"id":"a","text":"\"Girls owe you nothing for being nice\"","trick":false},{"id":"b","text":"\"A real man takes what he wants\"","trick":true},{"id":"c","text":"\"Respect means hearing a no the first time\"","trick":false},{"id":"d","text":"\"Women secretly want to be pressured\"","trick":true},{"id":"e","text":"\"Strength is controlling yourself, not others\"","trick":false}],"why":"'A real man takes what he wants' and 'women want pressure' dishonour consent; the rest model genuine respect.","relearn":"'Take what you want' and 'women want pressure' are manosphere lies, not strength."},
  {"id":"tk-1308","cat":"the-teen-talks","type":"spot","persona":"any","source":"two snooping moves","hook":"Spot the two parenting moves that break a teen's trust instead of building it.","scene":[{"id":"a","text":"Asking openly how the relationship is going","trick":false},{"id":"b","text":"Secretly reading every private chat","trick":true},{"id":"c","text":"Agreeing on reasonable phone limits together","trick":false},{"id":"d","text":"Installing hidden spyware on their phone","trick":true},{"id":"e","text":"Keeping the door open without judgement","trick":false}],"why":"Secret chat-reading and hidden spyware break trust once found; open questions and shared limits build it.","relearn":"Secret snooping and hidden spyware break the trust that keeps a teen talking to you."},
  {"id":"tk-1309","cat":"the-teen-talks","type":"role-play","persona":"Vikram","source":"porn calmly","hook":"Your teen asks if what they saw in a video is 'how it really is'. Stay calm.","setup":"Answer with honest porn-literacy:","yourLine":[{"text":"\"Good that you asked. A lot of that is performed and edited. Real intimacy is about both people and respect.\"","best":true},{"text":"\"You shouldn't be watching that filth at your age. We're not discussing it.\""}],"relearn":"Meeting a porn question with calm honesty keeps you the trusted source over the screen."},
  {"id":"tk-1310","cat":"the-teen-talks","type":"role-play","persona":"any","source":"heartbreak support","hook":"Your teen is crying after a breakup. You want to support, not minimise.","setup":"Say something that lets them grieve:","yourLine":[{"text":"\"I'm so sorry. This really hurts, and I'm right here. We can just sit with it.\"","best":true},{"text":"\"It's puppy love, you'll forget them by next week. Stop crying.\""}],"relearn":"Taking a teen's heartbreak seriously, without minimising it, keeps you their safe place."},
  {"id":"tk-1311","cat":"the-teen-talks","type":"role-play","persona":"Vikram","source":"consent in words","hook":"Your teen asks what 'consent' actually means in practice. Make it concrete.","setup":"Put it plainly:","yourLine":[{"text":"\"It means both people freely want it, every time, and anyone can change their mind and stop.\"","best":true},{"text":"\"It's complicated grown-up stuff, don't worry about it yet.\""}],"relearn":"Explaining consent plainly, as both people freely wanting it every time, gives a teen a clear protective rule."},
  {"id":"tk-1312","cat":"the-teen-talks","type":"role-play","persona":"any","source":"partner pressure script","hook":"Your teen says their partner keeps pushing them to do more than they want. Back them.","setup":"Give them their words back:","yourLine":[{"text":"\"No one should pressure you, ever. 'I'm not ready' is a full sentence, and I've got your back.\"","best":true},{"text":"\"Well, maybe you're leading them on. Just sort it out yourselves.\""}],"relearn":"Affirming a teen's right to say no and offering backup keeps a pressured teen talking to you."},
  {"id":"tk-1313","cat":"the-teen-talks","type":"role-play","persona":"Vikram","source":"manosphere counter","hook":"Your son repeats an influencer's line that 'women love a man who takes charge'. Counter it warmly.","setup":"Push back without shaming him:","yourLine":[{"text":"\"I get why that sounds cool, but real strength is respect. Taking charge never means ignoring a no.\"","best":true},{"text":"\"What rubbish. Only an idiot believes those losers online.\""}],"relearn":"Countering manosphere lines warmly, without shaming your son, keeps the conversation open and teaches real respect."},
  {"id":"tk-1314","cat":"the-teen-talks","type":"role-play","persona":"any","source":"stranger online","hook":"Your teen mentions an older 'friend' online who wants to chat privately. Stay calm and curious.","setup":"Open it up, don't panic:","yourLine":[{"text":"\"Thanks for telling me. People online aren't always who they say. Let's look at this together, no trouble.\"","best":true},{"text":"\"That's it, you're banned from the internet. I knew this would happen.\""}],"relearn":"Staying calm and curious about an online stranger keeps a teen reporting risks instead of hiding them."},
  {"id":"tk-1315","cat":"the-teen-talks","type":"role-play","persona":"Vikram","source":"sexting mistake","hook":"Your teen admits they sent a private photo and now regret it. React to keep them safe.","setup":"Lead with safety, not blame:","yourLine":[{"text":"\"I'm glad you told me. You're not in trouble. Let's work out how to handle it, together.\"","best":true},{"text":"\"How could you be so stupid? You've shamed this whole family.\""}],"relearn":"Meeting a sexting mistake with safety not blame keeps a teen working the problem with you."},
  {"id":"tk-1316","cat":"the-teen-talks","type":"role-play","persona":"any","source":"both facts and values","hook":"Your teen asks straight out whether they should have sex. Give facts and your values.","setup":"Hold both, don't dodge:","yourLine":[{"text":"\"Here's how to stay safe if you do, and here's what we believe about waiting. Both matter; it's your call to make well.\"","best":true},{"text":"\"Absolutely not, end of discussion. Don't ask me things like that.\""}],"relearn":"Answering a big question with honest facts and your values, not a shutdown, is what truly protects a teen."},
  {"id":"tk-1317","cat":"the-teen-talks","type":"role-play","persona":"Vikram","source":"stay askable eye-roll","hook":"Your teen rolls their eyes and says 'ugh, not another talk'. Keep the door open lightly.","setup":"Stay easy, not pushy:","yourLine":[{"text":"\"Fair enough, no lecture. Just know I'm always around if anything ever comes up.\"","best":true},{"text":"\"You'll sit here and listen whether you like it or not.\""}],"relearn":"Staying light and available with an eye-rolling teen keeps you a resource without forcing a lecture."},
  {"id":"tk-1318","cat":"the-teen-talks","type":"role-play","persona":"any","source":"repair a fumble","hook":"Yesterday you snapped 'you're too young' at your teen's question. Go back and repair it.","setup":"Reopen the door yourself:","yourLine":[{"text":"\"I'm sorry I brushed you off yesterday. That was a real question. Ask me again, I'm listening now.\"","best":true},{"text":"\"Let's just both pretend yesterday didn't happen, okay?\""}],"relearn":"Going back to repair a fumbled answer models honesty and shows a teen the door is genuinely always open."},
  {"id":"tk-1319","cat":"the-teen-talks","type":"role-play","persona":"Priya","source":"affirm queer teen","hook":"Your teen quietly says they think they might be bisexual. Affirm and stay their parent.","setup":"Lead with love:","yourLine":[{"text":"\"Thank you for trusting me. I love you exactly as you are, and I'm here for all of it, always.\"","best":true},{"text":"\"You're confused, it's just a phase. Let's not tell anyone about this.\""}],"relearn":"Affirming a teen who shares their identity keeps them safe and close; dismissal teaches them to stop confiding."},
  {"id":"tk-1351","cat":"tools-and-help","type":"strike-rewrite","hook":"\"The school's sex-ed class means I don't need to say anything at home.\"","myth":{"un":"The school's sex-ed class means I don't need to say anything at home.","re":"School lessons help, but your everyday voice and values are the tool a class can't replace; do both.","why":"Home talks and school lessons work together, not instead."},"relearn":"A school class helps but doesn't replace your voice; your everyday talks and values are tools no class can give.","persona":"any","source":"school plus home"},
  {"id":"tk-1352","cat":"tools-and-help","type":"strike-rewrite","hook":"\"A good book left in their room does the whole job for me.\"","myth":{"un":"A good book left in their room does the whole job for me.","re":"A book is a useful tool, but your willingness to talk about it is what makes it land; pair the book with a chat.","why":"A book opens the topic; your conversation seals it."},"relearn":"A book is a helpful tool, but pairing it with your willingness to talk is what makes it work; don't rely on it alone.","persona":"Divya","source":"book plus talk"},
  {"id":"tk-1353","cat":"tools-and-help","type":"strike-rewrite","hook":"\"If I fumbled one answer, I've lost my chance and shouldn't try again.\"","myth":{"un":"If I fumbled one answer, I've lost my chance and shouldn't try again.","re":"You can always go back and repair a fumble; doing so models honesty and shows the door is genuinely open.","why":"A repaired fumble teaches more than a perfect answer."},"relearn":"A fumbled answer isn't the end; you can go back and repair it, which models honesty and reopens the door.","persona":"Divya","source":"repair not lose"},
  {"id":"tk-1354","cat":"tools-and-help","type":"strike-rewrite","hook":"\"These talks are the mother's job; fathers don't need to be involved.\"","myth":{"un":"These talks are the mother's job; fathers don't need to be involved.","re":"A child gains when both parents are askable; a second calm, open door doubles their trusted support.","why":"Two askable parents are stronger than one."},"relearn":"These talks aren't only a mother's job; when both parents stay askable, a child gains a second trusted door.","persona":"Vikram","source":"both parents"},
  {"id":"tk-1355","cat":"tools-and-help","type":"strike-rewrite","hook":"\"My child never asks, so there's clearly nothing I need to bring up.\"","myth":{"un":"My child never asks, so there's clearly nothing I need to bring up.","re":"A child who never asks may have learned it's unwelcome; gently opening the topic yourself is a key tool.","why":"Silence isn't 'no questions'; it can mean a closed door."},"relearn":"A child not asking may mean the door feels closed; gently raising topics yourself is a tool you can use.","persona":"any","source":"open it yourself"},
  {"id":"tk-1356","cat":"tools-and-help","type":"strike-rewrite","hook":"\"Worrying about my child's safety is overreacting; I should just let it go.\"","myth":{"un":"Worrying about my child's safety is overreacting; I should just let it go.","re":"A safety worry is worth taking seriously; seek guidance from Be the Safe Adult and Childline 1098 rather than brushing it off.","why":"Acting on a worry is care, not overreaction."},"relearn":"A safety worry is never overreacting; take it seriously and seek guidance, routing to Be the Safe Adult and Childline 1098.","persona":"Meena","source":"take it seriously"},
  {"id":"tk-1357","cat":"tools-and-help","type":"strike-rewrite","hook":"\"There's a single right script that works for every child and every age.\"","myth":{"un":"There's a single right script that works for every child and every age.","re":"Each age has its own headline focus; you fit the words to the child in front of you, not one fixed script.","why":"Age-right beats one-size-fits-all."},"relearn":"No single script fits every child; each age has its own focus, so you tune the words to the child in front of you.","persona":"any","source":"age-right words"},
  {"id":"tk-1358","cat":"tools-and-help","type":"branch","hook":"You want a calm moment to bring up a tricky topic, not a tense face-to-face.","options":[{"text":"Use a relaxed side-by-side moment, like a car ride or a walk","consequence":"The low pressure helps your child open up.","outcome":"sidebyside","best":true},{"text":"Sit them down for a formal, eye-to-eye interrogation","consequence":"A formal sit-down makes a child clam up."}],"debrief":"Pick a relaxed side-by-side moment, like a car ride, rather than a tense formal sit-down.","relearn":"A side-by-side moment, like a car ride, lowers pressure and helps a child talk; a formal sit-down shuts it down.","persona":"Vikram","source":"low-pressure moment"},
  {"id":"tk-1359","cat":"tools-and-help","type":"branch","hook":"A TV scene opens a natural chance to talk about consent or relationships.","options":[{"text":"Use it calmly: 'What do you make of how they treated her?'","consequence":"An everyday cue becomes an easy talk.","outcome":"teachable","best":true},{"text":"Switch the channel fast and say nothing","consequence":"Switching away silently wastes an easy opening."}],"debrief":"Use everyday cues, like a TV scene, as natural openings, rather than switching away in silence.","relearn":"Everyday cues like a TV scene are natural openings to talk; switching away silently wastes the chance.","persona":"any","source":"teachable moment"},
  {"id":"tk-1360","cat":"tools-and-help","type":"branch","hook":"Your child asks a question you genuinely don't know the answer to.","options":[{"text":"Say 'good question, let's find a reliable answer together'","consequence":"You model honesty and finding good information.","outcome":"findout","best":true},{"text":"Make up an answer so you don't look unsure","consequence":"Inventing an answer risks teaching them wrong."}],"debrief":"Admit you don't know and find a reliable answer together, rather than inventing one.","relearn":"'Let's find out together' models honesty and good information-finding; making one up risks teaching wrong facts.","persona":"Vikram","source":"find out together"},
  {"id":"tk-1361","cat":"tools-and-help","type":"branch","hook":"You and your co-parent disagree on how much to tell your child now.","options":[{"text":"Agree a shared, age-right line privately, then talk to them","consequence":"Your child gets one calm, consistent message.","outcome":"aligned","best":true},{"text":"Argue about it in front of your child","consequence":"Arguing in front of them makes the topic feel unsafe."}],"debrief":"Agree a shared, age-right line with your co-parent privately, rather than arguing in front of your child.","relearn":"Agree a shared, age-right line privately so a child gets one calm message; don't argue in front of them.","persona":"any","source":"shared line"},
  {"id":"tk-1362","cat":"tools-and-help","type":"branch","hook":"Your child mentions a friend who hinted an adult is scaring them.","options":[{"text":"Take it seriously; seek guidance via Be the Safe Adult and Childline 1098","consequence":"You act on a possible warning sign.","outcome":"route","best":true},{"text":"Tell your child not to get involved","consequence":"Telling them to stay out can leave harm unaddressed."}],"debrief":"Take a worry about another child seriously and seek guidance via Be the Safe Adult and Childline 1098.","relearn":"If a child hints another child is harmed, take it seriously and seek guidance via Be the Safe Adult and Childline 1098.","persona":"Meena","source":"route a worry"},
  {"id":"tk-1363","cat":"tools-and-help","type":"branch","hook":"You snapped at your child's question yesterday and they've gone quiet.","options":[{"text":"Go back: 'I was short with you yesterday, sorry, ask me again'","consequence":"Repairing reopens the door.","outcome":"repair","best":true},{"text":"Pretend it never happened and hope they forget","consequence":"Pretending it didn't happen leaves the door closed."}],"debrief":"Go back and repair a snapped-at moment; it reopens the door and shows mistakes can be fixed.","relearn":"Going back to repair after you snapped reopens the door and shows mistakes are fixable; pretending leaves it shut.","persona":"Divya","source":"go back and repair"},
  {"id":"tk-1364","cat":"tools-and-help","type":"branch","hook":"A grandparent at home disapproves of you talking to your child about bodies.","options":[{"text":"Kindly hold your line; keep your child's safety facts in place","consequence":"Your child keeps what protects them.","outcome":"holdline","best":true},{"text":"Drop the talks to keep the peace at home","consequence":"Dropping the talks for peace leaves them exposed."}],"debrief":"Kindly hold your line on your child's safety facts even when a grandparent disapproves.","relearn":"Kindly keep your child's safety facts in place even if a grandparent disapproves; dropping them for peace leaves a child exposed.","persona":"any","source":"kindly hold the line"},
  {"id":"tk-1365","cat":"tools-and-help","type":"branch","hook":"Your teen asks where they can read trustworthy information for themselves.","options":[{"text":"Point them to a reliable, age-right source; offer to read it together","consequence":"They get good information and a safe co-reader.","outcome":"reliable","best":true},{"text":"Tell them to just search online and figure it out","consequence":"'Just search online' can hand them distortion."}],"debrief":"Point a teen to a reliable, age-right source and offer to explore it together.","relearn":"Point a teen to a reliable, age-right source and offer to read it together, not a blind online search.","persona":"Vikram","source":"reliable source"},
  {"id":"tk-1366","cat":"tools-and-help","type":"match","hook":"Match each parent's hard moment to the tool that helps.","pairs":[{"left":"You freeze on a sudden question","right":"A simple script you readied earlier"},{"left":"You don't know the answer","right":"'Let's find out together' and a good source"},{"left":"You snapped and regret it","right":"Go back and repair the moment"},{"left":"Something said worries you","right":"Be the Safe Adult and Childline 1098"},{"left":"Your co-parent feels left out","right":"Invite them to be askable too"}],"relearn":"Each hard moment has a tool: a script, finding out together, repair, the safeguarding route, or a co-parent.","persona":"any","source":"moment to tool"},
  {"id":"tk-1367","cat":"tools-and-help","type":"match","hook":"Match each age to a ready first-line to keep handy.","pairs":[{"left":"A curious four-year-old","right":"'That's the proper name, like elbow.'"},{"left":"A pre-teen before puberty","right":"'Your body will change soon; that's normal.'"},{"left":"A teen on relationships","right":"'No judgement; you can always ask me.'"},{"left":"Any child, after you fumbled","right":"'I didn't answer well; let's talk now.'"},{"left":"A child who shares a scary thing","right":"'Thank you for telling me, you're safe.'"}],"relearn":"Each age has a first-line: proper names, normalising changes, no-judgement for teens, repair, thanking a disclosure.","persona":"any","source":"ready first-lines"},
  {"id":"tk-1368","cat":"tools-and-help","type":"match","hook":"Match each parenting goal to the everyday habit that builds it.","pairs":[{"left":"Stay your child's go-to source","right":"Answer calmly, every time"},{"left":"Make hard questions easier","right":"Welcome the easy ones warmly first"},{"left":"Keep talks low-pressure","right":"Chat side-by-side, in the car or kitchen"},{"left":"Show the door is always open","right":"Repair it openly when you get one wrong"},{"left":"Cover the right things in time","right":"Follow the age-by-age headline focus"}],"relearn":"Habits build the goals: calm answers, welcoming small questions, side-by-side chats, open repair, and an age-by-age focus.","persona":"any","source":"goal to habit"},
  {"id":"tk-1369","cat":"tools-and-help","type":"match","hook":"Match each real India worry to a calm, doable response.","pairs":[{"left":"'Log kya kahenge if I teach this?'","right":"Your child's safety comes before opinions"},{"left":"'My elders never told me anything'","right":"You can give what you never got"},{"left":"'I'll say the wrong thing'","right":"Repair it; an honest fix beats silence"},{"left":"'I'm too embarrassed'","right":"Start with one small, factual sentence"},{"left":"'No time in our busy home'","right":"Use car rides and bedtimes for tiny talks"}],"relearn":"Worries each have a response: safety over opinions, breaking the silence, repairing, starting small, tiny moments.","persona":"any","source":"worry to response"},
  {"id":"tk-1370","cat":"tools-and-help","type":"match","hook":"Match each thing a parent says to whether it opens or closes the door, and why.","pairs":[{"left":"'Great question, let's talk'","right":"Opens it: rewards coming to you"},{"left":"'You'll understand when older'","right":"Closes it: tells them not to ask"},{"left":"'I don't know, let's find out'","right":"Opens it: models honest learning"},{"left":"'We don't discuss such things'","right":"Closes it: sends them online"},{"left":"'Thanks for telling me, you're safe'","right":"Opens it: makes telling feel safe"}],"relearn":"Welcoming, honest, reassuring lines open the door; 'you're too young' and 'we don't discuss that' close it.","persona":"any","source":"open or close"},
  {"id":"tk-1371","cat":"tools-and-help","type":"match","hook":"Match each child age to the safe route or support that fits a worry.","pairs":[{"left":"Any child says someone hurt them","right":"Stay calm, believe them, call Childline 1098"},{"left":"You need guidance on a safety worry","right":"Be the Safe Adult (g69)"},{"left":"An emergency right now","right":"112"},{"left":"You fumbled and want a redo","right":"Go back and repair the talk"},{"left":"You feel alone in the talks","right":"Invite your co-parent to be askable too"}],"relearn":"Match the route: Childline 1098 if a child was hurt, Be the Safe Adult for guidance, 112 in an emergency, repair, or a co-parent.","persona":"any","source":"route to support"},
  {"id":"tk-1372","cat":"tools-and-help","type":"match","hook":"Match each ready script to the question it answers calmly.","pairs":[{"left":"'Where do babies come from?'","right":"A simple, true answer at their level"},{"left":"'What's a period?'","right":"'A normal, healthy sign of growing up'"},{"left":"'What does that rude word mean?'","right":"Define it plainly, then share your view"},{"left":"'Is what I saw online real?'","right":"'A lot of it isn't; let's talk about what is'"},{"left":"'Can I say no to a hug?'","right":"'Yes, your body is yours'"}],"relearn":"Questions each have a script: a simple true answer, normalising periods, plain definitions, porn-literacy, 'your body is yours'.","persona":"any","source":"script to question"},
  {"id":"tk-1373","cat":"tools-and-help","type":"match","hook":"Match each part of the parent's kit to what it does.","pairs":[{"left":"Be askable","right":"Keeps your child bringing questions to you"},{"left":"Keep it age-right","right":"Makes each answer land at their level"},{"left":"Give facts and your values","right":"Offers safety and your guidance together"},{"left":"Route real worries to help","right":"Gets a child support when safety's at risk"},{"left":"Repair your fumbles","right":"Shows the door is genuinely always open"}],"relearn":"The kit: be askable, keep it age-right, give facts and values, route real worries to help, and repair fumbles, each doing its own job.","persona":"any","source":"the kit"},
  {"id":"tk-1374","cat":"tools-and-help","type":"match","hook":"Match each 'I can't because...' to the reframe that frees a parent to start.","pairs":[{"left":"'I'm not an expert'","right":"Learn alongside; willingness is enough"},{"left":"'I had one bad attempt'","right":"Repair it; the door reopens any time"},{"left":"'It's the school's job'","right":"Your voice is what school can't give"},{"left":"'My child never asks'","right":"Gently open the topic yourself"},{"left":"'Too late, they're teens'","right":"The door matters more in the teen years"}],"relearn":"Every 'I can't' has a reframe: learn alongside, repair, your voice matters, open it yourself, never too late.","persona":"any","source":"reframe to start"},
  {"id":"tk-1375","cat":"tools-and-help","type":"match","hook":"Match each everyday opening to the topic it makes easy to raise.","pairs":[{"left":"A relative's new baby","right":"Where babies come from, simply"},{"left":"A wedding in the family","right":"Relationships, consent and respect"},{"left":"A news story about online scams","right":"Online safety and telling you about 'off' things"},{"left":"A cousin starting her period","right":"Periods as a normal sign of growing up"},{"left":"A film about a crush","right":"Feelings, boundaries and saying no"}],"relearn":"Everyday life offers openings: a new baby, a wedding, online-scam news, a cousin's period, or a film each makes a topic easy.","persona":"any","source":"opening to topic"},
  {"id":"tk-1376","cat":"tools-and-help","type":"match","hook":"Match each sign you're becoming more askable to the move that builds it.","pairs":[{"left":"They bring you the small stuff","right":"You stayed calm last time"},{"left":"They tell you scary online things","right":"You thanked them, not punished"},{"left":"They ask the awkward questions","right":"You answered earlier ones without shame"},{"left":"They come back after a misstep","right":"You went back and repaired it"},{"left":"They trust your facts over the feed","right":"You gave honest answers before"}],"relearn":"You grow more askable by staying calm, thanking disclosures, answering without shame, repairing, and honest answers.","persona":"any","source":"sign to move"},
  {"id":"tk-1377","cat":"tools-and-help","type":"sort","hook":"Sort each move: keeps you askable, or quietly closes the door?","items":[{"id":"a","text":"Answering calmly, every time"},{"id":"b","text":"Reacting with anger or panic"},{"id":"c","text":"Going back to repair a fumble"},{"id":"d","text":"Saying 'you're too young' to dodge it"},{"id":"e","text":"Thanking them for a hard question"},{"id":"f","text":"Mocking a question as silly"}],"bins":[{"id":"askable","label":"Keeps you askable","valence":"pos"},{"id":"closes","label":"Closes the door","valence":"neg"}],"key":{"a":"askable","b":"closes","c":"askable","d":"closes","e":"askable","f":"closes"},"relearn":"Calm answers, repair and thanking hard questions keep you askable; anger, 'you're too young' and mockery close the door.","persona":"any","source":"askable or closes"},
  {"id":"tk-1378","cat":"tools-and-help","type":"sort","hook":"Sort each one: a real tool in the parent's kit, or a myth that holds you back?","items":[{"id":"a","text":"A few ready, age-right scripts"},{"id":"b","text":"'I must be an expert first'"},{"id":"c","text":"Learning alongside your child"},{"id":"d","text":"'One book does the whole job'"},{"id":"e","text":"The safeguarding route for real worries"},{"id":"f","text":"'The school handles all of it'"}],"bins":[{"id":"tool","label":"Real tool","valence":"pos"},{"id":"myth","label":"Myth to drop","valence":"neg"}],"key":{"a":"tool","b":"myth","c":"tool","d":"myth","e":"tool","f":"myth"},"relearn":"Ready scripts, learning alongside and a safeguarding route are real tools; 'be an expert first', 'a book does it' and 'the school handles it' are myths.","persona":"any","source":"tool or myth"},
  {"id":"tk-1379","cat":"tools-and-help","type":"sort","hook":"Sort each worry by where it belongs: call Childline 1098, seek guidance, or just keep talking.","items":[{"id":"a","text":"A child says someone hurt them"},{"id":"b","text":"You're unsure if it's a red flag"},{"id":"c","text":"An awkward but innocent question"},{"id":"d","text":"A disclosure of ongoing abuse"},{"id":"e","text":"You worry but have no clear sign"},{"id":"f","text":"Just curious about bodies"}],"bins":[{"id":"call","label":"Call Childline 1098","valence":"tell"},{"id":"guide","label":"Seek guidance (g69)","valence":"uhoh"},{"id":"talk","label":"Keep talking","valence":"pos"}],"key":{"a":"call","b":"guide","c":"talk","d":"call","e":"guide","f":"talk"},"relearn":"A child hurt means call Childline 1098; an unclear worry, seek guidance (g69); ordinary curiosity, keep talking calmly.","persona":"any","source":"where it belongs"},
  {"id":"tk-1380","cat":"tools-and-help","type":"sort","hook":"Sort each habit: a sustainable everyday tool, or one that burns out fast?","items":[{"id":"a","text":"Tiny talks at bedtime or in the car"},{"id":"b","text":"One long, scheduled lecture a year"},{"id":"c","text":"Answering questions as they come up"},{"id":"d","text":"Waiting till you feel fully expert"},{"id":"e","text":"Using everyday cues to start"},{"id":"f","text":"Cramming everything into one talk"}],"bins":[{"id":"sustain","label":"Sustainable tool","valence":"pos"},{"id":"burns","label":"Burns out","valence":"neg"}],"key":{"a":"sustain","b":"burns","c":"sustain","d":"burns","e":"sustain","f":"burns"},"relearn":"Tiny everyday talks, answering as questions arise and using cues are sustainable; one yearly lecture, waiting to feel expert and cramming burn out.","persona":"any","source":"sustainable or burns"},
  {"id":"tk-1381","cat":"tools-and-help","type":"sort","hook":"Sort each response to 'I don't know the answer': a good tool, or one to avoid?","items":[{"id":"a","text":"'Let's find a reliable answer together'"},{"id":"b","text":"Making up an answer to look sure"},{"id":"c","text":"'Good question, give me a day to check'"},{"id":"d","text":"'Stop asking me things like that'"},{"id":"e","text":"Looking it up with them in a good source"},{"id":"f","text":"Pretending you didn't hear"}],"bins":[{"id":"good","label":"Good move","valence":"pos"},{"id":"avoid","label":"Avoid it","valence":"neg"}],"key":{"a":"good","b":"avoid","c":"good","d":"avoid","e":"good","f":"avoid"},"relearn":"Finding out together, honestly buying time and looking it up in a good source are good moves; inventing answers, snapping and ignoring are not.","persona":"Vikram","source":"i dont know move"},
  {"id":"tk-1382","cat":"tools-and-help","type":"sort","hook":"Sort each into the age its headline focus fits best.","items":[{"id":"a","text":"Correct names and safe-vs-unsafe touch"},{"id":"b","text":"Preparing for periods and wet dreams"},{"id":"c","text":"Consent and respect in relationships"},{"id":"d","text":"'You're the boss of your body'"},{"id":"e","text":"First online-safety basics"},{"id":"f","text":"Porn-literacy and the manosphere"}],"bins":[{"id":"young","label":"Early years","valence":"neutral"},{"id":"before","label":"Before puberty","valence":"neutral"},{"id":"teen","label":"Teen years","valence":"neutral"}],"key":{"a":"young","b":"before","c":"teen","d":"young","e":"before","f":"teen"},"relearn":"Correct names and body ownership are early-years; period prep and online basics come before puberty; consent and porn-literacy are teen-years.","persona":"any","source":"age focus sort"},
  {"id":"tk-1383","cat":"tools-and-help","type":"sort","hook":"Sort each move: brings your co-parent into the talks, or pushes them out?","items":[{"id":"a","text":"'Let's agree a line, then talk to them'"},{"id":"b","text":"'You always say the wrong thing'"},{"id":"c","text":"Sharing a ready script with them"},{"id":"d","text":"Doing every talk alone, resentfully"},{"id":"e","text":"'Even just being calm and askable helps'"},{"id":"f","text":"Mocking their attempt in front of the child"}],"bins":[{"id":"brings","label":"Brings them in","valence":"pos"},{"id":"pushes","label":"Pushes them out","valence":"neg"}],"key":{"a":"brings","b":"pushes","c":"brings","d":"pushes","e":"brings","f":"pushes"},"relearn":"Agreeing a line, sharing a script and 'just be calm and askable' bring a co-parent in; criticising, going it alone and mocking push them out.","persona":"any","source":"co-parent in or out"},
  {"id":"tk-1384","cat":"tools-and-help","type":"sort","hook":"Sort each: a ready, age-right script, or one to rework before you use it?","items":[{"id":"a","text":"'That's the proper name, like elbow.'"},{"id":"b","text":"'Only bad children ask about that.'"},{"id":"c","text":"'No judgement, you can always ask me.'"},{"id":"d","text":"'We never speak of such dirty things.'"},{"id":"e","text":"'Thanks for telling me, you're not in trouble.'"},{"id":"f","text":"'You'll find out the hard way one day.'"}],"bins":[{"id":"ready","label":"Ready to use","valence":"pos"},{"id":"rework","label":"Rework it","valence":"neg"}],"key":{"a":"ready","b":"rework","c":"ready","d":"rework","e":"ready","f":"rework"},"relearn":"Calm, naming and no-judgement lines are ready to use; shaming, 'we don't speak of that' and scare-lines need reworking before you use them.","persona":"any","source":"ready or rework"},
  {"id":"tk-1385","cat":"tools-and-help","type":"reflect","hook":"Lensy: the words you give your child are often the ones nobody gave you, and that's the cycle ending. Feel it?","prompt":"What's your take?","options":["Feel it","Cycle ending","Giving what I missed"],"affirm":"Handing your child the openness and words you never received is how the silence ends with you, on purpose.","relearn":"The words you give your child may be ones nobody gave you; that's the silence cycle ending with you.","persona":"any","source":"cycle ends here"},
  {"id":"tk-1386","cat":"tools-and-help","type":"reflect","hook":"Lensy: you don't need every answer ready, just the willingness to find it with them. Sit right?","prompt":"What do you think?","options":["Sits right","Willingness is enough","Learn together"],"affirm":"Being willing to learn alongside your child matters more than having every answer; your openness is the real tool.","relearn":"You don't need every answer ready; the willingness to find it with your child is the tool that counts.","persona":"Vikram","source":"willingness is the tool"},
  {"id":"tk-1387","cat":"tools-and-help","type":"reflect","hook":"Lensy: a fumbled talk you go back to repair teaches more than a perfect one ever could. Agree?","prompt":"What's your take?","options":["Agree","Repair teaches","Worth going back"],"affirm":"Going back to repair a fumble shows your child the door is genuinely open and that honesty beats perfection.","relearn":"A fumble you go back and repair teaches honesty and that the door is genuinely always open.","persona":"Divya","source":"repair teaches more"},
  {"id":"tk-1388","cat":"tools-and-help","type":"reflect","hook":"Lensy: a second calm, askable parent in the home doubles your child's trusted doors. Worth bringing them in?","prompt":"What do you think?","options":["Worth it","Two doors","Bring them in"],"affirm":"When both parents stay calm and askable, a child has two trusted doors instead of one, and that's real protection.","relearn":"A second calm, askable parent doubles a child's trusted doors; it's worth bringing your co-parent in.","persona":"any","source":"two trusted doors"},
  {"id":"tk-1389","cat":"tools-and-help","type":"reflect","hook":"Lensy: keeping a few ready scripts means a hard question meets calm, not a freeze. Useful tool?","prompt":"What's your take?","options":["Useful","No more freeze","Ready helps"],"affirm":"Readying a few simple scripts ahead of time lets a sudden hard question meet your calm instead of a panicked freeze.","relearn":"A few ready scripts mean a hard question meets your calm, not a freeze; preparing ahead is a real tool.","persona":"Divya","source":"ready beats freeze"},
  {"id":"tk-1390","cat":"tools-and-help","type":"reflect","hook":"Lensy: routing a real safety worry to help isn't failing as a parent, it's exactly the right move. Land?","prompt":"What do you think?","options":["Lands","Right move","Get them help"],"affirm":"Taking a safety worry seriously and seeking guidance via Be the Safe Adult and Childline 1098 is good parenting, not failure.","relearn":"Routing a real safety worry to Be the Safe Adult and Childline 1098 is the right move, not a parenting failure.","persona":"Meena","source":"routing is right"},
  {"id":"tk-1391","cat":"tools-and-help","type":"reflect","hook":"Lensy: the whole kit is just this, be askable, age-right, give facts and values, route real worries. Feel ready?","prompt":"What's your take?","options":["Ready","I hold the kit","Got this"],"affirm":"Being askable, age-appropriate, honest with your values, and ready to route real worries is the whole kit, and it's yours.","relearn":"The kit is simple: be askable, age-right, give facts and values, and route real worries to help; you already hold it.","persona":"any","source":"hold the kit"},
  {"id":"tk-1392","cat":"tools-and-help","type":"reflect","hook":"Lensy: tiny talks in the car or at bedtime add up to more than one big dreaded lecture ever would. Resonate?","prompt":"What do you think?","options":["Resonates","Tiny adds up","Small and steady"],"affirm":"Lots of tiny, low-pressure talks over time build more trust and safety than one big, dreaded lecture ever could.","relearn":"Tiny talks at bedtime or in the car add up to more than one dreaded lecture; small and steady is the tool.","persona":"any","source":"tiny adds up"},
  {"id":"tk-1393","cat":"tools-and-help","type":"spot","hook":"Spot the two red-flag moves that quietly close a child's door, among calm, askable ones.","scene":[{"id":"a","text":"Answering the question calmly and simply","trick":false},{"id":"b","text":"Snapping 'why would you ask that?'","trick":true},{"id":"c","text":"Thanking them for coming to you","trick":false},{"id":"d","text":"Laughing the question off as silly","trick":true},{"id":"e","text":"Saying 'good question, let's talk'","trick":false}],"why":"Snapping and laughing a question off are the red flags; they teach a child not to ask you again, unlike calm, welcoming answers.","relearn":"Snapping and mocking a question close the door; calm, welcoming, thankful answers keep a child coming to you.","persona":"any","source":"spot door-closers"},
  {"id":"tk-1394","cat":"tools-and-help","type":"spot","hook":"A child shares something worrying. Spot the two responses that fail to keep them safe.","scene":[{"id":"a","text":"Staying calm and believing them","trick":false},{"id":"b","text":"Telling them they must be exaggerating","trick":true},{"id":"c","text":"Saying 'thank you for telling me'","trick":false},{"id":"d","text":"Promising to keep it a total secret","trick":true},{"id":"e","text":"Seeking guidance via Be the Safe Adult","trick":false}],"why":"Doubting the child and promising total secrecy are the red flags.","relearn":"Doubting a child or promising secrecy fails them; stay calm, believe them, thank them and seek guidance via Be the Safe Adult.","persona":"Meena","source":"spot unsafe responses"},
  {"id":"tk-1395","cat":"tools-and-help","type":"spot","hook":"Spot the two myths that keep a parent from using the tools, among the true reassurances.","scene":[{"id":"a","text":"You can learn alongside your child","trick":false},{"id":"b","text":"You must be an expert before you start","trick":true},{"id":"c","text":"A fumble can always be repaired","trick":false},{"id":"d","text":"One bad talk means you've lost your chance","trick":true},{"id":"e","text":"Small everyday talks really do add up","trick":false}],"why":"'Be an expert first' and 'one bad talk ends it' are the myths to catch.","relearn":"'Be an expert first' and 'one fumble ends it' are myths; you can learn alongside your child, repair, and small talks add up.","persona":"Vikram","source":"spot the myths"},
  {"id":"tk-1396","cat":"tools-and-help","type":"spot","hook":"Spot the two unhelpful 'tools' a parent might reach for, among the genuinely useful ones.","scene":[{"id":"a","text":"A few simple, age-right ready scripts","trick":false},{"id":"b","text":"A scare story to frighten them into care","trick":true},{"id":"c","text":"Everyday cues like a TV scene to start","trick":false},{"id":"d","text":"Shaming them so they never ask again","trick":true},{"id":"e","text":"The safeguarding route for real worries","trick":false}],"why":"A scare story and shaming are the red flags; real tools are ready scripts, everyday cues and the safeguarding route.","relearn":"Scaring or shaming a child aren't tools; ready scripts, everyday cues and the safeguarding route are.","persona":"any","source":"spot unhelpful tools"},
  {"id":"tk-1397","cat":"tools-and-help","type":"spot","hook":"Spot the two moves that push a co-parent out of the talks, among the inviting ones.","scene":[{"id":"a","text":"Agreeing a shared, age-right line together","trick":false},{"id":"b","text":"Saying 'you always ruin these talks'","trick":true},{"id":"c","text":"Sharing a ready script with them","trick":false},{"id":"d","text":"Mocking their attempt in front of the child","trick":true},{"id":"e","text":"'Even just being calm and askable helps'","trick":false}],"why":"Criticising and mocking are the red flags that push a co-parent out.","relearn":"Criticising or mocking a co-parent pushes them out; agreeing a line, sharing a script and a warm invite bring them in.","persona":"any","source":"spot co-parent push-outs"},
  {"id":"tk-1398","cat":"tools-and-help","type":"spot","hook":"Spot the two scripts that should be reworked, among the calm, age-right ones.","scene":[{"id":"a","text":"'That's the proper name, like elbow or knee'","trick":false},{"id":"b","text":"'Only dirty-minded kids ask such things'","trick":true},{"id":"c","text":"'No judgement, you can always ask me'","trick":false},{"id":"d","text":"'You'll learn the hard way, don't ask me'","trick":true},{"id":"e","text":"'Thanks for telling me, you're not in trouble'","trick":false}],"why":"The shaming line and the 'learn the hard way' brush-off are the red flags.","relearn":"Shaming and brush-off scripts need reworking; naming plainly, 'no judgement' and 'you're not in trouble' are ready to use.","persona":"any","source":"spot scripts to rework"},
  {"id":"tk-1399","cat":"tools-and-help","type":"spot","hook":"Spot the two responses to 'I don't know' that backfire, among the honest ones.","scene":[{"id":"a","text":"'Good question, let's find a reliable answer'","trick":false},{"id":"b","text":"Making up an answer to seem sure","trick":true},{"id":"c","text":"'Give me a day, I'll check and tell you'","trick":false},{"id":"d","text":"'Stop bothering me with these questions'","trick":true},{"id":"e","text":"Looking it up together in a good source","trick":false}],"why":"Inventing an answer and snapping are the red flags to catch.","relearn":"Inventing an answer or snapping backfires; 'let's find out together', buying time honestly and a reliable source work.","persona":"Vikram","source":"spot i-dont-know backfires"},
  {"id":"tk-1400","cat":"tools-and-help","type":"spot","hook":"Spot the two unsafe moves when a worry comes up, among the protective ones.","scene":[{"id":"a","text":"Taking the worry seriously","trick":false},{"id":"b","text":"Brushing it off so you needn't deal with it","trick":true},{"id":"c","text":"Seeking guidance via Be the Safe Adult","trick":false},{"id":"d","text":"Telling the child to keep it quiet","trick":true},{"id":"e","text":"Calling Childline 1098 if a child was hurt","trick":false}],"why":"Brushing the worry off and telling a child to stay quiet are the red flags.","relearn":"Brushing off a worry or silencing a child is unsafe; take it seriously, seek guidance, and call Childline 1098 if a child was hurt.","persona":"Meena","source":"spot unsafe worry moves"},
  {"id":"tk-1401","cat":"tools-and-help","type":"role-play","hook":"Your child asks something hard and you feel the freeze coming. You reach for a ready, calm line.","setup":"Use your ready line:","yourLine":[{"text":"\"That's a good question. Let me give you a proper answer, here's the simple version.\"","best":true},{"text":"\"Uh, why do you even want to know that? Go ask someone else.\""}],"relearn":"A ready, calm line lets you answer instead of freezing or pushing your child away to ask someone else.","persona":"Divya","source":"ready line in the moment"},
  {"id":"tk-1402","cat":"tools-and-help","type":"role-play","hook":"You genuinely don't know the answer your child needs. You want to model finding out.","setup":"Model finding out:","yourLine":[{"text":"\"Honestly, I'm not sure, let's look it up together in a good source and learn it as a team.\"","best":true},{"text":"\"I'll just make something up so I don't look like I don't know.\""}],"relearn":"Finding out together models honesty and the skill of seeking good information, unlike bluffing an answer.","persona":"Vikram","source":"model finding out"},
  {"id":"tk-1403","cat":"tools-and-help","type":"role-play","hook":"You answered badly yesterday and want to go back and repair it today.","setup":"Repair it openly:","yourLine":[{"text":"\"I didn't handle your question well yesterday. I'm sorry, ask me again, I'm ready to talk properly.\"","best":true},{"text":"\"Let's just pretend you never asked me that, alright?\""}],"relearn":"Openly repairing a fumbled answer reopens the door and shows your child mistakes can be fixed.","persona":"Divya","source":"open repair"},
  {"id":"tk-1404","cat":"tools-and-help","type":"role-play","hook":"Your child shares something that worries you about their safety. You want to respond so they keep talking.","setup":"Respond safely:","yourLine":[{"text":"\"Thank you for telling me. You're not in trouble, and I'm going to get us the right help.\"","best":true},{"text":"\"Are you sure? Don't make up stories, let's not talk about this again.\""}],"relearn":"Believing a child, reassuring them and getting the right help keeps them talking; doubting them silences future disclosures.","persona":"Meena","source":"respond to a disclosure"},
  {"id":"tk-1405","cat":"tools-and-help","type":"role-play","hook":"Your co-parent says they're too awkward to handle 'the talks' and wants to leave it all to you.","setup":"Invite them in warmly:","yourLine":[{"text":"\"You don't have to be perfect, just calm and askable. Our child having two of us they trust is huge.\"","best":true},{"text":"\"Fine, sit it out, I'll carry all of this on my own then.\""}],"relearn":"Inviting a co-parent to simply be calm and askable shares the load and gives a child a second trusted door.","persona":"Vikram","source":"warm co-parent invite"},
  {"id":"tk-1406","cat":"tools-and-help","type":"role-play","hook":"A relative insists you're 'spoiling' the child by talking about bodies. You want to hold your line kindly.","setup":"Hold your line kindly:","yourLine":[{"text":"\"I hear you, but these talks keep her safer and able to tell us things. I'm going to keep them up.\"","best":true},{"text":"\"You're right, sorry, I'll stop confusing her with all that.\""}],"relearn":"Kindly holding your line keeps your child's safety facts in place, rather than apologising away the protection they give.","persona":"any","source":"hold the line kindly"},
  {"id":"tk-1407","cat":"tools-and-help","type":"role-play","hook":"Your teen asks where they can read something trustworthy. You want to point them well and stay involved.","setup":"Point and stay involved:","yourLine":[{"text":"\"Let me find you a reliable, age-right source, and I'm happy to read it with you if you want.\"","best":true},{"text":"\"Just search it online yourself, I don't want to be part of this.\""}],"relearn":"Pointing a teen to a reliable source and offering to read along keeps you involved, unlike sending them off to a blind search.","persona":"Vikram","source":"point and stay in"},
  {"id":"tk-1408","cat":"tools-and-help","type":"role-play","hook":"A natural chance to talk comes up on a long car ride. You want to use the low-pressure moment.","setup":"Use the easy moment:","yourLine":[{"text":"\"While we're driving, can I ask, is there anything about growing up you've been wondering about?\"","best":true},{"text":"\"We'll have a Serious Talk at the dining table when we get home, sit up straight.\""}],"relearn":"A relaxed side-by-side opening invites a child to share, where a formal, tense sit-down makes them clam up.","persona":"any","source":"easy car moment"},
];

